class ViewCancelled(Exception):
    pass


def current_view_cancelled(session, serial):
    if not session:
        return lambda: False
    with VIEW_SESSIONS_LOCK:
        last=VIEW_SESSIONS.get(session,0)
        advanced=serial>last
        if advanced:
            VIEW_SESSIONS[session]=serial
            VIEW_SESSIONS.move_to_end(session)
        while len(VIEW_SESSIONS)>64:
            VIEW_SESSIONS.popitem(last=False)
    if advanced and HEAT_CANCEL_FLAGS is not None:
        slot=_heat_session_slot(session)
        with HEAT_CANCEL_LOCK:
            HEAT_CANCEL_FLAGS[slot]=(HEAT_CANCEL_FLAGS[slot]+1)&0xffffffffffffffff
    def cancelled():
        with VIEW_SESSIONS_LOCK:
            return VIEW_SESSIONS.get(session)!=serial
    cancelled.heat_session=session
    return cancelled



class BoundedStream:
    def __init__(self, stream, limit=MAX_MEMBER):
        self.stream = stream
        self.limit = limit
        self.total = 0

    def read(self, n=-1):
        if n < 0:
            n = self.limit - self.total + 1
        data = self.stream.read(min(n, self.limit - self.total + 1))
        self.total += len(data)
        if self.total > self.limit:
            raise ValueError("Activity exceeds the size safety limit")
        return data


def read_exact(stream, size):
    data = stream.read(size)
    if len(data) != size:
        raise ValueError("Truncated activity file")
    return data


def keep_telemetry_sample(summary, sample):
    samples=summary.setdefault('_telemetry',[])
    stride=summary.setdefault('_telemetry_stride',1)
    index=summary.get('_telemetry_index',0)
    summary['_telemetry_index']=index+1
    if index%stride:return
    sample=[value if not isinstance(value,(int,float)) or math.isfinite(value) else None for value in sample]
    samples.append(sample)
    if len(samples)>5000:
        summary['_telemetry']=samples[::2]
        summary['_telemetry_stride']=stride*2


def store_telemetry(con, activity_id, info):
    if con.execute('SELECT 1 FROM activity_route_repairs WHERE activity_id=?',(activity_id,)).fetchone():return
    samples=info.get('_telemetry')
    if not samples:return
    payload=zlib.compress(json.dumps(samples,separators=(',',':'),allow_nan=False).encode(),6)
    if len(payload)>4*1024*1024:return
    con.execute("INSERT INTO activity_telemetry(activity_id,payload,sample_count) VALUES(?,?,?) ON CONFLICT(activity_id) DO UPDATE SET payload=excluded.payload,sample_count=excluded.sample_count",(activity_id,payload,len(samples)))


def points_fit(stream, summary=None):
    header_size = read_exact(stream, 1)[0]
    if header_size < 12 or header_size > 64:
        raise ValueError("Invalid FIT header")
    header = bytes([header_size]) + read_exact(stream, header_size - 1)
    if header[8:12] != b".FIT":
        raise ValueError("Not a FIT activity")
    remaining = struct.unpack_from("<I", header, 4)[0]
    if remaining > MAX_MEMBER:
        raise ValueError("FIT payload too large")
    definitions = {}
    record_previous = None
    record_max_speed = None
    last_record_timestamp = None
    first_stamp = last_stamp = None
    ascent = moving = 0.0
    last_altitude = None
    altitude_samples = moving_samples = 0
    sampled_temp_sum = sampled_temp_count = 0
    while remaining:
        h = read_exact(stream, 1)[0]
        remaining -= 1
        if h & 0x80:
            local = (h >> 5) & 3
            compressed_offset = h & 31
            is_definition = False
        else:
            local = h & 15
            compressed_offset = None
            is_definition = bool(h & 0x40)
        if is_definition:
            block = read_exact(stream, 5)
            remaining -= 5
            endian = ">" if block[1] else "<"
            global_number = struct.unpack(endian + "H", block[2:4])[0]
            count = block[4]
            details = read_exact(stream, count * 3)
            remaining -= count * 3
            fields = [(details[i], details[i + 1], details[i + 2]) for i in range(0, len(details), 3)]
            if h & 0x20:
                dev_count = read_exact(stream, 1)[0]
                remaining -= 1
                dev = read_exact(stream, dev_count * 3)
                remaining -= len(dev)
                fields.extend((255, dev[i + 1], dev[i + 2]) for i in range(0, len(dev), 3))
            definitions[local] = (global_number, endian, fields)
        else:
            if local not in definitions:
                raise ValueError("FIT record missing definition")
            global_number, endian, fields = definitions[local]
            record_len = sum(field[1] for field in fields)
            if record_len > remaining:
                raise ValueError("Invalid FIT record length")
            record = read_exact(stream, record_len)
            remaining -= record_len
            if global_number == 18 and summary is not None:
                at = 0
                for number, size, base in fields:
                    fmt = {1: "b", 2: "B", 4: "H", 6: "I", 5: "i"}.get(base & 31)
                    session_fields = {7: ("elapsed_seconds", 1000), 8: ("moving_seconds", 1000), 9: ("recorded_distance_m", 100), 11: ("calories_kcal", 1), 14: ("avg_speed", 1000), 15: ("max_speed", 1000), 16: ("avg_heart_rate", 1), 18: ("avg_cadence", 1), 19: ("max_cadence", 1), 10: ("total_cycles", 1), 17: ("max_heart_rate", 1), 20: ("avg_power", 1), 21: ("max_power", 1), 22: ("elevation_m", 1), 34: ("normalized_power", 1), 35: ("training_stress_score", 10), 36: ("intensity_factor", 1000), 57: ("avg_temp_c", 1), 58: ("max_temp_c", 1)}
                    if number == 5 and size == 1 and (base & 31) == 0:
                        sport_name = {1:"Run",2:"Ride",5:"Swim",11:"Walk",12:"Cross-country ski",13:"Ski",14:"Snowboard",15:"Row",16:"Mountaineering",17:"Hike",18:"Multisport",19:"Paddle",35:"Snowshoeing"}.get(record[at])
                        if sport_name and not summary.get('sport'):
                            summary['sport'] = sport_name
                    if number in session_fields and fmt and size == struct.calcsize(fmt):
                        raw = struct.unpack(endian + fmt, record[at:at + size])[0]
                        invalid = -(1 << (8*size-1)) if fmt.islower() else (1 << (8*size))-1
                        if raw != invalid and (number in (57,58) or raw >= 0):
                            name, factor = session_fields[number]
                            if number in (57,58) or raw > 0:
                                summary[name] = raw / factor
                    at += size
                continue
            if global_number == 128 and summary is not None:
                at = 0
                fields_weather = {1:("weather_temp_c",1),4:("wind_speed_mps",1000),7:("humidity_pct",1)}
                for number,size,base in fields:
                    fmt={1:"b",2:"B",4:"H",6:"I"}.get(base & 31)
                    if number in fields_weather and fmt and size==struct.calcsize(fmt):
                        raw=struct.unpack(endian+fmt,record[at:at+size])[0]
                        invalid=-(1 << (8*size-1)) if fmt.islower() else (1 << (8*size))-1
                        if raw!=invalid and (number==1 or raw>=0):
                            name,factor=fields_weather[number]
                            if name not in summary:
                                summary[name]=raw/factor
                    at+=size
                continue
            if global_number != 20:
                continue
            lat = lon = stamp = altitude = speed = hr = power = cadence = temperature = None
            pos = 0
            for number, size, base in fields:
                if number in (0, 1) and size == 4 and (base & 31) == 5:
                    value = struct.unpack(endian + "i", record[pos:pos + 4])[0]
                    if value != 2147483647:
                        if number == 0:
                            lat = value * (180.0 / 2147483648)
                        else:
                            lon = value * (180.0 / 2147483648)
                if number == 2 and size == 2 and (base & 31) == 4:
                    raw_alt = struct.unpack(endian + "H", record[pos:pos + 2])[0]
                    if raw_alt != 65535:
                        altitude = raw_alt / 5.0 - 500
                if number == 78 and size == 4 and (base & 31) == 6:
                    raw_alt = struct.unpack(endian + "I", record[pos:pos + 4])[0]
                    if raw_alt != 4294967295:
                        altitude = raw_alt / 5.0 - 500
                if number == 3 and size == 1 and (base & 31) == 2:
                    v=record[pos]
                    if v!=255:hr=v
                if number == 4 and size == 1 and (base & 31) == 2:
                    v=record[pos]
                    if v!=255:cadence=v
                if number == 7 and size == 2 and (base & 31) == 4:
                    v=struct.unpack(endian+'H',record[pos:pos+2])[0]
                    if v!=65535:power=v
                if number == 6 and size == 2 and (base & 31) == 4:
                    raw_speed = struct.unpack(endian + "H", record[pos:pos + 2])[0]
                    if raw_speed != 65535:
                        speed = raw_speed / 1000
                        if math.isfinite(speed):
                            record_max_speed = max(record_max_speed or 0, speed)
                if number == 73 and size == 4 and (base & 31) == 6:
                    raw_speed = struct.unpack(endian + "I", record[pos:pos + 4])[0]
                    if raw_speed != 4294967295:
                        speed = raw_speed / 1000
                        if math.isfinite(speed):
                            record_max_speed = max(record_max_speed or 0, speed)
                if number == 13 and size == 1 and (base & 31) == 1:
                    temperature=struct.unpack("b",record[pos:pos+1])[0]
                    if temperature == -128 or not -60 <= temperature <= 70:
                        temperature = None
                    else:
                        sampled_temp_sum+=temperature
                        sampled_temp_count+=1
                if number == 253 and size == 4 and (base & 31) == 6:
                    value = struct.unpack(endian + "I", record[pos:pos + 4])[0]
                    if value != 0xffffffff:
                        stamp = value
                pos += size
            if compressed_offset is not None and stamp is None and last_record_timestamp is not None:
                stamp = (last_record_timestamp & ~31) + compressed_offset
                if stamp < last_record_timestamp:
                    stamp += 32
            if stamp is not None:
                last_record_timestamp = stamp
            if lat is not None and lon is not None:
                if stamp is not None:
                    if first_stamp is None:
                        first_stamp = stamp
                    last_stamp = stamp
                if altitude is not None and math.isfinite(altitude) and -500 <= altitude <= 10000:
                    altitude_samples += 1
                    if last_altitude is not None:
                        rise = altitude - last_altitude
                        if .75 <= rise <= 30:
                            ascent += rise
                    last_altitude = altitude
                if record_previous is not None and stamp is not None:
                    old_lat, old_lon, old_stamp = record_previous
                    if old_stamp is not None and 0 < stamp - old_stamp <= 120:
                        distance = haversine((old_lat, old_lon), (lat, lon))
                        if .7 <= distance / (stamp - old_stamp) <= 25:
                            moving += stamp - old_stamp
                            moving_samples += 1
                record_previous = (lat, lon, stamp)
                if summary is not None and stamp is not None:
                    keep_telemetry_sample(summary, [round(FIT_EPOCH.timestamp()+stamp),round(lat,6),round(lon,6),speed,hr,power,cadence,temperature,altitude])
                yield lat, lon, stamp
    read_exact(stream, 2)
    if summary is not None:
        if first_stamp is not None:
            summary["_fit_start_utc"] = FIT_EPOCH.timestamp() + first_stamp
        if summary.get("avg_temp_c") is None and sampled_temp_count:
            summary["avg_temp_c"] = round(sampled_temp_sum/sampled_temp_count,1)
        if summary.get("max_speed") is None and record_max_speed is not None:
            summary["max_speed"] = record_max_speed
        if not summary.get("elapsed_seconds") and first_stamp is not None and last_stamp is not None and last_stamp > first_stamp:
            summary["elapsed_seconds"] = last_stamp - first_stamp
        if not summary.get("moving_seconds") and moving_samples >= 2:
            summary["moving_seconds"] = moving
            summary["moving_source"] = "track-estimate"
        if not summary.get("elevation_m") and altitude_samples >= 3 and ascent > 0:
            summary["elevation_m"] = round(ascent, 1)
            summary["elevation_source"] = "track-estimate"


def parse_track_timestamp(value):
    if not value:
        return None
    try:
        timestamp = dt.datetime.fromisoformat(value.strip().replace("Z", "+00:00"))
        if timestamp.tzinfo is None:
            timestamp = timestamp.replace(tzinfo=dt.timezone.utc)
        return (timestamp - FIT_EPOCH).total_seconds()
    except ValueError:
        return None


def summarize_track_samples(samples, summary=None):
    first = last = None
    previous = None
    last_altitude = None
    moving = ascent = 0.0
    moving_count = altitude_count = 0
    for item in samples:
        if item is None:
            previous = last_altitude = None
            yield None
            continue
        lat, lon, stamp, altitude = item[:4]
        extras=(list(item[4:8])+[None]*4)[:4]
        extras=[v if v is None or (isinstance(v,(int,float)) and math.isfinite(v)) else None for v in extras]
        if not (math.isfinite(lat) and math.isfinite(lon) and -90<=lat<=90 and -180<=lon<=180):
            previous=last_altitude=None
            continue
        if altitude is not None and not math.isfinite(altitude):altitude=None
        if stamp is not None:
            if first is None:
                first = stamp
            last = stamp
        if altitude is not None and math.isfinite(altitude):
            altitude_count += 1
            if last_altitude is not None:
                increase = altitude - last_altitude
                if .75 <= increase <= 30:
                    ascent += increase
            last_altitude = altitude
        if previous is not None and stamp is not None and previous[2] is not None:
            delta = stamp - previous[2]
            if 0 < delta <= 120:
                distance = haversine((previous[0], previous[1]), (lat, lon))
                if .7 <= distance / delta <= 25:
                    moving += delta
                    moving_count += 1
        speed=None
        if previous and stamp is not None and previous[2] is not None and 0<stamp-previous[2]<=120:
            candidate=haversine((previous[0],previous[1]),(lat,lon))/(stamp-previous[2])
            if 0<=candidate<=35:speed=round(candidate,3)
        previous = (lat, lon, stamp)
        if summary is not None and stamp is not None:
            keep_telemetry_sample(summary,[round(FIT_EPOCH.timestamp()+stamp),round(lat,6),round(lon,6),speed,*extras,altitude])
        yield lat, lon, stamp
    if summary is not None:
        if not summary.get("elapsed_seconds") and first is not None and last is not None and last > first:
            summary["elapsed_seconds"] = round(last - first)
        if not summary.get("moving_seconds") and moving_count >= 2:
            summary["moving_seconds"] = round(moving)
            summary["moving_source"] = "track-estimate"
        if not summary.get("elevation_m") and altitude_count >= 3 and ascent > 0:
            summary["elevation_m"] = round(ascent, 1)
            summary["elevation_source"] = "track-estimate"


def points_gpx(stream, summary=None):
    import xml.etree.ElementTree as ET
    def items():
        in_route = 0
        for event, element in ET.iterparse(stream, events=("start", "end")):
            tag = element.tag.rsplit("}", 1)[-1]
            if event == "start" and tag in ("trk", "rte"):
                in_route += 1
            if event == "start" and tag in ("trkseg", "rte"):
                yield None
            elif event == "end" and tag == "type" and in_route and summary is not None and not summary.get("sport"):
                activity_type = (element.text or "").strip()
                if activity_type and any(word in activity_type.casefold() for word in ('run', 'jog', 'walk', 'hik', 'trek', 'ride', 'cycl', 'bik', 'velo')):
                    summary['sport'] = activity_type[:80]
            elif event == "end" and tag in ("trkpt", "rtept"):
                try:
                    lat = float(element.attrib["lat"])
                    lon = float(element.attrib["lon"])
                    altitude = stamp = hr = power = cadence = temp = None
                    for child in element.iter():
                        field = child.tag.rsplit("}", 1)[-1]
                        if field == "ele" and child.text:
                            try:
                                altitude = float(child.text)
                            except ValueError:
                                pass
                        elif field == "time" and child.text:
                            stamp = parse_track_timestamp(child.text)
                        elif child.text and field.lower() in ('hr','heartratebpm'):
                            try:hr=float(child.text)
                            except ValueError:pass
                        elif child.text and field.lower() in ('cad','cadence'):
                            try:cadence=float(child.text)
                            except ValueError:pass
                        elif child.text and field.lower() in ('power','watts'):
                            try:power=float(child.text)
                            except ValueError:pass
                        elif child.text and field.lower() in ('atemp','temp','temperature'):
                            try:temp=float(child.text)
                            except ValueError:pass
                    yield lat, lon, stamp, altitude,hr,power,cadence,temp
                except (ValueError, KeyError):
                    pass
                element.clear()
            elif event == "end" and tag in ("trkseg", "rte"):
                element.clear()
            if event == "end" and tag in ("trk", "rte"):
                in_route = max(0, in_route - 1)
    yield from summarize_track_samples(items(), summary)


def points_tcx(stream, summary=None):
    import xml.etree.ElementTree as ET
    def items():
        for event, element in ET.iterparse(stream, events=("end",)):
            tag = element.tag.rsplit("}", 1)[-1]
            if tag == "Trackpoint":
                lat = lon = altitude = stamp = hr = power = cadence = temp = None
                for child in element.iter():
                    field = child.tag.rsplit("}", 1)[-1]
                    if field == "LatitudeDegrees" and child.text:
                        lat = float(child.text)
                    elif field == "LongitudeDegrees" and child.text:
                        lon = float(child.text)
                    elif field == "AltitudeMeters" and child.text:
                        altitude = float(child.text)
                    elif field == "Time" and child.text:
                        stamp = parse_track_timestamp(child.text)
                    elif field in ('Value','HeartRateBpm') and child.text and child.tag.endswith('Value'):
                        try:hr=float(child.text)
                        except ValueError:pass
                    elif field == 'Cadence' and child.text:
                        try:cadence=float(child.text)
                        except ValueError:pass
                    elif field == 'Watts' and child.text:
                        try:power=float(child.text)
                        except ValueError:pass
                    elif field in ('Temperature','Temp') and child.text:
                        try:temp=float(child.text)
                        except ValueError:pass
                if lat is not None and lon is not None:
                    yield lat, lon, stamp, altitude,hr,power,cadence,temp
                element.clear()
            elif tag == "Track":
                yield None
                element.clear()
            elif tag == "Activity" and summary is not None and not summary.get('sport'):
                activity_type = (element.attrib.get('Sport') or '').strip()
                if activity_type:
                    summary['sport'] = {'biking':'Ride','running':'Run','walking':'Walk','hiking':'Hike'}.get(activity_type.casefold(),activity_type[:80])
    yield from summarize_track_samples(items(), summary)

def points_kml(stream, summary=None):

    import xml.etree.ElementTree as ET
    def items():
        for event, element in ET.iterparse(BoundedStream(stream, MAP_FORMAT_LIMIT), events=('end',)):
            tag = element.tag.rsplit('}', 1)[-1]
            if tag == 'LineString':
                coordinates = next((child.text for child in element.iter() if child.tag.rsplit('}', 1)[-1] == 'coordinates'), None)
                if coordinates:
                    yield None
                    for entry in coordinates.split():
                        parts = entry.split(',')
                        if len(parts) < 2:continue
                        try:
                            lon, lat = float(parts[0]), float(parts[1])
                            altitude = float(parts[2]) if len(parts) > 2 and parts[2] else None
                            yield lat, lon, None, altitude
                        except ValueError:continue
                element.clear()
            elif tag == 'Track':
                stamps = [parse_track_timestamp(e.text) for e in element if e.tag.rsplit('}', 1)[-1] == 'when']
                positions = [e.text for e in element if e.tag.rsplit('}', 1)[-1] == 'coord']
                if positions:
                    yield None
                    for index, position in enumerate(positions):
                        try:
                            lon, lat, *alt = (float(x) for x in position.split())
                            yield lat, lon, stamps[index] if index < len(stamps) else None, alt[0] if alt else None
                        except (ValueError, AttributeError):continue
                element.clear()
    yield from summarize_track_samples(items(), summary)


def points_kmz(stream, summary=None):
    with zipfile.ZipFile(io.BytesIO(BoundedStream(stream, MAP_FORMAT_LIMIT).read())) as archive:
        options = [m for m in archive.infolist() if not m.is_dir() and m.filename.casefold().endswith('.kml')]
        if not options:raise ValueError('KMZ contains no KML track')
        if len(options) > 100:raise ValueError('KMZ contains too many KML files')
        for member in options:
            if member.file_size > MAP_FORMAT_LIMIT or (member.file_size > 1024*1024 and member.file_size > 1000*max(1,member.compress_size)):
                raise ValueError('KMZ member exceeds the safety limit')
            with archive.open(member) as kml:
                yield from points_kml(BoundedStream(kml, MAP_FORMAT_LIMIT), summary)
            yield None


def points_geojson(stream, summary=None):

    data = json.loads(BoundedStream(stream, MAP_FORMAT_LIMIT).read().decode('utf-8-sig'))
    def geometries(node, properties=None):
        if not isinstance(node, dict):return
        kind=node.get('type')
        if kind == 'FeatureCollection':
            for item in node.get('features', []):yield from geometries(item)
        elif kind == 'Feature':
            props=node.get('properties') if isinstance(node.get('properties'), dict) else {}
            if summary is not None:
                for key in ('name','title'):
                    if isinstance(props.get(key),str) and props[key].strip() and not summary.get('name'):
                        summary['name']=props[key].strip()[:300];break
                for key in ('sport','activity_type'):
                    if isinstance(props.get(key),str) and props[key].strip() and not summary.get('sport'):
                        summary['sport']=props[key].strip()[:80];break
            yield from geometries(node.get('geometry'),props)
        elif kind == 'GeometryCollection':
            for item in node.get('geometries',[]):yield from geometries(item,properties)
        elif kind in ('LineString','MultiLineString'):
            routes=[node.get('coordinates')] if kind == 'LineString' else node.get('coordinates',[])
            if not isinstance(routes,list):raise ValueError('Invalid GeoJSON coordinates')
            for route in routes:
                if not isinstance(route,list):continue
                yield None
                for point in route:
                    if not isinstance(point,list) or len(point)<2:continue
                    try:
                        lon, lat = float(point[0]), float(point[1])
                        altitude=float(point[2]) if len(point)>2 and point[2] is not None else None
                    except (ValueError,TypeError):continue
                    yield lat,lon,None,altitude
    yield from summarize_track_samples(geometries(data),summary)


GPS_CSV_LAT = ('latitude','lat','latitude_deg','latitudedegrees')
GPS_CSV_LON = ('longitude','lon','lng','long','longitude_deg','longitudedegrees')
GPS_CSV_TIME = ('timestamp','time','datetime','date_time','utc_time')
GPS_CSV_ALT = ('altitude','altitude_m','elevation','elevation_m')

def gps_csv_headers(stream):
    position=stream.tell()
    try:
        header=stream.read(8192).decode('utf-8-sig').splitlines()
        if not header:return False
        fields={f.strip().casefold() for f in next(csv.reader([header[0]]))}
        return any(key in fields for key in GPS_CSV_LAT) and any(key in fields for key in GPS_CSV_LON)
    except (UnicodeDecodeError,csv.Error):return False
    finally:stream.seek(position)


def points_gps_csv(stream, summary=None):
    def items():
        text=io.StringIO(BoundedStream(stream, MAP_FORMAT_LIMIT).read().decode('utf-8-sig'),newline='')
        rows=csv.DictReader(text)
        columns={name.strip().casefold():name for name in (rows.fieldnames or []) if name}
        def col(keys):return next((columns[key] for key in keys if key in columns),None)
        lat_key,lon_key=col(GPS_CSV_LAT),col(GPS_CSV_LON)
        if not lat_key or not lon_key:raise ValueError('GPS CSV requires latitude and longitude columns')
        time_key,alt_key=col(GPS_CSV_TIME),col(GPS_CSV_ALT)
        yield None
        for row in rows:
            try:
                lat,lon=float(row[lat_key]),float(row[lon_key])
                alt=float(row[alt_key]) if alt_key and row.get(alt_key) else None
                stamp=parse_track_timestamp(row.get(time_key)) if time_key else None
                yield lat,lon,stamp,alt
            except (ValueError,TypeError,KeyError):continue
    yield from summarize_track_samples(items(),summary)


def haversine(a, b):
    lat1, lon1 = a
    lat2, lon2 = b
    x = math.radians(lat2 - lat1)
    y = math.radians(lon2 - lon1)
    q = math.sin(x / 2) ** 2 + math.cos(math.radians(lat1)) * math.cos(math.radians(lat2)) * math.sin(y / 2) ** 2
    return 12742017.6 * math.asin(min(1.0, math.sqrt(q)))


def decode_track(stream, filename, summary=None):
    lower = filename.lower()
    stream = BoundedStream(stream)
    if lower.endswith(".gz"):
        stream = BoundedStream(gzip.GzipFile(fileobj=stream))
    if lower.endswith((".fit", ".fit.gz")):
        iterator = points_fit(stream, summary)
    elif lower.endswith((".gpx", ".gpx.gz")):
        iterator = points_gpx(stream, summary)
    elif lower.endswith(('.tcx','.tcx.gz')):
        iterator = points_tcx(stream, summary)
    elif lower.endswith(('.kml','.kml.gz')):
        iterator = points_kml(stream, summary)
    elif lower.endswith('.kmz'):
        iterator = points_kmz(stream, summary)
    elif lower.endswith(('.geojson','.geojson.gz')):
        iterator = points_geojson(stream, summary)
    elif lower.endswith('.csv'):
        iterator = points_gps_csv(stream, summary)
    else:
        raise ValueError('Unsupported GPS track format')
    packed = bytearray()
    prev = None
    remaining = 25.0
    first_stamp = None
    bbox = [90.0, 180.0, -90.0, -180.0]
    count = 0
    distance_total = 0.0
    last_emit = None

    def append(point):
        nonlocal count, last_emit
        last_emit = point
        lat, lon = point
        packed.extend(struct.pack("<ii", round(lat * 1e6), round(lon * 1e6)))
        bbox[0] = min(bbox[0], lat)
        bbox[1] = min(bbox[1], lon)
        bbox[2] = max(bbox[2], lat)
        bbox[3] = max(bbox[3], lon)
        count += 1
        if count > MAX_POINTS:
            raise ValueError("Activity has more than two million sampled points")

    for value in iterator:
        if value is None:
            if prev is not None:
                if last_emit is not None and haversine(last_emit, prev) > 0.3:
                    append(prev)
                packed.extend(struct.pack("<ii", 2147483647, 2147483647))
            prev = None
            remaining = 25.0
            continue
        lat, lon, stamp = value
        if stamp is not None and first_stamp is None:
            first_stamp = stamp
        if not (math.isfinite(lat) and math.isfinite(lon) and -85.0511 <= lat <= 85.0511 and -180 <= lon <= 180):
            continue
        current = (lat, lon)
        if prev is None:
            append(current)
            prev = current
            remaining = 25.0
            continue
        length = haversine(prev, current)
        if length > 2000.0:
            if last_emit is not None and haversine(last_emit, prev) > 0.3:
                append(prev)
            packed.extend(struct.pack("<ii", 2147483647, 2147483647))
            append(current)
            prev = current
            remaining = 25.0
            continue
        distance_total += length
        if length > 0.01:
            traveled = 0.0
            while traveled + remaining <= length + 1e-8:
                target = traveled + remaining
                ratio = min(1.0, target / length)
                append((prev[0] + (current[0] - prev[0]) * ratio,
                        prev[1] + (current[1] - prev[1]) * ratio))
                traveled = target
                remaining = 25.0
            remaining -= max(0.0, length - traveled)
        prev = current
    if prev is not None and last_emit is not None and haversine(last_emit, prev) > 0.3:
        append(prev)
    if summary is not None and first_stamp is not None:
        summary["_fit_start_utc"] = FIT_EPOCH.timestamp() + first_stamp
    if count < 2:
        return None
    start = (FIT_EPOCH + dt.timedelta(seconds=first_stamp)).date().isoformat() if first_stamp is not None else None
    return zlib.compress(bytes(packed), 6), count, bbox, start, round(distance_total)


def parse_date(value):
    if not value:
        return None
    value = value.strip()
    for pattern in ("%Y-%m-%d", "%Y-%m-%d %H:%M:%S", "%b %d, %Y, %I:%M:%S %p", "%b %d, %Y, %I:%M %p", "%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%dT%H:%M:%S%z", "%Y-%m-%d %H:%M:%S %Z"):
        try:
            return dt.datetime.strptime(value, pattern).date().isoformat()
        except ValueError:
            continue
    if len(value) >= 10 and value[4:5] == "-" and value[7:8] == "-":
        return value[:10]
    return None


def csv_number(value):
    if value is None or not str(value).strip():
        return None
    try:
        result = float(str(value).replace(",", "").strip())
        return result if math.isfinite(result) and result >= 0 else None
    except ValueError:
        return None


def csv_duration(value):
    value = str(value or "").strip()
    if ":" not in value:
        return csv_number(value)
    parts = value.split(":")
    if len(parts) not in (2, 3):
        return None
    try:
        numbers = [float(v) for v in parts]
        return sum(v * 60**i for i,v in enumerate(reversed(numbers))) if all(math.isfinite(v) and v >= 0 for v in numbers) else None
    except ValueError:
        return None


def metadata_from_csv(stream):
    text = io.TextIOWrapper(stream, encoding="utf-8-sig", errors="replace", newline="")
    reader = csv.reader(text)
    header = next(reader, None)
    if not header:
        return {}
    positions = {}
    for index, key in enumerate(header):
        positions.setdefault(re.sub(r"[^a-z0-9]", "", key.casefold()), []).append(index)

    def values(row, *names):
        for name in names:
            for index in reversed(positions.get(re.sub(r"[^a-z0-9]", "", name.casefold()), ())):
                if index < len(row) and row[index].strip():
                    yield row[index].strip()

    def cell(row, *names):
        return next(values(row, *names), "")

    def numeric(row, parser, *names):
        zero = None
        for value in values(row, *names):
            parsed = parser(value)
            if parsed is None:
                continue
            if parsed > 0:
                return parsed
            zero = parsed
        return zero

    metadata = {}
    for n, row in enumerate(reader):
        if n >= 150000:
            raise ValueError("Activity CSV exceeds the row limit")
        filename = cell(row, "Filename", "File Name", "Activity Filename", "File").replace("\\", "/").lstrip("/")
        activity_id = cell(row, "Activity ID", "Activity Id", "ActivityID", "ID")
        if not filename and not activity_id:
            continue
        info = {
            "name": cell(row, "Activity Name", "Name"),
            "sport": cell(row, "Activity Type", "Sport Type", "Type"),
            "day": parse_date(cell(row, "Activity Date", "Activity Date Local", "Date", "Start Date")),
            "recorded_distance_m": numeric(row, csv_number, "Distance (m)", "Distance", "Distance Meters"),
            "moving_seconds": numeric(row, csv_duration, "Moving Time", "Moving Time (s)", "Timer Time", "Moving Time Seconds"),
            "elapsed_seconds": numeric(row, csv_duration, "Elapsed Time", "Elapsed Time (s)"),
            "elevation_m": numeric(row, csv_number, "Elevation Gain", "Total Elevation Gain", "Total Ascent", "Elev Gain", "Elevation Gain (m)"),
            "avg_heart_rate": numeric(row, csv_number, "Average Heart Rate", "Avg Heart Rate"),
            "avg_speed": numeric(row, csv_number, "Average Speed"),
            "avg_power": numeric(row, csv_number, "Average Power", "Average Watts", "Avg Power"),
            "calories_kcal": numeric(row, csv_number, "Calories", "Calories Burned"),
            "avg_temp_c": numeric(row, csv_number, "Average Temperature", "Avg Temperature"),
            "max_temp_c": numeric(row, csv_number, "Max Temperature", "Maximum Temperature"),
            "weather_temp_c": numeric(row, csv_number, "Weather Temperature"),
            "wind_speed_mps": numeric(row, csv_number, "Wind Speed"),
            "wind_gust_mps": numeric(row, csv_number, "Wind Gust"),
            "humidity_pct": numeric(row, csv_number, "Humidity"),
            "avg_cadence": numeric(row, csv_number, "Average Cadence", "Avg Cadence"),
            "max_power": numeric(row, csv_number, "Max Watts", "Maximum Power"),
            "weather_condition": cell(row, "Weather Condition")[:120],
            "max_speed": numeric(row, csv_number, "Max Speed"),
            "bike": cell(row, "Activity Gear", "Gear Name", "Bike Name"),
            "gear_id": cell(row, "Gear ID", "Bike", "Gear"),
        }
        if info["bike"] and info["bike"].casefold() == info["gear_id"].casefold():
            info["bike"] = ""
        if info["moving_seconds"] is not None:
            info["moving_source"] = "strava"
        if info["elevation_m"] is not None:
            info["elevation_source"] = "strava"
        if filename:
            metadata[filename.casefold()] = info
            metadata[filename.rsplit("/", 1)[-1].casefold()] = info
        if activity_id:
            matched = re.search(r"\d{7,}", activity_id)
            if matched:
                metadata["id:" + matched.group()] = info
    return metadata


def gear_names_from_csv(stream):
    reader = csv.DictReader(io.TextIOWrapper(stream, encoding="utf-8-sig", errors="replace", newline=""))
    names = {}
    for count, row in enumerate(reader):
        if count >= 5000:
            raise ValueError("Gear CSV exceeds the row limit")
        normalized = {re.sub(r"[^a-z0-9]", "", key.casefold()): str(value or "").strip() for key, value in row.items() if key}
        gear_id = next((normalized[k] for k in ("bikeid", "gearid", "id") if normalized.get(k)), "")
        name = next((normalized[k] for k in ("bikename", "gearname", "name", "nickname") if normalized.get(k)), "")
        if gear_id and name:
            names[gear_id.casefold()] = name[:160]
    return names


def metadata_csv(zfile):
    options = [x for x in zfile.infolist() if x.filename.lower().endswith("activities.csv") and x.file_size < 32 * 1024 * 1024]
    if not options:
        return {}
    with zfile.open(min(options, key=lambda m: len(m.filename))) as stream:
        lookup = metadata_from_csv(stream)
    gear = {}
    for entry in zfile.infolist():
        if entry.filename.lower().endswith(("bikes.csv", "gear.csv")) and 0 < entry.file_size < 1024 * 1024:
            with zfile.open(entry) as stream:
                gear.update(gear_names_from_csv(stream))
    seen = set()
    for info in lookup.values():
        if id(info) in seen:
            continue
        seen.add(id(info))
        name = info.get("bike", "").strip()
        key = (info.get("gear_id") or "").casefold()
        if key in gear and (not name or name.casefold() == key or name.casefold() in ("unknown", "none")):
            info["bike"] = gear[key]
        elif name.casefold() in gear:
            info["bike"] = gear[name.casefold()]
    return lookup

def garmin_summary_index(zfile):
    records = []
    for entry in zfile.infolist():
        if not entry.filename.casefold().endswith("_summarizedactivities.json") or entry.file_size > 16 * 1024 * 1024:
            continue
        with zfile.open(entry) as stream:
            data = json.loads(BoundedStream(stream, 16 * 1024 * 1024).read())
        if not isinstance(data, list):
            continue
        for group in data:
            if not isinstance(group, dict):
                continue
            for row in group.get("summarizedActivitiesExport", []):
                if not isinstance(row, dict):
                    continue
                start = row.get("startTimeGmt")
                if not isinstance(start, (int, float)) or not math.isfinite(start) or start < 1e11:
                    continue
                def positive(name, scale=1):
                    value = row.get(name)
                    return value / scale if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and value > 0 else None
                local_start = row.get("startTimeLocal")
                day_stamp = local_start if isinstance(local_start, (int, float)) and math.isfinite(local_start) and local_start > 1e11 else start
                info = {
                    "name": str(row.get("name") or "")[:300],
                    "sport": str(row.get("activityType") or row.get("sportType") or "")[:80],
                    "day": dt.datetime.fromtimestamp(day_stamp / 1000, dt.timezone.utc).date().isoformat(),
                    "recorded_distance_m": positive("distance", 100),
                    "moving_seconds": positive("movingDuration", 1000),
                    "elapsed_seconds": positive("elapsedDuration", 1000),
                    "elevation_m": positive("elevationGain", 100),
                    "avg_speed": positive("avgSpeed", 10),
                    "max_speed": positive("maxSpeed", 10),
                    "calories_kcal": positive("calories"),
                    "avg_cadence": positive("avgBikeCadence"),
                    "max_temp_c": row.get("maxTemperature") if isinstance(row.get("maxTemperature"), (int, float)) and not isinstance(row.get("maxTemperature"), bool) and math.isfinite(row["maxTemperature"]) and -60 <= row["maxTemperature"] <= 70 else None,
                    "moving_source": "garmin",
                    "elevation_source": "garmin",
                }
                records.append((round(start / 1000), info))
                if len(records) > 50000:
                    raise ValueError("Garmin activity summary exceeds the safety limit")
    return sorted(records, key=lambda item: item[0])


def matching_garmin_summary(index, fit_time, distance):
    if not index or fit_time is None:
        return {}
    import bisect
    first = bisect.bisect_left(index, (round(fit_time) - 120,))
    matching = [(abs(stamp-fit_time), info) for stamp, info in index[first:] if stamp <= fit_time + 120]
    if len(matching) != 1 or matching[0][0] > 120:
        return {}
    info = matching[0][1]
    recorded = info.get("recorded_distance_m")
    if recorded and distance and abs(recorded-distance) > max(800.0, recorded * .27):
        return {}
    return info


def garmin_safe_filename(filename):
    base = filename.replace("\\", "/").rsplit("/", 1)[-1]
    if "@" not in base:
        return filename
    match = re.search(r"_(\d{7,})(\.fit(?:\.gz)?)$", base, re.I)
    if match:
        return "Garmin/" + match.group(1) + match.group(2).lower()
    extension = ".fit.gz" if base.casefold().endswith(".fit.gz") else ".fit"
    return "Garmin/" + hashlib.sha256(base.encode("utf-8")).hexdigest()[:20] + extension


def apply_metadata(con, lookup):
    updates = 0
    for ident, filename in con.execute("SELECT id,filename FROM activities"):
        info = get_metadata(filename, lookup)
        if not info:
            continue
        restore_global_baseline(con,ident)
        con.execute("""UPDATE activities SET name=COALESCE(NULLIF(?,''),name), sport=COALESCE(NULLIF(?,''),sport),
            day=COALESCE(?,day), recorded_distance_m=COALESCE(?,recorded_distance_m),
            moving_seconds=COALESCE(?,moving_seconds), elapsed_seconds=COALESCE(?,elapsed_seconds),
            elevation_m=COALESCE(?,elevation_m), avg_heart_rate=COALESCE(?,avg_heart_rate),
            avg_speed=COALESCE(?,avg_speed), max_speed=COALESCE(?,max_speed), avg_power=COALESCE(?,avg_power),
            bike=COALESCE(NULLIF(?,''),bike), gear_id=COALESCE(NULLIF(?,''),gear_id),
            moving_source=CASE WHEN ? IS NOT NULL THEN 'strava' ELSE moving_source END,
            elevation_source=CASE WHEN ? IS NOT NULL THEN 'strava' ELSE elevation_source END
            WHERE id=?""", ((info.get("name") or "")[:300], (info.get("sport") or "")[:80], info.get("day"),
            info.get("recorded_distance_m"), info.get("moving_seconds"), info.get("elapsed_seconds"),
            info.get("elevation_m"), info.get("avg_heart_rate"), info.get("avg_speed"), info.get("max_speed"), info.get("avg_power"),
            (info.get("bike") or "")[:160], (info.get("gear_id") or "")[:120],
            info.get("moving_seconds"), info.get("elevation_m"), ident))
        extra_update=[info.get(field) for field in ADV_NUM_FIELDS]
        extra_update.append((info.get("weather_condition") or None))
        con.execute("UPDATE activities SET "+", ".join(field+"=COALESCE(?,"+field+")" for field in ADV_NUM_FIELDS+("weather_condition",)) + " WHERE id=?",extra_update+[ident])
         
         
        seed_source_version(con,ident)
        strava_id=strava_activity_id(filename)
        if strava_id:
            record_source_version(con,ident,'strava-archive-csv:'+strava_id,'strava-archive/activities.csv',info)
        apply_source_choices(con,ident)
        if con.execute('SELECT 1 FROM activity_source_baselines WHERE activity_id=?',(ident,)).fetchone():capture_global_baseline(con,ident,replace=True)
        apply_global_source_preferences(con,ident)
        reapply_activity_override(con,ident)
        updates += 1
    con.commit()
    clear_render_caches()
    return updates


def get_metadata(filename, lookup):
    name = filename.replace("\\", "/")
    base = name.rsplit("/", 1)[-1]
    ident = re.match(r"^(\d{7,})(?:\.|_|$)", base)
    return (lookup.get(name.casefold()) or lookup.get(base.casefold()) or (lookup.get("id:" + ident.group(1)) if ident else None) or {})


def strava_activity_id(filename):
    name = filename.replace("\\", "/").rsplit("/", 1)[-1]
    match = re.match(r"^(\d{7,})(?:\.|_|$)", name)
    return match.group(1) if match else None


ADV_NUM_FIELDS=("calories_kcal","avg_temp_c","max_temp_c","weather_temp_c","wind_speed_mps","wind_gust_mps","humidity_pct","avg_cadence","max_power","max_cadence","total_cycles","normalized_power","training_stress_score","intensity_factor","max_heart_rate")


def db_connect():
    con = sqlite3.connect(str(DB_PATH), timeout=40)
    con.execute("PRAGMA busy_timeout=40000")
    return con


def init_db():
    with db_connect() as con:
        con.execute("PRAGMA journal_mode=WAL")
        con.execute("CREATE TABLE IF NOT EXISTS activities (id INTEGER PRIMARY KEY, unique_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, name TEXT NOT NULL, sport TEXT NOT NULL, day TEXT, distance_m INTEGER, point_count INTEGER NOT NULL, west REAL NOT NULL, south REAL NOT NULL, east REAL NOT NULL, north REAL NOT NULL, coordinates BLOB NOT NULL)")
        columns = {row[1] for row in con.execute("PRAGMA table_info(activities)")}
        for name in ("recorded_distance_m", "moving_seconds", "elapsed_seconds", "elevation_m", "avg_heart_rate", "avg_speed", "max_speed", "avg_power"):
            if name not in columns:
                con.execute("ALTER TABLE activities ADD COLUMN {} REAL".format(name))
        for name in ADV_NUM_FIELDS:
            if name not in columns:
                con.execute("ALTER TABLE activities ADD COLUMN {} REAL".format(name))
        if "weather_condition" not in columns:
            con.execute("ALTER TABLE activities ADD COLUMN weather_condition TEXT")
        for name in ("bike", "gear_id", "moving_source", "elevation_source"):
            if name not in columns:
                con.execute("ALTER TABLE activities ADD COLUMN {} TEXT".format(name))
        con.execute("CREATE INDEX IF NOT EXISTS activity_filters ON activities (sport, day)")
        con.execute("CREATE INDEX IF NOT EXISTS activity_bbox ON activities (west, east, south, north)")
        if "activity_id" not in columns:
            con.execute("ALTER TABLE activities ADD COLUMN activity_id TEXT")
            for row_id, filename in con.execute("SELECT id,filename FROM activities").fetchall():
                activity_id = strava_activity_id(filename)
                if activity_id:
                    con.execute("UPDATE activities SET activity_id=? WHERE id=?", (activity_id, row_id))
        if "fit_extended_checked" not in columns:
            con.execute("ALTER TABLE activities ADD COLUMN fit_extended_checked INTEGER NOT NULL DEFAULT 0")
        con.execute("CREATE INDEX IF NOT EXISTS activity_id_idx ON activities(activity_id)")
        con.execute("CREATE INDEX IF NOT EXISTS activity_filename_idx ON activities(filename)")
        for row_id, filename in con.execute("SELECT id,filename FROM activities WHERE activity_id IS NULL OR activity_id='' ").fetchall():
            activity_id = strava_activity_id(filename)
            if activity_id:
                con.execute("UPDATE activities SET activity_id=? WHERE id=?", (activity_id, row_id))
        con.execute("CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
        con.execute("CREATE TABLE IF NOT EXISTS speed_filter_exceptions (activity_id INTEGER PRIMARY KEY, included INTEGER NOT NULL DEFAULT 1 CHECK(included=1))")
        con.execute("CREATE TABLE IF NOT EXISTS activity_telemetry (activity_id INTEGER PRIMARY KEY, payload BLOB NOT NULL, sample_count INTEGER NOT NULL, FOREIGN KEY(activity_id) REFERENCES activities(id) ON DELETE CASCADE)")
        con.execute("CREATE TABLE IF NOT EXISTS import_history (id INTEGER PRIMARY KEY, imported_at TEXT NOT NULL, label TEXT NOT NULL, added INTEGER NOT NULL, skipped INTEGER NOT NULL, no_gps INTEGER NOT NULL, failed INTEGER NOT NULL, updated INTEGER NOT NULL)")
        con.execute("CREATE INDEX IF NOT EXISTS activity_day_idx ON activities(day)")
        con.execute("CREATE INDEX IF NOT EXISTS activity_day_distance_idx ON activities(day,distance_m)")
        con.execute("CREATE TABLE IF NOT EXISTS archived_duplicates (archive_id INTEGER PRIMARY KEY AUTOINCREMENT, original_id INTEGER NOT NULL, kept_id INTEGER NOT NULL, archived_at TEXT NOT NULL, metadata TEXT NOT NULL, coordinates BLOB NOT NULL, telemetry BLOB, telemetry_samples INTEGER, speed_exception INTEGER)")
        con.execute("CREATE TABLE IF NOT EXISTS activity_overrides (activity_id INTEGER PRIMARY KEY, originals TEXT NOT NULL, values_json TEXT NOT NULL, updated_at TEXT NOT NULL)")
        con.execute("CREATE TABLE IF NOT EXISTS activity_edit_log (id INTEGER PRIMARY KEY, activity_id INTEGER NOT NULL, changed_at TEXT NOT NULL, previous TEXT NOT NULL, updated TEXT NOT NULL)")
        con.execute("CREATE TABLE IF NOT EXISTS activity_source_versions (id INTEGER PRIMARY KEY, activity_id INTEGER NOT NULL, source_key TEXT NOT NULL, label TEXT NOT NULL, provider TEXT NOT NULL, fields_json TEXT NOT NULL, coordinates BLOB, route_stats TEXT, telemetry BLOB, sample_count INTEGER, UNIQUE(activity_id,source_key))")
        con.execute("CREATE INDEX IF NOT EXISTS source_version_activity_idx ON activity_source_versions(activity_id)")
        con.execute("CREATE TABLE IF NOT EXISTS activity_source_choices (activity_id INTEGER PRIMARY KEY, choices_json TEXT NOT NULL, updated_at TEXT NOT NULL)")
        con.execute("CREATE TABLE IF NOT EXISTS activity_source_baselines (activity_id INTEGER PRIMARY KEY, fields_json TEXT NOT NULL, coordinates BLOB, route_stats TEXT, telemetry BLOB, sample_count INTEGER)")
        con.execute("CREATE TABLE IF NOT EXISTS activity_route_repairs (activity_id INTEGER PRIMARY KEY, original_coordinates BLOB NOT NULL, original_point_count INTEGER NOT NULL, original_distance_m REAL NOT NULL, original_bbox TEXT NOT NULL, original_telemetry BLOB, original_telemetry_count INTEGER, edits TEXT NOT NULL, applied_at TEXT NOT NULL)")
        con.execute("CREATE TABLE IF NOT EXISTS heatmap_track_cache (activity_id INTEGER PRIMARY KEY, source_digest TEXT NOT NULL, payload BLOB NOT NULL)")
        con.execute("CREATE TABLE IF NOT EXISTS heatmap_view_cache (key TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, digest TEXT NOT NULL, payload BLOB NOT NULL, used INTEGER NOT NULL DEFAULT 0)")



DEFAULT_APPEARANCE = {"mode":"dark","online":True,"palette":"classic","routes":True,"heat":True,"radius":5,"definition":78,"intensity":120,"opacity":84,"bike_routes":True,"bike_tint_color":"#54dc96"}


def normalize_appearance(value):
    retired = {"bike_source", "bike_paths", "bike_lanes", "bike_trails", "bike_path_color", "bike_lane_color", "bike_trail_color", "bike_path_width", "bike_lane_width", "bike_trail_width", "bike_opacity"}
    if not isinstance(value, dict) or set(value) - set(DEFAULT_APPEARANCE) - retired:
        raise ValueError("Invalid appearance settings")
    result = dict(DEFAULT_APPEARANCE)
    for key, item in value.items():
        if key in retired:
            continue
        if key == "mode":
            if item not in ("dark", "light", "satellite"):
                raise ValueError("Invalid map background")
        elif key == "palette":
            if item not in ("classic", "ember", "violet", "ocean", "forest"):
                raise ValueError("Invalid heat palette")
        elif key in ("online", "routes", "heat", "bike_routes"):
            if not isinstance(item, bool):
                raise ValueError("Invalid toggle setting")
        elif key == "bike_tint_color":
            if not isinstance(item, str) or not re.fullmatch(r"#[0-9a-fA-F]{6}", item):
                raise ValueError("Invalid cycling line color")
            item = item.lower()
        elif key in ("radius", "definition", "intensity", "opacity"):
            if isinstance(item, bool) or not isinstance(item, (int, float)) or not math.isfinite(item):
                raise ValueError("Invalid display slider")
            limits = {"radius":(0,30),"definition":(0,100),"intensity":(0,200),"opacity":(0,100)}
            lower, upper = limits[key]
            if not lower <= item <= upper:
                raise ValueError("Appearance setting outside supported range")
            item = int(item)
        result[key] = item
    return result


def load_appearance():
    with db_connect() as con:
        result = con.execute("SELECT value FROM app_settings WHERE key='appearance'").fetchone()
    try:
        if not result:
            return None
        saved = json.loads(result[0])
         
         
        if isinstance(saved, dict) and 'bike_tint_color' not in saved:
            legacy_color = saved.get('bike_path_color')
            if isinstance(legacy_color, str) and re.fullmatch(r'#[0-9a-fA-F]{6}', legacy_color):
                saved['bike_tint_color'] = legacy_color
        return normalize_appearance(saved)
    except (TypeError, ValueError, json.JSONDecodeError):
        return None


def store_appearance(value):
    appearance = normalize_appearance(value)
    with db_connect() as con:
        con.execute("INSERT INTO app_settings(key,value) VALUES('appearance',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (json.dumps(appearance, separators=(',', ':')),))
    return appearance


def quantile(values, proportion):
    values = sorted(values)
    if not values:
        raise ValueError("No coordinates")
    index = (len(values)-1)*proportion
    low = int(index)
    high = min(len(values)-1,low+1)
    return values[low]+(values[high]-values[low])*(index-low)


def focus_activity_bounds(boxes):
    if not boxes:
        return None
    centers = [((b[0] + b[2]) / 2, (b[1] + b[3]) / 2) for b in boxes]
    latitude = quantile([p[1] for p in centers], .5)
    cosine = max(.25, math.cos(math.radians(latitude)))
    cell_lat = .12
    cell_lon = cell_lat / cosine
    cells = {}
    for lon, lat in centers:
        key = (math.floor(lon / cell_lon), math.floor(lat / cell_lat))
        cells.setdefault(key, []).append((lon, lat))
    selected = []
    best = -1
    for x, y in cells:
        nearby = [p for i in (-1, 0, 1) for j in (-1, 0, 1) for p in cells.get((x + i, y + j), ())]
        if len(nearby) > best:
            selected = nearby
            best = len(nearby)
    if not selected:
        selected = centers
    longitude = quantile([p[0] for p in selected], .5)
    latitude = quantile([p[1] for p in selected], .5)
    cosine = max(.25, math.cos(math.radians(latitude)))
    longitude_spread = (quantile([p[0] for p in selected], .8) - quantile([p[0] for p in selected], .2)) * cosine
    latitude_spread = quantile([p[1] for p in selected], .8) - quantile([p[1] for p in selected], .2)
    radius = min(.16, max(.045, max(longitude_spread, latitude_spread) * .9))
    half_lon = radius / cosine
    return [max(-180, longitude - half_lon), max(-85, latitude - radius), min(180, longitude + half_lon), min(85, latitude + radius)]

def recover_fit_summary(stream, filename):
    summary = {}
    source = BoundedStream(stream)
    if filename.lower().endswith(".gz"):
        source = BoundedStream(gzip.GzipFile(fileobj=source))
    for _ in points_fit(source, summary):
        pass
    return summary


def recover_xml_telemetry(stream, filename):
    summary={}
    source=BoundedStream(stream)
    if filename.lower().endswith('.gz'):
        source=BoundedStream(gzip.GzipFile(fileobj=source))
    parser=points_gpx if filename.lower().endswith(('.gpx','.gpx.gz')) else points_tcx
    for _ in parser(source,summary):pass
    return {'_telemetry':summary.get('_telemetry',[])}


 
 
SOURCE_CHOICE_FIELDS = ('name','sport','day','bike','gear_id','recorded_distance_m',
    'moving_seconds','elapsed_seconds','elevation_m','avg_speed','max_speed',
    'avg_heart_rate','avg_power')+ADV_NUM_FIELDS+('weather_condition',)


def source_provider(label):
    path=str(label).replace('\\','/').lower()
    if path.startswith('garmin/') or path.startswith('garmin-') or 'garmin' in path:
        return 'Garmin'
    if path.startswith(('activities/','strava/','strava-archive/')) or re.search(r'(?:^|/)(?:[0-9]{7,}|strava)[^/]*\.(?:gpx|fit|tcx)',path):
        return 'Strava'
    return 'Imported file'


def source_version_fields(info):
    result={}
    for key in SOURCE_CHOICE_FIELDS:
        value=info.get(key)
        if value is None or value=='':continue
        if isinstance(value,(int,float)) and not math.isfinite(value):continue
        if isinstance(value,(str,int,float)) and not isinstance(value,bool):result[key]=value
    return result


def seed_source_version(con,activity_id):
    if con.execute('SELECT 1 FROM activity_source_versions WHERE activity_id=? LIMIT 1',(activity_id,)).fetchone():return
    previous_factory=con.row_factory
    try:
        con.row_factory=sqlite3.Row
        row=con.execute('SELECT * FROM activities WHERE id=?',(activity_id,)).fetchone()
    finally:
        con.row_factory=previous_factory
    if row is None:return
    record=dict(row)
    telemetry=con.execute('SELECT payload,sample_count FROM activity_telemetry WHERE activity_id=?',(activity_id,)).fetchone()
    stats={key:record[key] for key in ('point_count','distance_m','west','south','east','north')}
    con.execute('INSERT OR IGNORE INTO activity_source_versions(activity_id,source_key,label,provider,fields_json,coordinates,route_stats,telemetry,sample_count) VALUES(?,?,?,?,?,?,?,?,?)',
        (activity_id,record['unique_key'],'Original library record: '+Path(record['filename']).name[:100],
         source_provider(record['filename']),json.dumps(source_version_fields(record),separators=(',',':')),
         record['coordinates'],json.dumps(stats),telemetry[0] if telemetry else None,telemetry[1] if telemetry else None))


def record_source_version(con,activity_id,source_key,filename,info,geometry=None):
    fields=source_version_fields(info)
    telemetry=info.get('_telemetry')
    payload=None
    if isinstance(telemetry,list) and telemetry:
        try:
            payload=zlib.compress(json.dumps(telemetry,separators=(',',':'),allow_nan=False).encode(),6)
            if len(payload)>4*1024*1024:payload=None
        except (ValueError,TypeError,OverflowError):payload=None
    coords,stats=(None,None)
    if geometry is not None:
        compressed,count,bbox,day,distance=geometry
        coords=compressed
        stats=json.dumps(dict(point_count=count,distance_m=distance,west=bbox[1],south=bbox[0],east=bbox[3],north=bbox[2]))
    if not fields and coords is None and payload is None:return
    con.execute("""INSERT INTO activity_source_versions(activity_id,source_key,label,provider,fields_json,coordinates,route_stats,telemetry,sample_count)
        VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(activity_id,source_key) DO UPDATE SET
        fields_json=excluded.fields_json,coordinates=COALESCE(excluded.coordinates,activity_source_versions.coordinates),
        route_stats=COALESCE(excluded.route_stats,activity_source_versions.route_stats),
        telemetry=COALESCE(excluded.telemetry,activity_source_versions.telemetry),
        sample_count=COALESCE(excluded.sample_count,activity_source_versions.sample_count)""",
        (activity_id,source_key,Path(filename).name[:110],source_provider(filename),json.dumps(fields,separators=(',',':')),
         coords,stats,payload,len(telemetry) if payload is not None else None))


def apply_source_choices(con,activity_id):
    row=con.execute('SELECT choices_json FROM activity_source_choices WHERE activity_id=?',(activity_id,)).fetchone()
    if not row:return
    choices=json.loads(row[0])
    fields={}
    for key,source_id in choices.items():
        if key not in SOURCE_CHOICE_FIELDS or type(source_id)!=int:continue
        data=con.execute('SELECT fields_json FROM activity_source_versions WHERE activity_id=? AND id=?',(activity_id,source_id)).fetchone()
        if not data:continue
        value=json.loads(data[0]).get(key)
        if value is not None:fields[key]=value
        if key in ('moving_seconds','elevation_m') and value is not None:
            provider=con.execute('SELECT provider FROM activity_source_versions WHERE id=? AND activity_id=?',(source_id,activity_id)).fetchone()
            if provider and provider[0] in ('Garmin','Strava'):
                fields['moving_source' if key=='moving_seconds' else 'elevation_source']=provider[0].lower()
    if fields:
        con.execute('UPDATE activities SET '+','.join(k+'=?' for k in fields)+' WHERE id=?',tuple(fields.values())+(activity_id,))
    if type(choices.get('route'))==int:
        source=con.execute('SELECT coordinates,route_stats FROM activity_source_versions WHERE activity_id=? AND id=?',
                           (activity_id,choices['route'])).fetchone()
        if source and source[0] and source[1] and not con.execute('SELECT 1 FROM activity_route_repairs WHERE activity_id=?',(activity_id,)).fetchone():
            stats=json.loads(source[1]);columns=('point_count','distance_m','west','south','east','north')
            if all(k in stats for k in columns):
                con.execute('UPDATE activities SET coordinates=?,'+','.join(k+'=?' for k in columns)+' WHERE id=?',
                            (source[0],)+(tuple(stats[k] for k in columns))+(activity_id,))
    if type(choices.get('telemetry'))==int:
        source=con.execute('SELECT telemetry,sample_count FROM activity_source_versions WHERE activity_id=? AND id=?',
                           (activity_id,choices['telemetry'])).fetchone()
        if source and source[0] and source[1] and not con.execute('SELECT 1 FROM activity_route_repairs WHERE activity_id=?',(activity_id,)).fetchone():
            con.execute('INSERT INTO activity_telemetry(activity_id,payload,sample_count) VALUES(?,?,?) ON CONFLICT(activity_id) DO UPDATE SET payload=excluded.payload,sample_count=excluded.sample_count',
                        (activity_id,source[0],source[1]))


 
 
SOURCE_PREFERENCE_FIELDS = SOURCE_CHOICE_FIELDS + ('route','telemetry')
SOURCE_PREFERENCE_PROVIDERS = ('Auto','Garmin','Strava','Imported file')
SOURCE_BASELINE_FIELDS = SOURCE_CHOICE_FIELDS + ('moving_source','elevation_source')


def load_source_preferences(con=None):
    def from_db(db):
        record=db.execute("SELECT value FROM app_settings WHERE key='source_preferences'").fetchone()
        try: stored=json.loads(record[0]) if record else {}
        except (ValueError,TypeError):stored={}
        if not isinstance(stored,dict):stored={}
        return {name:stored.get(name,'Auto') if stored.get(name) in SOURCE_PREFERENCE_PROVIDERS else 'Auto'
                for name in SOURCE_PREFERENCE_FIELDS}
    if con is not None:return from_db(con)
    with db_connect() as db:return from_db(db)


def source_preference_review(con):
    prefs=load_source_preferences(con)
    multi=con.execute('SELECT COUNT(*) FROM (SELECT activity_id FROM activity_source_versions GROUP BY activity_id HAVING COUNT(*)>1)').fetchone()[0]
    counts={name:{provider:0 for provider in SOURCE_PREFERENCE_PROVIDERS[1:]} for name in SOURCE_PREFERENCE_FIELDS}
    for provider,fields_json,route,telemetry in con.execute('SELECT provider,fields_json,coordinates IS NOT NULL,telemetry IS NOT NULL FROM activity_source_versions WHERE activity_id IN (SELECT activity_id FROM activity_source_versions GROUP BY activity_id HAVING COUNT(*)>1)'):
        if provider not in SOURCE_PREFERENCE_PROVIDERS[1:]:continue
        data=json.loads(fields_json)
        for name in SOURCE_CHOICE_FIELDS:
            if name in data and data[name] is not None:counts[name][provider]+=1
        if route is not None:counts['route'][provider]+=1
        if telemetry is not None:counts['telemetry'][provider]+=1
    return {'preferences':prefs,'providers':list(SOURCE_PREFERENCE_PROVIDERS),
            'fields':list(SOURCE_PREFERENCE_FIELDS),'availability':counts,'multi_source_activities':multi,
            'fallback':'When your preferred source lacks a field, the previously imported value is retained. Manually edited values and repaired routes are protected.'}


def capture_global_baseline(con,activity_id,replace=False):
    old=con.execute('SELECT coordinates,telemetry FROM activity_source_baselines WHERE activity_id=?',(activity_id,)).fetchone()
    if not replace and old:return
     
     
     
    fields=','.join(SOURCE_BASELINE_FIELDS)
    values=con.execute('SELECT '+fields+' FROM activities WHERE id=?',(activity_id,)).fetchone()
    if values is None:return
    metadata=dict(zip(SOURCE_BASELINE_FIELDS,values))
    route=None;coords=None;telemetry=None
    if old and old[0] is not None:
        row=con.execute('SELECT coordinates,point_count,distance_m,west,south,east,north FROM activities WHERE id=?',(activity_id,)).fetchone()
        coords=row[0];route=json.dumps(dict(zip(('point_count','distance_m','west','south','east','north'),row[1:])))
    if old and old[1] is not None:
        telemetry=con.execute('SELECT payload,sample_count FROM activity_telemetry WHERE activity_id=?',(activity_id,)).fetchone()
    con.execute("""INSERT INTO activity_source_baselines(activity_id,fields_json,coordinates,route_stats,telemetry,sample_count)
        VALUES(?,?,?,?,?,?) ON CONFLICT(activity_id) DO UPDATE SET
        fields_json=excluded.fields_json,coordinates=excluded.coordinates,route_stats=excluded.route_stats,
        telemetry=excluded.telemetry,sample_count=excluded.sample_count""",
        (activity_id,json.dumps(metadata,separators=(',',':')),coords,route,
         telemetry[0] if telemetry else None,telemetry[1] if telemetry else None))


def backup_global_media_once(con,activity_id,prefs):
    baseline=con.execute('SELECT coordinates,telemetry FROM activity_source_baselines WHERE activity_id=?',(activity_id,)).fetchone()
    if baseline is None:return
    if prefs.get('route')!='Auto' and baseline[0] is None:
        row=con.execute('SELECT coordinates,point_count,distance_m,west,south,east,north FROM activities WHERE id=?',(activity_id,)).fetchone()
        if row and row[0] is not None:
            stats=dict(zip(('point_count','distance_m','west','south','east','north'),row[1:]))
            con.execute('UPDATE activity_source_baselines SET coordinates=?,route_stats=? WHERE activity_id=?',(row[0],json.dumps(stats),activity_id))
    if prefs.get('telemetry')!='Auto' and baseline[1] is None:
        row=con.execute('SELECT payload,sample_count FROM activity_telemetry WHERE activity_id=?',(activity_id,)).fetchone()
        if row:con.execute('UPDATE activity_source_baselines SET telemetry=?,sample_count=? WHERE activity_id=?',(row[0],row[1],activity_id))


def restore_global_baseline(con,activity_id):
    baseline=con.execute('SELECT fields_json,coordinates,route_stats,telemetry,sample_count FROM activity_source_baselines WHERE activity_id=?',(activity_id,)).fetchone()
    if baseline is None:return False
    data=json.loads(baseline[0]);names=[name for name in SOURCE_BASELINE_FIELDS if name in data]
    if names:con.execute('UPDATE activities SET '+','.join(name+'=?' for name in names)+' WHERE id=?',tuple(data[name] for name in names)+(activity_id,))
    repaired=con.execute('SELECT 1 FROM activity_route_repairs WHERE activity_id=?',(activity_id,)).fetchone()
    if not repaired and baseline[1] is not None and baseline[2]:
        route=json.loads(baseline[2]);keys=('point_count','distance_m','west','south','east','north')
        if all(k in route for k in keys):
            con.execute('UPDATE activities SET coordinates=?,'+','.join(k+'=?' for k in keys)+' WHERE id=?',
                        (baseline[1],)+tuple(route[k] for k in keys)+(activity_id,))
    if not repaired and baseline[3] is not None and baseline[4] is not None:
         
         
        con.execute('INSERT INTO activity_telemetry(activity_id,payload,sample_count) VALUES(?,?,?) ON CONFLICT(activity_id) DO UPDATE SET payload=excluded.payload,sample_count=excluded.sample_count',
                    (activity_id,baseline[3],baseline[4]))
    return True


def apply_global_source_preferences(con,activity_id,preferences=None):
    prefs=preferences if preferences is not None else load_source_preferences(con)
    baseline=con.execute('SELECT 1 FROM activity_source_baselines WHERE activity_id=?',(activity_id,)).fetchone()
    if not baseline and not any(v!='Auto' for v in prefs.values()):return False
    versions=con.execute('SELECT id,provider,fields_json,coordinates IS NOT NULL,route_stats,telemetry IS NOT NULL,sample_count FROM activity_source_versions WHERE activity_id=? ORDER BY id DESC',(activity_id,)).fetchall()
    if len(versions)<2 and not baseline:return False
    if not baseline:capture_global_baseline(con,activity_id)
    else:restore_global_baseline(con,activity_id)
    backup_global_media_once(con,activity_id,prefs)
    updates={}
    selected_media={}
    for name,preferred in prefs.items():
        if preferred=='Auto':continue
        for sid,provider,json_fields,coords,route_stats,telemetry,count in versions:
            if provider!=preferred:continue
            if name=='route':
                if coords and route_stats:
                    selected_media[name]=(con.execute('SELECT coordinates FROM activity_source_versions WHERE id=?',(sid,)).fetchone()[0],json.loads(route_stats));break
            elif name=='telemetry':
                if telemetry and count is not None:
                    selected_media[name]=(con.execute('SELECT telemetry FROM activity_source_versions WHERE id=?',(sid,)).fetchone()[0],count);break
            else:
                val=json.loads(json_fields).get(name)
                if val is not None:
                    updates[name]=val
                    if name in ('moving_seconds','elevation_m') and preferred in ('Garmin','Strava'):
                        updates['moving_source' if name=='moving_seconds' else 'elevation_source']=preferred.lower()
                    break
    if updates:
        con.execute('UPDATE activities SET '+','.join(k+'=?' for k in updates)+' WHERE id=?',tuple(updates.values())+(activity_id,))
    repaired=con.execute('SELECT 1 FROM activity_route_repairs WHERE activity_id=?',(activity_id,)).fetchone()
    if not repaired and 'route' in selected_media:
        coords,route=selected_media['route'];keys=('point_count','distance_m','west','south','east','north')
        if all(k in route for k in keys):
            con.execute('UPDATE activities SET coordinates=?,'+','.join(k+'=?' for k in keys)+' WHERE id=?',
                        (coords,)+tuple(route[k] for k in keys)+(activity_id,))
    if not repaired and 'telemetry' in selected_media:
        trace,count=selected_media['telemetry']
        con.execute('INSERT INTO activity_telemetry(activity_id,payload,sample_count) VALUES(?,?,?) ON CONFLICT(activity_id) DO UPDATE SET payload=excluded.payload,sample_count=excluded.sample_count',
                    (activity_id,trace,count))
    reapply_activity_override(con,activity_id)
    return bool(updates or selected_media or baseline)


def save_source_preferences(payload):
    if not isinstance(payload,dict) or set(payload)!={'preferences'} or not isinstance(payload['preferences'],dict):
        raise ValueError('Invalid global data source preferences')
    values=payload['preferences']
    if set(values)!=set(SOURCE_PREFERENCE_FIELDS) or any(type(v)!=str or v not in SOURCE_PREFERENCE_PROVIDERS for v in values.values()):
        raise ValueError('Choose Auto, Garmin, Strava or Imported file for each known field')
    with STATE_LOCK:
        if JOB['status']=='running':raise ValueError('Finish the current import before applying source rules')
        with db_connect() as con:
            con.execute('BEGIN IMMEDIATE')
            con.execute("INSERT INTO app_settings(key,value) VALUES('source_preferences',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                        (json.dumps(values,separators=(',',':')),))
            ids={r[0] for r in con.execute('SELECT activity_id FROM activity_source_versions GROUP BY activity_id HAVING COUNT(*)>1')}
            ids.update(r[0] for r in con.execute('SELECT activity_id FROM activity_source_baselines'))
            for activity_id in sorted(ids):apply_global_source_preferences(con,activity_id,values)
    clear_render_caches(include_tracks=True)
    start_heat_warmup()
    return {'ok':True,'preferences':values,'activities_reviewed':len(ids)}


def choose_activity_sources(payload):
    if not isinstance(payload,dict) or set(payload)!={'action','activity_id','choices'} or payload['action']!='choose_sources':
        raise ValueError('Invalid source selection')
    activity_id=payload['activity_id'];choices=payload['choices']
    if type(activity_id)!=int or not 0<activity_id<10**12 or not isinstance(choices,dict) or len(choices)>len(SOURCE_CHOICE_FIELDS)+2:
        raise ValueError('Invalid activity or source selection')
    if any(k not in SOURCE_CHOICE_FIELDS+('route','telemetry') or type(v)!=int or v<=0 for k,v in choices.items()):
        raise ValueError('Invalid source field')
    with STATE_LOCK:
        if JOB['status']=='running':raise ValueError('Finish the current import before changing activity sources')
        with db_connect() as con:
            con.execute('BEGIN IMMEDIATE')
            if not con.execute('SELECT 1 FROM activities WHERE id=?',(activity_id,)).fetchone():raise ValueError('Activity no longer exists')
            override=con.execute('SELECT originals,values_json FROM activity_overrides WHERE activity_id=?',(activity_id,)).fetchone()
            manually_edited=set()
            if override:
                old=json.loads(override[0]); new=json.loads(override[1])
                manually_edited={k for k in EDITABLE_ACTIVITY_FIELDS if new.get(k)!=old.get(k)}
            if any(k in manually_edited for k in choices):
                raise ValueError('Restore the manually edited field before selecting its import source')
            for key,source_id in choices.items():
                row=con.execute('SELECT fields_json FROM activity_source_versions WHERE activity_id=? AND id=?',(activity_id,source_id)).fetchone()
                if key in SOURCE_CHOICE_FIELDS:
                    if not row or json.loads(row[0]).get(key) is None:raise ValueError('Selected source does not supply '+key)
                else:
                    option=con.execute('SELECT coordinates,route_stats,telemetry,sample_count FROM activity_source_versions WHERE activity_id=? AND id=?',
                                       (activity_id,source_id)).fetchone()
                    if not option or (key=='route' and not (option[0] and option[1])) or (key=='telemetry' and not (option[2] and option[3])):
                        raise ValueError('Selected source does not contain the '+key+' recording')
                    if con.execute('SELECT 1 FROM activity_route_repairs WHERE activity_id=?',(activity_id,)).fetchone():
                        raise ValueError('Restore any manual GPS route repairs before choosing a different track or sensor trace')
            con.execute('INSERT INTO activity_source_choices(activity_id,choices_json,updated_at) VALUES(?,?,?) ON CONFLICT(activity_id) DO UPDATE SET choices_json=excluded.choices_json,updated_at=excluded.updated_at',
                (activity_id,json.dumps(choices,separators=(',',':')),dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')))
            apply_source_choices(con,activity_id)
    clear_render_caches(include_tracks=True)
    start_heat_warmup()
    return {'ok':True,'activity_id':activity_id,'fields_selected':len(choices)}


def source_version_review(con, activity_id=None):
    if activity_id is None:
        rows=con.execute('SELECT activity_id,COUNT(*) FROM activity_source_versions GROUP BY activity_id HAVING COUNT(*)>1 ORDER BY activity_id DESC LIMIT 250').fetchall()
    else:
        rows=con.execute('SELECT activity_id,COUNT(*) FROM activity_source_versions WHERE activity_id=? GROUP BY activity_id HAVING COUNT(*)>1',(activity_id,)).fetchall()
    results=[]
    for activity_id,_ in rows:
        activity=con.execute('SELECT name,day FROM activities WHERE id=?',(activity_id,)).fetchone()
        if not activity:continue
        versions=[]
        for row in con.execute('SELECT id,label,provider,fields_json,coordinates,telemetry FROM activity_source_versions WHERE activity_id=? ORDER BY id',(activity_id,)):
            versions.append({'id':row[0],'label':row[1],'provider':row[2], 'fields':json.loads(row[3]),
                             'has_route':row[4] is not None,'has_telemetry':row[5] is not None})
        preferences=con.execute('SELECT choices_json FROM activity_source_choices WHERE activity_id=?',(activity_id,)).fetchone()
        results.append({'activity_id':activity_id,'name':activity[0],'day':activity[1],
                        'sources':versions,'choices':json.loads(preferences[0]) if preferences else {}})
    return results


def _telemetry_near(a, b, distance_limit=80):
    if not isinstance(a,list) or not isinstance(b,list) or len(a)<3 or len(b)<3:
        return False
    try:
        if not all(isinstance(v,(int,float)) and math.isfinite(v) for v in (a[0],a[1],a[2],b[0],b[1],b[2])):
            return False
        return haversine((a[1],a[2]),(b[1],b[2])) <= distance_limit
    except (TypeError,ValueError,OverflowError):
        return False


def matching_existing_recording(con, info, day, distance):
    samples=info.get('_telemetry') or []
    if len(samples)<2 or distance<1000 or not day:
        return None
    first,last=samples[0],samples[-1]
    if not _telemetry_near(first,first) or not _telemetry_near(last,last):
        return None
    if not 30 <= last[0]-first[0] <= 7*24*3600:
        return None
    try:
        date=dt.date.fromisoformat(day[:10])
    except ValueError:
        return None
    try:
        lower=(date-dt.timedelta(days=1)).isoformat()
        upper=(date+dt.timedelta(days=1)).isoformat()
    except OverflowError:
        return None
    allowance=max(60,distance*.03)
    sql=('SELECT a.id,t.payload FROM activities a JOIN activity_telemetry t ON t.activity_id=a.id '
         'WHERE a.day BETWEEN ? AND ? AND a.distance_m BETWEEN ? AND ? '
         'ORDER BY a.id LIMIT 100')
    candidates=con.execute(sql,(lower,upper,distance-allowance,distance+allowance)).fetchall()
    matches=[]
    for candidate_id,payload in candidates:
        try:
            old=json.loads(zlib.decompress(payload))
            if len(old)<2:continue
            before,after=old[0],old[-1]
            if (abs(first[0]-before[0])<=120 and abs(last[0]-after[0])<=120
                and _telemetry_near(first,before) and _telemetry_near(last,after)):
                matches.append(candidate_id)
        except (TypeError,ValueError,IndexError,zlib.error,OverflowError):
            continue
    return matches[0] if len(matches)==1 else None


def enrich_matching_recording(con, row_id, info, activity_id):
    fields=('recorded_distance_m','moving_seconds','elapsed_seconds','elevation_m',
            'avg_heart_rate','avg_speed','max_speed','avg_power')+ADV_NUM_FIELDS+('weather_condition',)
    values=[info.get(k) for k in fields]
    updates=', '.join(k+'=COALESCE('+k+',?)' for k in fields)
    con.execute('UPDATE activities SET '+updates+' WHERE id=?',values+[row_id])
    existing=con.execute('SELECT name,filename,sport FROM activities WHERE id=?',(row_id,)).fetchone()
    new_name=(info.get('name') or '').strip()
    new_sport=(info.get('sport') or '').strip()
    if new_name and existing[0] in ('','Unknown',Path(existing[1]).name.split('.')[0]):
        con.execute('UPDATE activities SET name=? WHERE id=?',(new_name[:300],row_id))
    if new_sport and new_sport.casefold()!='unknown' and existing[2] in ('','Unknown'):
        con.execute('UPDATE activities SET sport=? WHERE id=?',(new_sport[:80],row_id))
    con.execute("UPDATE activities SET bike=COALESCE(NULLIF(bike,''),?),gear_id=COALESCE(NULLIF(gear_id,''),?),activity_id=COALESCE(NULLIF(activity_id,''),?) WHERE id=?",
        ((info.get('bike') or '')[:160],(info.get('gear_id') or '')[:120],activity_id,row_id))
    has_strava_metadata=(info.get('moving_source')=='strava' or info.get('elevation_source')=='strava')
    if has_strava_metadata:
        con.execute("""UPDATE activities SET
            day=COALESCE(?,day),
            name=COALESCE(NULLIF(?,''),name),
            sport=COALESCE(NULLIF(?,''),sport),
            recorded_distance_m=COALESCE(?,recorded_distance_m),
            moving_seconds=COALESCE(?,moving_seconds),
            elapsed_seconds=COALESCE(?,elapsed_seconds),
            elevation_m=COALESCE(?,elevation_m),
            avg_speed=COALESCE(?,avg_speed),
            max_speed=COALESCE(?,max_speed),
            avg_heart_rate=COALESCE(?,avg_heart_rate),
            avg_power=COALESCE(?,avg_power),
            bike=COALESCE(NULLIF(?,''),bike),
            gear_id=COALESCE(NULLIF(?,''),gear_id),
            moving_source=COALESCE(?,moving_source),
            elevation_source=COALESCE(?,elevation_source),
            activity_id=COALESCE(?,activity_id)
            WHERE id=?""",(
            info.get('day'),new_name[:300] if new_name else None,
            new_sport[:80] if new_sport.casefold()!='unknown' else None,
            info.get('recorded_distance_m'),info.get('moving_seconds'),info.get('elapsed_seconds'),
            info.get('elevation_m'),info.get('avg_speed'),info.get('max_speed'),
            info.get('avg_heart_rate'),info.get('avg_power'),
            (info.get('bike') or '')[:160],(info.get('gear_id') or '')[:120],
            info.get('moving_source'),info.get('elevation_source'),activity_id,row_id))
    fresh=info.get('_telemetry') or []
    if fresh:
        row=con.execute('SELECT payload FROM activity_telemetry WHERE activity_id=?',(row_id,)).fetchone()
        try:stored=json.loads(zlib.decompress(row[0])) if row else []
        except (TypeError,ValueError,zlib.error):stored=[]
        richness=lambda data:sum(any(len(sample)>i and sample[i] is not None for sample in data) for i in range(3,9))
        if not stored or richness(fresh)>richness(stored):store_telemetry(con,row_id,info)
    reapply_activity_override(con,row_id)
    con.commit()


def insert_activity(con, source, source_key, stream, info, garmin_index=None):
    filename = source.replace("\\", "/")
    activity_id = strava_activity_id(filename)
    existing = con.execute("SELECT id,moving_seconds,elapsed_seconds,elevation_m,recorded_distance_m,day,avg_speed,max_speed,avg_power FROM activities WHERE unique_key=?", (source_key,)).fetchone()
    if not existing and activity_id:
        existing = con.execute("SELECT id,moving_seconds,elapsed_seconds,elevation_m,recorded_distance_m,day,avg_speed,max_speed,avg_power FROM activities WHERE activity_id=? ORDER BY id LIMIT 1", (activity_id,)).fetchone()
    if not existing:
        existing = con.execute("SELECT id,moving_seconds,elapsed_seconds,elevation_m,recorded_distance_m,day,avg_speed,max_speed,avg_power FROM activities WHERE filename=? ORDER BY id LIMIT 1", (filename,)).fetchone()
    if existing:
         
         
         
         
        row_id=existing[0]
        seed_source_version(con,row_id)
        restore_global_baseline(con,row_id)
        embedded={}
        geometry=decode_track(stream,filename,embedded)
        if geometry is not None and filename.lower().endswith(('.fit','.fit.gz')):
            match=matching_garmin_summary(garmin_index,embedded.get('_fit_start_utc'),geometry[-1])
        else:
            match={}
        imported={**embedded,**match,**{k:v for k,v in info.items() if v is not None and v!=''}}
         
         
        record_source_version(con,row_id,source_key,filename,imported,geometry)
        if imported:
            enrich_matching_recording(con,row_id,imported,activity_id)
        if filename.lower().endswith(('.fit','.fit.gz')):
            con.execute('UPDATE activities SET fit_extended_checked=1 WHERE id=?',(row_id,))
        apply_source_choices(con,row_id)
        if con.execute('SELECT 1 FROM activity_source_baselines WHERE activity_id=?',(row_id,)).fetchone():capture_global_baseline(con,row_id,replace=True)
        apply_global_source_preferences(con,row_id)
        reapply_activity_override(con,row_id)  
        con.commit()
        clear_render_caches()
        return 'enriched'
    embedded = {}
    result = decode_track(stream, filename, embedded)
    info = {**embedded, **{k: v for k, v in info.items() if v is not None and v != ""}}
    if result is None:
        return "no-gps"
    compressed, count, bbox, day, distance = result
    match = matching_garmin_summary(garmin_index, embedded.get("_fit_start_utc"), distance)
    info = {**embedded, **match, **{k: v for k, v in info.items() if v is not None and v != ""}}
    duplicate=matching_existing_recording(con,info,info.get('day') or day,distance)
    if duplicate is not None:
        seed_source_version(con,duplicate)
        restore_global_baseline(con,duplicate)
        enrich_matching_recording(con,duplicate,info,activity_id)
        record_source_version(con,duplicate,source_key,filename,info,result)
        apply_source_choices(con,duplicate)
        if con.execute('SELECT 1 FROM activity_source_baselines WHERE activity_id=?',(duplicate,)).fetchone():capture_global_baseline(con,duplicate,replace=True)
        apply_global_source_preferences(con,duplicate)
        con.commit()
        return 'skipped' 
    name = info.get("name") or Path(filename).name.split(".")[0]
    sport = info.get("sport") or "Unknown"
    info.setdefault('name',name)
    info.setdefault('sport',sport)
    info.setdefault('day',day)
    con.execute("INSERT OR IGNORE INTO activities (unique_key,filename,name,sport,day,distance_m,point_count,west,south,east,north,coordinates,recorded_distance_m,moving_seconds,elapsed_seconds,elevation_m,avg_heart_rate,avg_speed,max_speed,avg_power,bike,gear_id,moving_source,elevation_source,activity_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", (source_key, filename, name[:300], sport[:80], info.get("day") or day, distance, count, bbox[1], bbox[0], bbox[3], bbox[2], compressed, info.get("recorded_distance_m"), info.get("moving_seconds"), info.get("elapsed_seconds"), info.get("elevation_m"), info.get("avg_heart_rate"), info.get("avg_speed"), info.get("max_speed"), info.get("avg_power"), (info.get("bike") or "")[:160], (info.get("gear_id") or "")[:120], info.get("moving_source"), info.get("elevation_source"), activity_id))
    activity_row=con.execute("SELECT id FROM activities WHERE unique_key=?",(source_key,)).fetchone()
    if activity_row:
        store_telemetry(con,activity_row[0],info)
        record_source_version(con,activity_row[0],source_key,filename,info,result)
    values=[info.get(field) for field in ADV_NUM_FIELDS]+[(info.get("weather_condition") or None)]
    con.execute("UPDATE activities SET "+", ".join(field+"=?" for field in ADV_NUM_FIELDS+("weather_condition",))+", fit_extended_checked=? WHERE id=(SELECT id FROM activities WHERE unique_key=?)",values+[1 if filename.lower().endswith((".fit", ".fit.gz")) else 0,source_key])
    if activity_row:
        apply_source_choices(con,activity_row[0])
        apply_global_source_preferences(con,activity_row[0])
    con.commit()
    clear_render_caches()
    return "added"


def set_job(**changes):
    with STATE_LOCK:
        JOB.update(changes)
        if changes.get('status') in ('done','error'):
            JOB['serial']=int(JOB.get('serial',0))+1


def import_job(path, display_name):
    added = skipped = failed = enriched = 0
    no_gps = 0
    try:
        with db_connect() as con:
            if display_name.lower().endswith(".csv"):
                with open(path, "rb") as file:
                    is_track = gps_csv_headers(file)
                if is_track:
                    set_job(total=1,message='Reading GPS CSV track')
                    size=os.stat(path).st_size
                    if size>MAP_FORMAT_LIMIT:raise ValueError('GPS CSV exceeds the safety limit')
                    key=hashlib.sha256((display_name.casefold()+':'+str(size)+':'+hashlib.sha256(Path(path).read_bytes()).hexdigest()).encode()).hexdigest()
                    with open(path,'rb') as file:outcome=insert_activity(con,display_name,key,file,{})
                    added=int(outcome=='added');enriched=int(outcome=='enriched');no_gps=int(outcome=='no-gps');skipped=int(outcome=='skipped')
                    set_job(total=1,processed=1,added=added,skipped=skipped,no_gps=no_gps,updated=enriched)
                else:
                    with open(path, "rb") as file:lookup=metadata_from_csv(file)
                    set_job(total=1, message="Updating existing activity statistics")
                    updated=apply_metadata(con,lookup)
                    set_job(processed=1, added=0, skipped=0, failed=0, updated=updated)
            elif display_name.lower().endswith(".zip"):
                with ExitStack() as stack:
                    archive = stack.enter_context(zipfile.ZipFile(path))
                    entries = [(archive, member, False) for member in archive.infolist() if not member.is_dir() and member.filename.lower().endswith(FORMATS)]
                    for member in archive.infolist():
                        if member.is_dir() or not member.filename.lower().endswith('.csv') or Path(member.filename).name.casefold()=='activities.csv' or member.file_size>MAP_FORMAT_LIMIT:continue
                        with archive.open(member) as candidate:
                            if gps_csv_headers(io.BytesIO(candidate.read(8192))):entries.append((archive,member,False))
                    nested = [member for member in archive.infolist() if not member.is_dir() and member.filename.lower().endswith(".zip")]
                    if len(nested) > 64:
                        raise ValueError("Too many nested archives")
                    for bundle in nested:
                        if bundle.file_size > MAX_MEMBER or (bundle.file_size > 1024 * 1024 and bundle.file_size > 1000 * max(1, bundle.compress_size)):
                            raise ValueError("Nested ZIP exceeds the safety limit")
                        spool = stack.enter_context(tempfile.SpooledTemporaryFile(max_size=8 * 1024 * 1024))
                        with archive.open(bundle) as member_stream:
                            source = BoundedStream(member_stream)
                            while True:
                                chunk = source.read(1024 * 1024)
                                if not chunk:
                                    break
                                spool.write(chunk)
                        spool.seek(0)
                        inner = stack.enter_context(zipfile.ZipFile(spool))
                        for member in inner.infolist():
                            if not member.is_dir() and member.filename.lower().endswith(FORMATS):
                                entries.append((inner, member, True))
                            elif not member.is_dir() and member.filename.lower().endswith('.csv') and Path(member.filename).name.casefold()!='activities.csv' and member.file_size<=MAP_FORMAT_LIMIT:
                                with inner.open(member) as candidate:
                                    if gps_csv_headers(io.BytesIO(candidate.read(8192))):entries.append((inner,member,True))
                    if len(entries) > 30000:
                        raise ValueError("Too many activity files in one archive")
                    if sum(member.file_size for _, member, _ in entries) > 12 * 1024 * 1024 * 1024:
                        raise ValueError("Uncompressed activity data exceeds the safety limit")
                    lookup = metadata_csv(archive)
                    garmin_index = garmin_summary_index(archive)
                    if not lookup and not garmin_index and not nested:
                        print("[LibreHeatmaps] This ZIP does not contain activities.csv. Bike names and official Strava totals may be unavailable.", flush=True)
                    set_job(total=len(entries), message="Reading GPS activities", metadata_rows=len({id(v) for v in lookup.values()}) + len(garmin_index))
                    for index, (source_archive, member, is_nested) in enumerate(entries, 1):
                        safe_name = garmin_safe_filename(member.filename)
                        set_job(processed=index - 1, message=Path(safe_name).name[:110])
                        try:
                            if member.file_size > 1000 * max(1, member.compress_size) and member.file_size > 1024 * 1024:
                                raise ValueError("Archive entry has an unsafe compression ratio")
                            if member.file_size > MAX_MEMBER:
                                raise ValueError("Activity entry exceeds size limit")
                            key = hashlib.sha256((member.filename.rsplit("/", 1)[-1].casefold() + ":" + str(member.CRC) + ":" + str(member.file_size)).encode()).hexdigest()
                            with source_archive.open(member) as file:
                                outcome = insert_activity(con, safe_name, key, file, get_metadata(member.filename, lookup), garmin_index if is_nested else None)
                            if outcome == "added":
                                added += 1
                            elif outcome == "enriched":
                                enriched += 1
                            elif outcome == "no-gps":
                                no_gps += 1
                            else:
                                skipped += 1
                        except Exception as exc:
                            failed += 1
                            print("[LibreHeatmaps] Could not import {}: {}".format(Path(safe_name).name, exc), flush=True)
                        set_job(processed=index, added=added, skipped=skipped, failed=failed, no_gps=no_gps)
                    if lookup:
                        set_job(updated=enriched+apply_metadata(con, lookup))
                    else:
                        set_job(updated=enriched)
            else:
                set_job(total=1, message="Reading activity")
                size = os.stat(path).st_size
                key = hashlib.sha256((display_name.casefold() + ":" + str(size) + ":" + hashlib.sha256(Path(path).read_bytes()[:1024 * 1024]).hexdigest()).encode()).hexdigest()
                with open(path, "rb") as file:
                    outcome = insert_activity(con, display_name, key, file, {})
                if outcome == "added":
                    added = 1
                elif outcome == "enriched":
                    enriched = 1
                elif outcome == "no-gps":
                    no_gps = 1
                else:
                    skipped = 1
                set_job(processed=1, added=added, skipped=skipped, no_gps=no_gps, updated=enriched)
        with db_connect() as record_con:
            record_con.execute("INSERT INTO import_history(imported_at,label,added,skipped,no_gps,failed,updated) VALUES(?,?,?,?,?,?,?)",(dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds'),Path(display_name).name[:160],added,skipped,no_gps,failed,JOB.get('updated',0)))
            record_con.execute("DELETE FROM import_history WHERE id NOT IN (SELECT id FROM import_history ORDER BY id DESC LIMIT 30)")
        set_job(status="done", message="Import complete")
        start_heat_warmup()
    except Exception as exc:
        set_job(status="error", message=str(exc)[:400])
        print("[LibreHeatmaps] Import stopped: {}".format(exc), flush=True)
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass



def sniff_gps_name(original, path):
    if not original.casefold().endswith('.gps'):
        return original
    with Path(path).open('rb') as stream:
        head=stream.read(4096)
    cleaned=head.lstrip(b'\xef\xbb\xbf \r\n\t').lower()
    if len(head)>=12 and head[8:12]==b'.FIT':return original+'.fit'
    if b'<gpx' in cleaned:return original+'.gpx'
    if b'<trainingcenterdatabase' in cleaned:return original+'.tcx'
    if b'<kml' in cleaned:return original+'.kml'
    if b'"featurecollection"' in cleaned or b'"linestring"' in cleaned:return original+'.geojson'
    raise ValueError('Unrecognized .gps encoding; supported file contents are FIT, GPX, TCX, KML or GeoJSON')

def garmin_usb_archive_directory():
    return DB_PATH.parent / "Garmin-FIT-Archive"


def garmin_usb_roots(roots=None):
    if roots is not None:
        return [Path(root) for root in roots]
    if os.name != "nt":
        return []
    import ctypes
    mask = ctypes.windll.kernel32.GetLogicalDrives()
    return [Path("{}:\\".format(chr(65 + index))) for index in range(26) if mask & (1 << index)]


def garmin_usb_devices(roots=None):
    devices = []
    seen = set()
    for root in garmin_usb_roots(roots):
        try:
            if not root.is_dir():
                continue
            activity_dir = None
            for folder in (root / "Garmin" / "Activity", root / "Garmin" / "Activities", root / "GARMIN" / "ACTIVITY"):
                if folder.is_dir() and not folder.is_symlink():
                    activity_dir = folder
                    break
            if activity_dir is None:
                continue
            files = []
            for item in activity_dir.iterdir():
                if item.is_file() and not item.is_symlink() and item.suffix.lower() == ".fit":
                    size = item.stat().st_size
                    if 12 <= size <= 128 * 1024 * 1024:
                        files.append(item)
                if len(files) > 20000:
                    raise ValueError("Too many activities on Garmin device")
            token = hashlib.sha256(str(root.resolve()).casefold().encode("utf-8")).hexdigest()[:20]
            if token in seen:
                continue
            seen.add(token)
            devices.append({"id": token, "label": str(root), "count": len(files), "files": sorted(files, key=lambda path:path.name.casefold()), "directory": str(activity_dir)})
        except (OSError, ValueError):
            continue
    return devices


def garmin_usb_scan(roots=None):
    devices = garmin_usb_devices(roots)
    return {"devices": [{"id": device["id"], "label": device["label"], "count": device["count"]} for device in devices], "archive": str(garmin_usb_archive_directory())}


def garmin_usb_copy(source, archive):
    with source.open("rb") as file:
        header = file.read(12)
    if len(header) < 12 or header[8:12] != b".FIT":
        raise ValueError("Not a valid FIT recording")
    archive.mkdir(parents=True, exist_ok=True)
    source_hash = hashlib.sha256()
    fd, temporary = tempfile.mkstemp(prefix=".garmin-copy-", suffix=".part", dir=str(archive))
    try:
        with os.fdopen(fd, "wb") as output, source.open("rb") as recording:
            total = 0
            while True:
                chunk = recording.read(262144)
                if not chunk:
                    break
                total += len(chunk)
                if total > 128 * 1024 * 1024:
                    raise ValueError("FIT file exceeds the size limit")
                source_hash.update(chunk)
                output.write(chunk)
            output.flush()
            os.fsync(output.fileno())
        digest = source_hash.hexdigest()
        candidate = archive / source.name
        if candidate.exists():
            if hashlib.sha256(candidate.read_bytes()).hexdigest() == digest:
                return candidate, False, digest
            candidate = archive / (source.stem + "-" + digest[:12] + ".fit")
            if candidate.exists():
                if hashlib.sha256(candidate.read_bytes()).hexdigest() == digest:
                    return candidate, False, digest
                raise ValueError("FIT archive filename collision")
        os.replace(temporary, candidate)
        return candidate, True, digest
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)



 
WATCH_LOCK = threading.Lock()
WATCH_PICK_LOCK = threading.Lock()
WATCH_SEEN = {}
WATCH_STATUS = {'message':'Automatic import is off until you select a folder.', 'added':0, 'skipped':0, 'failed':0, 'last_scan':None}
WATCH_SUFFIXES = FORMATS + ('.gps','.csv')

def watch_seen_key(folder_name, source):
    return 'watch_seen:'+hashlib.sha256((folder_name+'\x00'+str(source)).encode('utf-8')).hexdigest()


def load_watch_folder():
    with db_connect() as con:
        row=con.execute("SELECT value FROM app_settings WHERE key='watch_folder'").fetchone()
    return row[0] if row else ''


def normalize_watch_folder(value):
    if type(value) is not str or len(value)>1024 or '\x00' in value:
        raise ValueError('Invalid watched folder path')
    value=value.strip()
    if not value:return ''
    folder=Path(value).expanduser()
    if not folder.is_absolute() or not folder.is_dir():
        raise ValueError('Choose an existing folder using its absolute path')
    if folder.is_symlink():
        raise ValueError('Choose a regular directory, not a linked folder')
    return str(folder.resolve())


def pick_watch_folder():
    if not WATCH_PICK_LOCK.acquire(blocking=False):
        raise ValueError('A folder selection dialog is already open')
    try:
        try:
            import tkinter as tk
            from tkinter import filedialog
        except ImportError as exc:
            raise ValueError('Folder chooser is unavailable; paste the full folder path instead') from exc
        root=None
        try:
            root=tk.Tk()
            root.withdraw()
            root.attributes('-topmost', True)
            selected=filedialog.askdirectory(parent=root,title='Select an automatic activity import folder',initialdir=load_watch_folder() or str(Path.home()),mustexist=True)
        except (tk.TclError, OSError) as exc:
            raise ValueError('The native folder chooser is unavailable; enter the full folder path instead') from exc
        finally:
            if root is not None:root.destroy()
        return {'folder':normalize_watch_folder(selected) if selected else None}
    finally:
        WATCH_PICK_LOCK.release()


def watch_folder_status():
    with WATCH_LOCK:
        status=dict(WATCH_STATUS)
    return {'folder':load_watch_folder(),**status}


def watch_folder_scan():
    folder_name=load_watch_folder()
    if not folder_name:
        with WATCH_LOCK:WATCH_STATUS.update(message='Automatic import is off; designate a local or shared folder in Settings.')
        return
    folder=Path(folder_name)
    try:
        if not folder.is_dir():
            raise OSError('Watched folder is disconnected or unavailable')
        candidates=[]
        with db_connect() as seen_con:
            seen_disk=dict(seen_con.execute("SELECT key,value FROM app_settings WHERE key LIKE 'watch_seen:%'"))
        for source in folder.iterdir():
            if not source.is_file() or source.is_symlink() or not source.name.lower().endswith(WATCH_SUFFIXES):continue
            stat=source.stat()
            if stat.st_size<12 or stat.st_size>128*1024*1024 or time.time()-stat.st_mtime<5:continue
            if source.name.lower().endswith('.csv'):
                with source.open('rb') as candidate:
                    if not gps_csv_headers(candidate):continue
            fingerprint=(stat.st_size,stat.st_mtime_ns)
            with WATCH_LOCK:
                if WATCH_SEEN.get((folder_name,str(source)))==fingerprint:continue
            if seen_disk.get(watch_seen_key(folder_name,source))=='{}:{}'.format(*fingerprint):continue
            candidates.append((source,fingerprint))
            if len(candidates)>20000:raise ValueError('Too many new activity files in watched folder')
        if not candidates:
            with WATCH_LOCK:WATCH_STATUS.update(message='Watching this folder for new activity files',last_scan=dt.datetime.now().isoformat(timespec='seconds'))
            return
        with STATE_LOCK:
            if JOB.get('status')=='running':return
            JOB.update(status='running',processed=0,total=len(candidates),added=0,skipped=0,failed=0,no_gps=0,updated=0,message='Importing watched activity files')
        added=skipped=failed=no_gps=0
        try:
            with db_connect() as con:
                for index,(source,fingerprint) in enumerate(candidates,1):
                    set_job(processed=index-1,message=source.name[:100])
                    try:
                        display=source.name
                        if display.casefold().endswith('.gps'):
                            with source.open('rb') as inspect:
                                header=inspect.read(4096)
                            stripped=header.lstrip(b'\xef\xbb\xbf \r\n\t')
                            if len(header)>=12 and header[8:12]==b'.FIT':display=source.name+'.fit'
                            elif b'<gpx' in stripped.lower():display=source.name+'.gpx'
                            elif b'<trainingcenterdatabase' in stripped.lower():display=source.name+'.tcx'
                            elif b'<kml' in stripped.lower():display=source.name+'.kml'
                            elif b'"featurecollection"' in stripped.lower() or b'"linestring"' in stripped.lower():display=source.name+'.geojson'
                            else:raise ValueError('Unrecognized .gps encoding; supported file contents are FIT, GPX, TCX, KML or GeoJSON')
                        with source.open('rb') as stream:
                            hasher=hashlib.sha256()
                            while True:
                                part=stream.read(256*1024)
                                if not part:break
                                hasher.update(part)
                            digest=hasher.hexdigest()
                        key=hashlib.sha256(('watched:'+digest).encode('ascii')).hexdigest()
                        with source.open('rb') as stream:
                            outcome=insert_activity(con,display,key,stream,{})
                        if outcome=='added':added+=1
                        elif outcome=='no-gps':no_gps+=1
                        else:skipped+=1
                        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",(watch_seen_key(folder_name,source),'{}:{}'.format(*fingerprint)))
                    except (ValueError,OSError,EOFError,sqlite3.Error,gzip.BadGzipFile,ET.ParseError) as exc:
                        failed+=1
                        print('[LibreHeatmaps] Watched folder import skipped {}: {}'.format(source.name,exc),flush=True)
                    finally:
                        with WATCH_LOCK:WATCH_SEEN[(folder_name,str(source))]=fingerprint
                        set_job(processed=index,added=added,skipped=skipped,no_gps=no_gps,failed=failed)
                con.execute('INSERT INTO import_history(imported_at,label,added,skipped,no_gps,failed,updated) VALUES(?,?,?,?,?,?,?)',
                    (dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds'),'Watched folder',added,skipped,no_gps,failed,0))
                con.execute('DELETE FROM import_history WHERE id NOT IN (SELECT id FROM import_history ORDER BY id DESC LIMIT 30)')
            set_job(status='done',message='Watched folder: {} added, {} already imported, {} failed'.format(added,skipped,failed))
            if added:start_heat_warmup()
            with WATCH_LOCK:WATCH_STATUS.update(message='Last scan: {} new activities'.format(added),added=added,skipped=skipped,failed=failed,last_scan=dt.datetime.now().isoformat(timespec='seconds'))
        except Exception:
            set_job(status='error',message='Watched folder import failed; see application log')
            raise
    except (OSError,ValueError,sqlite3.Error) as exc:
        with WATCH_LOCK:WATCH_STATUS.update(message=str(exc)[:250],last_scan=dt.datetime.now().isoformat(timespec='seconds'))
        print('[LibreHeatmaps] Watched folder: {}'.format(exc),flush=True)


def watch_folder_loop():
    while True:
        try:watch_folder_scan()
        except Exception as exc:print('[LibreHeatmaps] Watched folder scan error: {}'.format(exc),flush=True)
        time.sleep(15)


 
 
GARMIN_PERSONAL_BASE = 'https://personal.connectapi.garmin.com'
GARMIN_PERSONAL_KEY_NAME = 'garmin-personal-api.key'
GARMIN_SYNC_LOCK = threading.Lock()
GARMIN_STATUS_LOCK = threading.Lock()
GARMIN_SCHEDULE_LOCK = threading.Lock()
GARMIN_LAST_ATTEMPT_MONO = 0.0
GARMIN_TOKEN_LOCK = threading.Lock()
GARMIN_TOKEN_CACHE = {'key_fingerprint': None, 'bearer': '', 'expires_at': 0}
GARMIN_HISTORY_PAGE_SIZE = 100
 
 
GARMIN_HISTORY_RETRY_SECONDS = 900
GARMIN_HISTORY_RATE_LIMIT_SECONDS = 3600
GARMIN_HISTORY_REQUEST_DELAY_SECONDS = 1.0
GARMIN_STATUS = {'running': False, 'message': 'Connect your personal Garmin API key to enable wireless activity sync.', 'last_sync': None, 'added': 0, 'skipped': 0, 'failed': 0, 'checked': 0, 'discovered': 0, 'authenticated': False, 'first_error': '', 'last_attempt': None}


class GarminPersonalHTTPError(ValueError):
    def __init__(self, status_code, message):
        super().__init__(message)
        self.status_code = status_code


def garmin_clear_token():
    with GARMIN_TOKEN_LOCK:
        GARMIN_TOKEN_CACHE.update(key_fingerprint=None, bearer='', expires_at=0)



def garmin_personal_key_path():
    return DB_PATH.parent / GARMIN_PERSONAL_KEY_NAME


def garmin_personal_key():
    keyfile = garmin_personal_key_path()
    if not keyfile.is_file() or keyfile.is_symlink():
        return ''
    return keyfile.read_text(encoding='ascii').strip()


def garmin_history_state():
     
     
    with db_connect() as con:
        rows=dict(con.execute("SELECT key,value FROM app_settings WHERE key LIKE 'garmin_history_%'"))
    def nonnegative(key, default=0):
        try:return max(0,int(rows.get(key,str(default))))
        except (TypeError,ValueError):return default
     
     
    last_message = rows.get('garmin_history_message', '')
    resume_at = nonnegative('garmin_history_next_after')
    if 'Next batch scheduled' in last_message:
        resume_at = 0
    return {
        'active': rows.get('garmin_history_active')=='1',
        'completed': rows.get('garmin_history_completed')=='1',
        'cursor': nonnegative('garmin_history_cursor'),
        'reviewed': nonnegative('garmin_history_reviewed'),
        'imported': nonnegative('garmin_history_imported'),
        'map_batch_size': 50,
        'ready_map_batches': nonnegative('garmin_history_imported') // 50,
        'next_after': resume_at,
        'message': last_message if last_message and 'Next batch scheduled' not in last_message else 'Full-history import can continue without batch pauses.',
    }


def garmin_history_write(**values):
    if not values:return
    with db_connect() as con:
        for k,v in values.items():
            if k not in ('active','completed','cursor','reviewed','imported','next_after','message'):
                raise ValueError('Invalid Garmin history state field')
            con.execute('INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)',('garmin_history_'+k,str(int(v) if isinstance(v,bool) else v)[:280]))


def garmin_history_start():
    if not garmin_personal_key():raise ValueError('Connect Garmin first')
    with STATE_LOCK:
        if JOB.get('status')=='running':raise ValueError('Wait for the current import to finish')
    if GARMIN_SYNC_LOCK.locked():raise ValueError('Garmin synchronization is already running')
    state=garmin_history_state()
    if state['completed']:
        garmin_history_write(cursor=0,reviewed=0,imported=0,completed=0)
     
    due=state['next_after'] if state['next_after']>time.time() else 0
    garmin_history_write(active=1,next_after=due,message='Importing full Garmin account history continuously…' if not due else 'Garmin requested a cooldown. Full history will resume after the retry window.')
    return garmin_history_state()


def garmin_history_pause():
    garmin_history_write(active=0,message='Historical import paused. Select Resume full import to continue; imported rides stay in the library.')
    return garmin_history_state()


def garmin_personal_status():
    with GARMIN_STATUS_LOCK:
        state = dict(GARMIN_STATUS)
    state['connected'] = bool(garmin_personal_key())
    if state['connected'] and state['message'].startswith('Connect your personal Garmin API key'):
        state['message'] = 'Saved Garmin key found. Automatic verification will run at startup; Sync now checks immediately.'
    state['method'] = 'Garmin Connect Personal API (not direct Edge-to-PC Wi-Fi)'
    state['sync_interval_minutes'] = load_garmin_sync_minutes()
    state['history'] = garmin_history_state()
    return state


def garmin_personal_store_key(value):
    if not isinstance(value, str) or not 12 <= len(value) <= 1024 or not value.isascii() or any(c.isspace() or ord(c) < 33 or ord(c) > 126 for c in value):
        raise ValueError('Enter the personal API key generated in your own Garmin Connect account')
    target = garmin_personal_key_path()
    previous_key = garmin_personal_key()
    fd, temp = tempfile.mkstemp(prefix='.garmin-key-', dir=str(target.parent))
    try:
        os.chmod(temp, 0o600)
        with os.fdopen(fd, 'w', encoding='ascii') as output:
            output.write(value)
            output.flush()
            os.fsync(output.fileno())
        os.replace(temp, target)
        if os.name != 'nt':
            os.chmod(target, 0o600)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)
    garmin_clear_token()
     
     
    if previous_key != value:
        garmin_history_write(active=0,completed=0,cursor=0,reviewed=0,imported=0,next_after=0,message='Not started for this Garmin connection.')
    global GARMIN_LAST_ATTEMPT_MONO
    with GARMIN_SCHEDULE_LOCK:
        GARMIN_LAST_ATTEMPT_MONO = 0.0   
    with GARMIN_STATUS_LOCK:
        GARMIN_STATUS.update(message='Garmin key saved locally but not yet verified. Select Sync now to test access.', last_sync=None, last_attempt=None, authenticated=False, first_error='')
    return garmin_personal_status()


def garmin_personal_disconnect():
    garmin_history_write(active=0,next_after=0,message='Historical import paused because Garmin was disconnected.')
     
     
    garmin_personal_key_path().unlink(missing_ok=True)
    garmin_clear_token()
    global GARMIN_LAST_ATTEMPT_MONO
    with GARMIN_SCHEDULE_LOCK:
        GARMIN_LAST_ATTEMPT_MONO = 0.0
    with GARMIN_STATUS_LOCK:
        GARMIN_STATUS.update(message='Garmin wireless sync is disconnected on this PC.', last_sync=None, last_attempt=None, running=False, authenticated=False, first_error='')
    return garmin_personal_status()


def garmin_personal_http(method, route, token, *, limit=8*1024*1024, accept="*/*"):
    if not route.startswith('/') or '://' in route or '\\' in route:
        raise ValueError('Invalid Garmin API route')
    req = Request(GARMIN_PERSONAL_BASE + route, method=method, headers={'Authorization': token, 'Accept': accept, 'User-Agent': 'LibreHeatmaps/'+VERSION})
    try:
        with urlopen(req, timeout=25) as response:
            declared = response.headers.get('Content-Length')
            if declared and int(declared) > limit:
                raise ValueError('Garmin download exceeds the safety limit')
            body = response.read(limit+1)
    except HTTPError as exc:
        if exc.code == 401:
            raise GarminPersonalHTTPError(401, 'Garmin authentication was rejected (HTTP 401)') from None
        if exc.code == 403:
            raise GarminPersonalHTTPError(403, 'Garmin denied access (HTTP 403); check Personal API key permissions or expiration') from None
        if exc.code == 429:
            raise GarminPersonalHTTPError(429, 'Garmin rate limit reached (HTTP 429); try again later') from None
        if exc.code == 406:
            raise GarminPersonalHTTPError(406, 'Garmin rejected the response format (HTTP 406)') from None
        raise GarminPersonalHTTPError(exc.code, 'Garmin API returned HTTP {}'.format(exc.code)) from None
    except (URLError, TimeoutError) as exc:
        raise ValueError('Could not reach Garmin Connect securely: {}'.format(type(exc).__name__)) from exc
    if len(body)>limit:
        raise ValueError('Garmin download exceeds the safety limit')
    return body


def garmin_personal_access_token(api_key, force_refresh=False):
     
    fingerprint = hashlib.sha256(api_key.encode('ascii')).hexdigest()
    with GARMIN_TOKEN_LOCK:
        if (not force_refresh and GARMIN_TOKEN_CACHE['key_fingerprint'] == fingerprint
                and GARMIN_TOKEN_CACHE['expires_at'] > time.time() + 3600):
            return GARMIN_TOKEN_CACHE['bearer']
    raw = garmin_personal_http('POST','/personalapitoken-service/personal-api/personal-api-key/token',
                               'ApiKey '+api_key,limit=65536,accept='*/*')
    try:
        token = raw.decode('ascii').strip()
        pieces = token.split('.')
        if len(pieces) != 3 or not all(pieces) or not 60 <= len(token) <= 20000:
            raise ValueError('Invalid token format')
        payload = json.loads(base64.urlsafe_b64decode(pieces[1]+'='*(-len(pieces[1])%4)))
        if not isinstance(payload,dict) or not isinstance(payload.get('exp'),(int,float)):
            raise ValueError('Missing token expiry')
        if payload['exp'] < time.time()+30:
            raise ValueError('Expired token')
    except (UnicodeError, ValueError, IndexError, TypeError, base64.binascii.Error):
        raise ValueError('Garmin did not return a valid bearer token; check your Personal API key') from None
    bearer='Bearer '+token
    with GARMIN_TOKEN_LOCK:
        GARMIN_TOKEN_CACHE.update(key_fingerprint=fingerprint,bearer=bearer,expires_at=float(payload['exp']))
    return bearer


def garmin_personal_activity_ids(bearer, max_items=25):
    if type(max_items) is not int or not 1 <= max_items <= 100:
        raise ValueError("Garmin recent activity count must be from 1 to 100")
    found=[]
    for start in range(0,max_items,100):
        page_size=min(100,max_items-start)
        route='/activitylist-service/activities/search/activities?start={}&limit={}'.format(start,page_size)
         
        data=json.loads(garmin_personal_http('GET',route,bearer,limit=8*1024*1024,accept='application/json'))
        if not isinstance(data,list):
            raise ValueError('Unexpected Garmin activity list response')
        for item in data:
            if isinstance(item,dict):
                aid=item.get('activityId') or item.get('activity_id')
                if isinstance(aid,int) and 0 < aid < 10**18:
                    found.append(aid)
        if len(data)<page_size:
            break
    return list(dict.fromkeys(found))[:max_items]



def garmin_personal_activity_page(bearer, start, limit=GARMIN_HISTORY_PAGE_SIZE):
    if not isinstance(start,int) or not 0<=start<=1000000 or limit!=GARMIN_HISTORY_PAGE_SIZE:
        raise ValueError('Invalid Garmin history page')
    route='/activitylist-service/activities/search/activities?start={}&limit={}'.format(start,limit)
    data=json.loads(garmin_personal_http('GET',route,bearer,limit=8*1024*1024,accept='application/json'))
    if not isinstance(data,list):raise ValueError('Unexpected Garmin activity list response')
    if len(data)>limit:raise ValueError('Garmin returned more activities than requested')
    ids=[]
    for item in data:
        aid=(item.get('activityId') or item.get('activity_id')) if isinstance(item,dict) else None
        ids.append(aid if isinstance(aid,int) and 0<aid<10**18 else None)
    return ids


def garmin_retry_auth_request(callback, api_key, bearer):
     
    try:
        return callback(bearer),bearer
    except GarminPersonalHTTPError as exc:
        if exc.status_code != 401:
            raise
    bearer=garmin_personal_access_token(api_key,force_refresh=True)
    return callback(bearer),bearer


def garmin_personal_save_fit(folder_name, activity_id, source_name, raw):
     
     
    folder=Path(folder_name)
    if not folder.is_dir() or folder.is_symlink():
        raise ValueError('The selected activity folder is no longer available')
    if len(raw)<12 or raw[8:12]!=b'.FIT':
        raise ValueError('Downloaded Garmin recording is not a FIT file')
    clean=re.sub(r'[^A-Za-z0-9._-]+','-',Path(source_name).name)[:100].strip('.-_')
    if not clean.casefold().endswith('.fit'):
        clean='activity.fit'
    digest=hashlib.sha256(raw).hexdigest()
    filename='Garmin-{}-{}'.format(activity_id,clean)
    target=folder/filename
    if target.exists():
        if target.is_symlink():raise ValueError('Cannot overwrite linked activity files')
        if hashlib.sha256(target.read_bytes()).hexdigest()==digest:
            return target,False
        target=folder/('Garmin-{}-{}.fit'.format(activity_id,digest[:16]))
        if target.exists():
            if target.is_symlink() or hashlib.sha256(target.read_bytes()).hexdigest()!=digest:
                raise ValueError('Garmin activity filename collision')
            return target,False
    fd,temporary=tempfile.mkstemp(prefix='.garmin-transfer-',suffix='.part',dir=str(folder))
    try:
        with os.fdopen(fd,'wb') as output:
            output.write(raw)
            output.flush()
            os.fsync(output.fileno())
        os.replace(temporary,target)
        return target,True
    finally:
        if os.path.exists(temporary):os.unlink(temporary)


def garmin_personal_import_zip(con, content, activity_id, destination=None):
    if not zipfile.is_zipfile(io.BytesIO(content)):
        raise ValueError('Garmin activity download is not a valid ZIP')
    added=skipped=no_gps=stored=save_failures=0
    with zipfile.ZipFile(io.BytesIO(content)) as archive:
        members=[m for m in archive.infolist() if not m.is_dir() and m.filename.lower().endswith(FORMATS)]
        if not members or len(members)>10 or sum(m.file_size for m in members)>128*1024*1024:
            raise ValueError('Garmin activity archive contains no supported recordings or is too large')
        for member in members:
            if member.file_size>MAX_MEMBER or (member.file_size>1024*1024 and member.file_size>1000*max(1,member.compress_size)):
                raise ValueError('Unsafe Garmin activity ZIP entry')
            display='Garmin/{}-{}'.format(activity_id,Path(member.filename).name)
            source_key=hashlib.sha256(('garmin-personal:{}:{}:{}'.format(activity_id,member.CRC,member.file_size)).encode()).hexdigest()
            with archive.open(member) as stream:
                raw=BoundedStream(stream,128*1024*1024).read()
            result=insert_activity(con,display,source_key,io.BytesIO(raw),{})
            if result=='added':added+=1
            elif result=='no-gps':no_gps+=1
            else:skipped+=1
            if destination and member.filename.casefold().endswith('.fit'):
                try:
                    target,was_new=garmin_personal_save_fit(destination,activity_id,member.filename,raw)
                    if was_new:stored+=1
                    fingerprint=target.stat()
                    seen=(fingerprint.st_size,fingerprint.st_mtime_ns)
                    con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",(watch_seen_key(destination,target),'{}:{}'.format(*seen)))
                    with WATCH_LOCK:WATCH_SEEN[(destination,str(target))]=seen
                except (OSError,ValueError):
                     
                    save_failures+=1
    return added,skipped,no_gps,stored,save_failures


def garmin_local_activity_ids(con):
     
     
    present=set()
    for (filename,) in con.execute("SELECT filename FROM activities WHERE filename LIKE 'Garmin/%' OR filename LIKE 'Garmin-%'"):
        match=re.match(r"(?i)^garmin[/\-]([0-9]{1,18})-",filename)
        if match:
            present.add(int(match.group(1)))
    return present


def garmin_personal_sync_job():
    global GARMIN_LAST_ATTEMPT_MONO
    if not GARMIN_SYNC_LOCK.acquire(blocking=False):
        return
    started = False
    try:
        key=garmin_personal_key()
        if not key:
            return
        with STATE_LOCK:
            if JOB.get('status')=='running':
                return
            JOB.update(status='running',processed=0,total=0,added=0,skipped=0,failed=0,no_gps=0,updated=0,message='Checking Garmin Connect for wireless rides')
        started = True
        with GARMIN_STATUS_LOCK:
            GARMIN_STATUS.update(running=True,message='Checking Garmin account and recent rides…',first_error='',last_attempt=dt.datetime.now().isoformat(timespec='seconds'))
        added=skipped=failed=no_gps=checked=saved=save_failures=0
        discovered=0
        folder_warning=''
        stage='authentication'
        try:
            folder_name=load_watch_folder()
            if folder_name and (not Path(folder_name).is_dir() or Path(folder_name).is_symlink()):
                 
                folder_warning=' Selected activity folder unavailable; originals were not saved there.'
                folder_name=''
            folder_id=hashlib.sha256(folder_name.encode('utf-8')).hexdigest() if folder_name else ''
            bearer=garmin_personal_access_token(key)
            stage='activity discovery'
            ids,bearer=garmin_retry_auth_request(lambda active: garmin_personal_activity_ids(active,load_garmin_recent_count()),key,bearer)
            discovered=len(ids)
            with GARMIN_STATUS_LOCK:
                GARMIN_STATUS.update(authenticated=True,discovered=discovered,message='Garmin access verified; comparing {} recent activities…'.format(discovered))
            with db_connect() as con:
                 
                 
                local_ids=garmin_local_activity_ids(con)
                stored=dict(con.execute("SELECT key,value FROM app_settings WHERE key LIKE 'garmin_personal_saved:%' OR key LIKE 'garmin_personal_nogps:%'"))
                pending=[aid for aid in reversed(ids) if
                    (aid not in local_ids and 'garmin_personal_nogps:'+str(aid) not in stored)
                    or (folder_name and stored.get('garmin_personal_saved:'+str(aid))!=folder_id)]
                set_job(total=len(pending),message='Downloading missing Garmin activity recordings')
                stage='activity download'
                first_error=''
                for index,aid in enumerate(pending,1):
                    if garmin_personal_key() != key:
                        raise ValueError('Garmin connection changed or was removed')
                    checked+=1
                    set_job(processed=index-1,message='Garmin activity {} ({} of {})'.format(aid,index,len(pending)))
                    try:
                        callback=lambda active: garmin_personal_http('GET','/download-service/files/activity/{}'.format(aid),active,limit=128*1024*1024,accept='application/zip, application/x-zip-compressed, application/octet-stream')
                        content,bearer=garmin_retry_auth_request(callback,key,bearer)
                        a,s,n,stored_count,save_error_count=garmin_personal_import_zip(con,content,aid,folder_name or None)
                        added+=a;skipped+=s;no_gps+=n;saved+=stored_count;save_failures+=save_error_count
                         
                         
                        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",('garmin_personal_synced:'+str(aid),dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')))
                        if n and not a and not s:
                            con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",('garmin_personal_nogps:'+str(aid),'1'))
                        else:
                            con.execute("DELETE FROM app_settings WHERE key=?",('garmin_personal_nogps:'+str(aid),))
                        if folder_name and not save_error_count:
                            con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",('garmin_personal_saved:'+str(aid),folder_id))
                        con.commit()
                    except (ValueError,zipfile.BadZipFile,sqlite3.Error,EOFError,OSError) as exc:
                        failed+=1
                        if not first_error:
                            first_error='Activity {}: {}'.format(aid,str(exc)[:115])
                        con.rollback()
                        if isinstance(exc,GarminPersonalHTTPError) and exc.status_code==429:
                             
                            break
                    set_job(processed=index,added=added,skipped=skipped,failed=failed,no_gps=no_gps)
                if pending:
                    con.execute('INSERT INTO import_history(imported_at,label,added,skipped,no_gps,failed,updated) VALUES(?,?,?,?,?,?,?)',(dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds'),'Garmin wireless (Personal API)',added,skipped,no_gps,failed,0))
                    con.execute('DELETE FROM import_history WHERE id NOT IN (SELECT id FROM import_history ORDER BY id DESC LIMIT 30)')
                    con.commit()
            if garmin_personal_key() != key:
                set_job(status='error',message='Garmin connection removed or changed during sync')
                return
            message='Garmin: {} new rides, {} previously imported, {} download failures; {} of {} recent activities downloaded.'.format(added,skipped,failed,checked,discovered)
            if saved:message+=' {} original FIT files saved.'.format(saved)
            if save_failures:message+=' {} optional original-file saves failed.'.format(save_failures)
            if first_error:message+=' '+first_error
            message+=folder_warning
            if not checked and not failed:message='Garmin account verified. No missing rides among the {} most recent activities checked. For older recordings, choose Import full history in Settings.'.format(discovered)+folder_warning
            set_job(status='error' if failed else 'done',message=message)
            with GARMIN_STATUS_LOCK:
                GARMIN_STATUS.update(running=False,last_sync=dt.datetime.now().isoformat(timespec='seconds'),message=message,added=added,skipped=skipped,failed=failed,checked=checked,discovered=discovered,stored=saved,first_error=first_error,authenticated=True)
            if added:start_heat_warmup()
        except Exception as exc:
             
            message='Garmin '+stage+' failed: '+str(exc)[:160]
            set_job(status='error',message=message)
            with GARMIN_STATUS_LOCK:
                auth_rejected=(isinstance(exc,GarminPersonalHTTPError) and exc.status_code in (401,403))
                GARMIN_STATUS.update(running=False,message=message,failed=failed,first_error=message,authenticated=False if stage=='authentication' or auth_rejected else GARMIN_STATUS.get('authenticated',False))
    finally:
        if started:
            with GARMIN_SCHEDULE_LOCK:
                GARMIN_LAST_ATTEMPT_MONO = time.monotonic()
        GARMIN_SYNC_LOCK.release()



def garmin_personal_history_job():
    global GARMIN_LAST_ATTEMPT_MONO
     
     
     
    if not GARMIN_SYNC_LOCK.acquire(blocking=False):
        return
    try:
        key = garmin_personal_key()
        history = garmin_history_state()
        if not key or not history['active'] or time.time() < history['next_after']:
            return
        with STATE_LOCK:
            if JOB.get('status') == 'running':
                return
            JOB.update(status='running', source='garmin_history', processed=history['reviewed'], total=0,
                       added=history['imported'], skipped=0, failed=0, no_gps=0,
                       updated=0, message='Importing full Garmin account history')
        with GARMIN_STATUS_LOCK:
            GARMIN_STATUS.update(running=True, first_error='',
                                 message='Importing Garmin history: {} reviewed, {} new rides'.format(
                                     history['reviewed'], history['imported']))
        stage = 'historical activity discovery'
        added_session = skipped_session = 0
        try:
            bearer = garmin_personal_access_token(key)
            folder = load_watch_folder()
            if not folder or not Path(folder).is_dir() or Path(folder).is_symlink():
                folder = ''
            folder_id = hashlib.sha256(folder.encode('utf-8')).hexdigest() if folder else ''
            with db_connect() as con:
                present = garmin_local_activity_ids(con)
                saved = dict(con.execute("SELECT key,value FROM app_settings WHERE key LIKE 'garmin_personal_saved:%' OR key LIKE 'garmin_personal_nogps:%'"))
            while True:
                history = garmin_history_state()
                if not history['active'] or garmin_personal_key() != key:
                    message = 'Garmin history paused at {} activities; {} new rides imported.'.format(
                        history['reviewed'], history['imported'])
                    garmin_history_write(active=0, message=message)
                    set_job(status='done', message=message, processed=history['reviewed'], added=history['imported'])
                    with GARMIN_STATUS_LOCK:
                        GARMIN_STATUS.update(running=False, message=message)
                    if added_session:
                        start_heat_warmup()
                    return
                if time.time() < history['next_after']:
                    return
                offset = history['cursor']
                stage = 'historical activity discovery'
                ids, bearer = garmin_retry_auth_request(
                    lambda b: garmin_personal_activity_page(b, offset), key, bearer)
                if not ids:
                    final = 'Full Garmin history complete: {} activities reviewed; {} new rides imported. Original GPS files preserved.'.format(
                        history['reviewed'], history['imported'])
                    garmin_history_write(active=0, completed=1, next_after=0, message=final)
                    set_job(status='done', message=final, processed=history['reviewed'], added=history['imported'])
                    with GARMIN_STATUS_LOCK:
                        GARMIN_STATUS.update(running=False, authenticated=True, message=final,
                                             added=history['imported'], checked=history['reviewed'])
                    with GARMIN_SCHEDULE_LOCK:
                        GARMIN_LAST_ATTEMPT_MONO = time.monotonic()
                    if added_session:
                        start_heat_warmup()
                    return
                set_job(total=0, message='Scanning Garmin history: {} reviewed'.format(offset))
                for aid in ids:
                    history = garmin_history_state()
                    if not history['active'] or garmin_personal_key() != key:
                        break
                    newly_added = 0
                    needs = (aid is not None and (
                        (aid not in present and 'garmin_personal_nogps:' + str(aid) not in saved)
                        or (folder and saved.get('garmin_personal_saved:' + str(aid)) != folder_id)))
                    if needs:
                        stage = 'historical FIT download'
                        try:
                            callback = lambda b: garmin_personal_http(
                                'GET', '/download-service/files/activity/{}'.format(aid), b,
                                limit=128*1024*1024,
                                accept='application/zip, application/x-zip-compressed, application/octet-stream')
                            content, bearer = garmin_retry_auth_request(callback, key, bearer)
                        except (ValueError, OSError, EOFError) as exc:
                             
                            delay = (GARMIN_HISTORY_RATE_LIMIT_SECONDS if isinstance(exc, GarminPersonalHTTPError)
                                     and exc.status_code == 429 else GARMIN_HISTORY_RETRY_SECONDS)
                            unauthorized = isinstance(exc, GarminPersonalHTTPError) and exc.status_code in (401, 403)
                            reason = 'Garmin activity {} failed: {}. No rides were deleted.'.format(aid, str(exc)[:150])
                            garmin_history_write(active=not unauthorized,
                                next_after=0 if unauthorized else int(time.time()+delay),
                                message=reason + (' Reconnect Garmin to continue.' if unauthorized else ' Automatic retry is scheduled.'))
                            set_job(status='error', message=reason, failed=1)
                            with GARMIN_STATUS_LOCK:
                                GARMIN_STATUS.update(running=False, first_error=reason, message=reason, failed=1)
                            if added_session:
                                start_heat_warmup()
                            return
                    try:
                        with db_connect() as con:
                            if needs:
                                a, sk, n, stored_count, save_errors = garmin_personal_import_zip(
                                    con, content, aid, folder or None)
                                newly_added = a
                                added_session += a
                                skipped_session += sk
                                if a:
                                    present.add(aid)
                                if n and not a and not sk:
                                    con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",
                                                ('garmin_personal_nogps:'+str(aid), '1'))
                                    saved['garmin_personal_nogps:'+str(aid)] = '1'
                                else:
                                    con.execute("DELETE FROM app_settings WHERE key=?", ('garmin_personal_nogps:'+str(aid),))
                                    saved.pop('garmin_personal_nogps:'+str(aid), None)
                                if folder and not save_errors:
                                    con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",
                                                ('garmin_personal_saved:'+str(aid), folder_id))
                                    saved['garmin_personal_saved:'+str(aid)] = folder_id
                                con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",
                                            ('garmin_personal_synced:'+str(aid), dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')))
                            else:
                                skipped_session += 1
                            con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('garmin_history_cursor',?)", (str(offset+1),))
                            con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('garmin_history_reviewed',?)", (str(history['reviewed']+1),))
                            con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('garmin_history_imported',?)", (str(history['imported']+newly_added),))
                    except (ValueError, zipfile.BadZipFile, sqlite3.Error, EOFError, OSError) as exc:
                        reason = 'Garmin activity {} could not be imported: {}'.format(aid, str(exc)[:150])
                        garmin_history_write(active=True, next_after=int(time.time()+GARMIN_HISTORY_RETRY_SECONDS),
                                             message=reason+' Automatic retry is scheduled.')
                        set_job(status='error', message=reason, failed=1)
                        with GARMIN_STATUS_LOCK:
                            GARMIN_STATUS.update(running=False, first_error=reason, message=reason, failed=1)
                        if added_session:
                            start_heat_warmup()
                        return
                    offset += 1
                    set_job(processed=history['reviewed']+1, added=history['imported']+newly_added,
                            skipped=skipped_session,
                            message='Garmin full history: {} reviewed, {} new rides imported'.format(
                                history['reviewed']+1, history['imported']+newly_added))
                    with GARMIN_STATUS_LOCK:
                        GARMIN_STATUS.update(running=True, authenticated=True, checked=history['reviewed']+1,
                                             added=history['imported']+newly_added,
                                             message='Full history: {} activities checked; {} imported'.format(
                                                 history['reviewed']+1, history['imported']+newly_added))
                    if needs and GARMIN_HISTORY_REQUEST_DELAY_SECONDS:
                        time.sleep(GARMIN_HISTORY_REQUEST_DELAY_SECONDS)
                if len(ids) < GARMIN_HISTORY_PAGE_SIZE and garmin_history_state()['active']:
                     
                    final_state = garmin_history_state()
                    final = 'Full Garmin history complete: {} activities reviewed; {} new rides imported. Original files untouched.'.format(
                        final_state['reviewed'], final_state['imported'])
                    garmin_history_write(active=0, completed=1, next_after=0, message=final)
                    set_job(status='done', message=final, processed=final_state['reviewed'], added=final_state['imported'])
                    with GARMIN_STATUS_LOCK:
                        GARMIN_STATUS.update(running=False, authenticated=True, message=final,
                                             added=final_state['imported'], checked=final_state['reviewed'])
                    with GARMIN_SCHEDULE_LOCK:
                        GARMIN_LAST_ATTEMPT_MONO = time.monotonic()
                    if added_session:
                        start_heat_warmup()
                    return
                 
                if GARMIN_HISTORY_REQUEST_DELAY_SECONDS:
                    time.sleep(GARMIN_HISTORY_REQUEST_DELAY_SECONDS)
        except Exception as exc:
            reason = 'Garmin '+stage+' failed: '+str(exc)[:150]
            delay = (GARMIN_HISTORY_RATE_LIMIT_SECONDS if isinstance(exc, GarminPersonalHTTPError)
                     and exc.status_code == 429 else GARMIN_HISTORY_RETRY_SECONDS)
            unauthorized = isinstance(exc, GarminPersonalHTTPError) and exc.status_code in (401,403)
            garmin_history_write(active=not unauthorized,
                                 next_after=0 if unauthorized else int(time.time()+delay),
                                 message=reason+(' Reconnect Garmin to continue.' if unauthorized else ' Automatic retry is scheduled.'))
            set_job(status='error', message=reason)
            with GARMIN_STATUS_LOCK:
                GARMIN_STATUS.update(running=False, first_error=reason, message=reason)
            if added_session:
                start_heat_warmup()
    finally:
        GARMIN_SYNC_LOCK.release()


def garmin_auto_sync_due(now=None):
    if now is None:
        now = time.monotonic()
    with GARMIN_SCHEDULE_LOCK:
        last_attempt = GARMIN_LAST_ATTEMPT_MONO
    return last_attempt == 0.0 or now - last_attempt >= load_garmin_sync_minutes() * 60


def garmin_personal_loop():
     
     
    while True:
        delay = 15
        try:
            if garmin_personal_key():
                with STATE_LOCK:
                    occupied = JOB.get('status') == 'running'
                if not occupied and not GARMIN_SYNC_LOCK.locked():
                    history=garmin_history_state()
                    in_cooldown=('rate limit' in history['message'].lower() or 'HTTP 429' in history['message']) and time.time()<history['next_after']
                    if not in_cooldown:
                        if history['active'] and time.time()>=history['next_after']:
                            garmin_personal_history_job()
                        elif garmin_auto_sync_due():
                            garmin_personal_sync_job()
                elif garmin_auto_sync_due():
                    delay = 12   
        except Exception as exc:
            print('[LibreHeatmaps] Garmin sync loop: {}'.format(type(exc).__name__),flush=True)
            delay = 60
        time.sleep(delay)


def garmin_usb_import_job(device_id, roots=None):
    added = skipped = failed = no_gps = copied = 0
    try:
        device = next((device for device in garmin_usb_devices(roots) if device["id"] == device_id), None)
        if device is None:
            raise ValueError("Garmin not found. Reconnect it by USB and scan again")
        files = device["files"]
        archive = garmin_usb_archive_directory()
        set_job(total=len(files), message="Copying Garmin FIT recordings", copied=0)
        with db_connect() as con:
            for index, source in enumerate(files, 1):
                set_job(processed=index - 1, message=source.name[:110])
                try:
                    destination, was_copied, digest = garmin_usb_copy(source, archive)
                    if was_copied:
                        copied += 1
                    key = hashlib.sha256(("garmin-usb:" + digest).encode()).hexdigest()
                    with destination.open("rb") as stream:
                        result = insert_activity(con, destination.name, key, stream, {})
                    if result == "added":
                        added += 1
                    elif result == "no-gps":
                        no_gps += 1
                    else:
                        skipped += 1
                except (OSError, ValueError, EOFError, sqlite3.Error, gzip.BadGzipFile) as exc:
                    failed += 1
                    print("[LibreHeatmaps] Garmin USB import unavailable for {}: {}".format(source.name, exc), flush=True)
                set_job(processed=index, added=added, skipped=skipped, no_gps=no_gps, failed=failed, copied=copied)
        with db_connect() as con:
            con.execute("INSERT INTO import_history(imported_at,label,added,skipped,no_gps,failed,updated) VALUES(?,?,?,?,?,?,?)", (dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds"), "Garmin USB", added, skipped, no_gps, failed, 0))
            con.execute("DELETE FROM import_history WHERE id NOT IN (SELECT id FROM import_history ORDER BY id DESC LIMIT 30)")
        set_job(status="done", message="Garmin USB complete · {} new FIT files copied to {}".format(copied, archive))
        start_heat_warmup()
    except Exception as exc:
        set_job(status="error", message=str(exc)[:320])
    

EDITABLE_ACTIVITY_FIELDS = ('name','sport','day','bike','gear_id','recorded_distance_m','moving_seconds','elapsed_seconds','elevation_m','avg_speed','max_speed','avg_heart_rate','avg_power','avg_cadence','calories_kcal','avg_temp_c','max_temp_c','weather_temp_c','wind_speed_mps','wind_gust_mps')


def safe_activity_id(params):
    value=params.get('id',[''])[0]
    if not isinstance(value,str) or not value.isascii() or not value.isdecimal() or len(value)>12 or int(value)<=0:
        raise ValueError('Invalid activity ID')
    return int(value)


def edit_activity_details(activity_id, action=None, changes=None):
    if type(activity_id) is not int or not 0 < activity_id < 10**12:
        raise ValueError('Select an activity')
    if action:
        with STATE_LOCK:
            if JOB['status']=='running':raise ValueError('Finish importing before editing this activity')
    with db_connect() as con:
        row=con.execute('SELECT '+','.join(EDITABLE_ACTIVITY_FIELDS)+' FROM activities WHERE id=?',(activity_id,)).fetchone()
        if row is None:raise ValueError('Activity not found')
        current=dict(zip(EDITABLE_ACTIVITY_FIELDS,row))
        old=con.execute('SELECT originals,values_json,updated_at FROM activity_overrides WHERE activity_id=?',(activity_id,)).fetchone()
        if action is None:
            known_gear=con.execute("SELECT TRIM(bike),MAX(COALESCE(gear_id,'')),COUNT(*) FROM activities WHERE bike IS NOT NULL AND TRIM(bike)!='' GROUP BY LOWER(TRIM(bike)) ORDER BY COUNT(*) DESC,TRIM(bike) COLLATE NOCASE LIMIT 100").fetchall()
            return {'id':activity_id,'values':current,'edited':bool(old),'original':{**current,**json.loads(old[0])} if old else current,'updated_at':old[2] if old else None,'gear_options':[{'name':name,'gear_id':gid,'count':count} for name,gid,count in known_gear]}
        if action=='restore':
            if old:
                originals={**current,**json.loads(old[0])}
                con.execute('UPDATE activities SET '+','.join(k+'=?' for k in EDITABLE_ACTIVITY_FIELDS)+' WHERE id=?',tuple(originals[k] for k in EDITABLE_ACTIVITY_FIELDS)+(activity_id,))
                con.execute('DELETE FROM activity_overrides WHERE activity_id=?',(activity_id,))
                con.execute('INSERT INTO activity_edit_log(activity_id,changed_at,previous,updated) VALUES(?,?,?,?)',(activity_id,dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds'),json.dumps(current),json.dumps(originals)))
        elif action=='save':
            if not isinstance(changes,dict) or set(changes)!=set(EDITABLE_ACTIVITY_FIELDS):raise ValueError('Invalid edit fields')
            validated={}
            for key in EDITABLE_ACTIVITY_FIELDS:
                value=changes[key]
                if key in ('name','sport','bike','gear_id'):
                    if value is None and key in ('bike','gear_id'):value=''
                    if not isinstance(value,str):raise ValueError('Expected text for '+key)
                    value=value.strip()
                    if key in ('name','sport') and not value:raise ValueError('Name and activity type are required')
                    if len(value)>{'name':300,'sport':80,'bike':160,'gear_id':120}[key] or any(ord(c)<32 for c in value):raise ValueError('Invalid '+key)
                elif key=='day':
                    if value is not None:
                        if not isinstance(value,str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}',value):raise ValueError('Invalid date')
                        try: d=dt.date.fromisoformat(value)
                        except ValueError:raise ValueError('Invalid calendar date')
                        if not 1980<=d.year<=2200:raise ValueError('Activity date must be between 1980 and 2200')
                else:
                    limits={'recorded_distance_m':2e7,'moving_seconds':1e8,'elapsed_seconds':1e8,'elevation_m':1e6,'avg_speed':70,'max_speed':100,'avg_heart_rate':270,'avg_power':3000,'avg_cadence':300,'calories_kcal':1e6,'avg_temp_c':100,'max_temp_c':100,'weather_temp_c':100,'wind_speed_mps':80,'wind_gust_mps':100}
                    if value in ('',None):value=None
                    elif type(value) not in (int,float) or not math.isfinite(value) or not (-80<=value<limits[key] if key.endswith('temp_c') else 0<=value<limits[key]):
                        raise ValueError('Invalid '+key+' measurement')
                validated[key]=value
            original={**current,**json.loads(old[0])} if old else current
            now=dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')
            con.execute('UPDATE activities SET '+','.join(k+'=?' for k in EDITABLE_ACTIVITY_FIELDS)+' WHERE id=?',tuple(validated[k] for k in EDITABLE_ACTIVITY_FIELDS)+(activity_id,))
            if validated==original:
                con.execute('DELETE FROM activity_overrides WHERE activity_id=?',(activity_id,))
            else:
                con.execute('INSERT INTO activity_overrides(activity_id,originals,values_json,updated_at) VALUES(?,?,?,?) ON CONFLICT(activity_id) DO UPDATE SET values_json=excluded.values_json,updated_at=excluded.updated_at',(activity_id,json.dumps(original),json.dumps(validated),now))
            con.execute('INSERT INTO activity_edit_log(activity_id,changed_at,previous,updated) VALUES(?,?,?,?)',(activity_id,now,json.dumps(current),json.dumps(validated)))
        else:raise ValueError('Unknown edit action')
    clear_render_caches(include_tracks=False)
    start_heat_warmup()
    return edit_activity_details(activity_id)


def reapply_activity_override(con, activity_id):
    record=con.execute('SELECT originals,values_json FROM activity_overrides WHERE activity_id=?',(activity_id,)).fetchone()
    if record:
        originals=json.loads(record[0]);values=json.loads(record[1])
         
         
        updated=[k for k in EDITABLE_ACTIVITY_FIELDS if k in values and values[k]!=originals.get(k)]
        if updated:
            con.execute('UPDATE activities SET '+','.join(k+'=?' for k in updated)+' WHERE id=?',tuple(values[k] for k in updated)+(activity_id,))



def estimate_activity_speeds(activity_id):
    if type(activity_id) is not int or not 0 < activity_id < 10**12:
        raise ValueError('Invalid activity')
    with db_connect() as con:
        row=con.execute('SELECT id,sport,COALESCE(recorded_distance_m,distance_m),moving_seconds,avg_speed,max_speed,west,south,east,north,coordinates FROM activities WHERE id=?',(activity_id,)).fetchone()
        if row is None:raise ValueError('Activity not found')
        record=con.execute('SELECT payload FROM activity_telemetry WHERE activity_id=?',(activity_id,)).fetchone()
        other=con.execute('SELECT id,COALESCE(recorded_distance_m,distance_m),avg_speed,west,south,east,north,coordinates,sport FROM activities WHERE id!=? AND distance_m BETWEEN ? AND ? AND west<? AND east>? AND south<? AND north>? ORDER BY id DESC LIMIT 160',
            (activity_id,max(1,(row[2] or 0)*.75),(row[2] or 0)*1.25+1,row[8]+.05,row[6]-.05,row[9]+.05,row[7]-.05)).fetchall()
    samples=[]
    if record:
        try:samples=json.loads(zlib.decompress(record[0]))
        except (TypeError,ValueError,zlib.error):samples=[]
    validated=[];rejected=0
    for a,b in zip(samples,samples[1:]):
        try:
            ta,la,oa=a[:3];tb,lb,ob=b[:3]
            if not all(type(v) in (int,float) and math.isfinite(v) for v in (ta,la,oa,tb,lb,ob)):continue
            dt_s=tb-ta
            if not 0.5<=dt_s<=45 or abs(la)>85 or abs(lb)>85:continue
            distance=haversine((la,oa),(lb,ob))
            if not math.isfinite(distance):continue
            if len(a)>8 and len(b)>8 and type(a[8]) in (int,float) and type(b[8]) in (int,float):
                rise=abs(a[8]-b[8])
                if rise>max(18,distance*.50):rejected+=1;continue
                distance=math.hypot(distance,rise)
            gps_speed=distance/dt_s
            if gps_speed>32 or gps_speed<0:rejected+=1;continue
            sensor=b[3] if len(b)>3 else None
            if type(sensor) in (int,float) and math.isfinite(sensor) and 0<=sensor<=32 and abs(sensor-gps_speed)<max(5,0.8*gps_speed):
                validated.append((gps_speed+sensor)/2)
            else:validated.append(gps_speed)
        except (TypeError,ValueError,IndexError):continue
    moving=sorted(v for v in validated if v>=1.0)
    sustained=None
    if len(moving)>=6:
        groups=sorted(sorted(validated[i:i+3])[1] for i in range(len(validated)-2) if sum(v>=1 for v in validated[i:i+3])>=2)
        if groups:
            sustained=round(groups[max(0,int(.98*(len(groups)-1)))],4)
    same_sport=lambda sp:('ride' in (sp or '').casefold() or 'cycl' in (sp or '').casefold() or 'bik' in (sp or '').casefold())==('ride' in (row[1] or '').casefold() or 'cycl' in (row[1] or '').casefold() or 'bik' in (row[1] or '').casefold())
    first,last=None,None
    for pt in iter_coordinates(row[10]):
        if pt is None:continue
        if first is None:first=pt
        last=pt
    peers=[]
    if first is not None and last is not None:
        for item in other:
            if not same_sport(item[8]) or item[2] is None or not (0<item[2]<30):continue
            pfirst,plast=None,None
            for pt in iter_coordinates(item[7]):
                if pt is None:continue
                if pfirst is None:pfirst=pt
                plast=pt
            if pfirst and plast and min(haversine(first,pfirst)+haversine(last,plast),haversine(first,plast)+haversine(last,pfirst))<=850:
                peers.append(item[2])
    peers.sort()
    median=(peers[(len(peers)-1)//2]+peers[len(peers)//2])/2 if peers else None
    return {'activity_id':activity_id,'valid_intervals':len(validated),'rejected_intervals':rejected,
            'sustained_max_mps':sustained,'comparable_count':len(peers),'comparable_median_avg_mps':median,
            'distance_time_average_mps':row[2]/row[3] if row[2] and row[3] and row[3]>0 else None,
            'recorded_avg_mps':row[4],'recorded_max_mps':row[5],
            'advisory':'Experimental estimate only; source speed, elevation and GPS telemetry remain unchanged until you explicitly save an edit.'}


def geometry_data(blob):
    return list(iter_coordinates(blob))


def geometry_pack(points):
    buf=bytearray()
    for point in points:
        buf.extend(struct.pack('<ii',2147483647,2147483647) if point is None else struct.pack('<ii',round(point[0]*1e6),round(point[1]*1e6)))
    return zlib.compress(bytes(buf),6)


def geometry_measure(points):
    previous=None; distance=0.0; box=[90.0,180.0,-90.0,-180.0]; count=0
    for p in points:
        if p is None:previous=None;continue
        count+=1
        box[0]=min(box[0],p[0]);box[1]=min(box[1],p[1]);box[2]=max(box[2],p[0]);box[3]=max(box[3],p[1])
        if previous is not None:distance+=haversine(previous,p)
        previous=p
    if count<2:raise ValueError('Not enough GPS positions for repair')
    return count,box,distance


def route_spike_candidates(points,samples):
    spikes=[]
    if len(samples)>8000 or len(points)>MAX_POINTS:raise ValueError('Route exceeds anomaly-review safety limit')
    for k in range(1,len(samples)-1):
        a,b,c=samples[k-1:k+2]
        if any(len(r)<3 or any(type(v) not in (float,int) or not math.isfinite(v) for v in r[:3]) for r in (a,b,c)):continue
        d1=b[0]-a[0];d2=c[0]-b[0]
        if not (0<d1<=25 and 0<d2<=25):continue
        left=haversine(a[1:3],b[1:3]);right=haversine(b[1:3],c[1:3]);short=haversine(a[1:3],c[1:3])
        if not (min(left,right)>=140 and left/d1>=35 and right/d2>=35 and short<=65 and left+right-short>330):continue
        if abs(a[1])>85 or abs(b[1])>85 or abs(c[1])>85:continue
        before=(a[1],a[2]);after=(c[1],c[2]);bad=(b[1],b[2])
        center=min(range(len(points)),key=lambda i:haversine(points[i],bad) if points[i] is not None else 1e10)
        if points[center] is None or haversine(points[center],bad)>65:continue
        lower=max(0,center-145);upper=min(len(points),center+146)
        start_candidates=[i for i in range(lower,center) if points[i] is not None and haversine(points[i],before)<=52]
        end_candidates=[i for i in range(center+1,upper) if points[i] is not None and haversine(points[i],after)<=52]
        if not start_candidates or not end_candidates:continue
        start=max(start_candidates);end=min(end_candidates)
        if end-start<3 or end-start>260 or any(x is None for x in points[start:end+1]):continue
        removed=sum(haversine(points[i],points[i+1]) for i in range(start,end))
        new_distance=haversine(points[start],points[end])
        if removed-new_distance<300:continue
        if spikes and start<=spikes[-1]['end_index']:continue
        spikes.append({'sample_index':k,'start_index':start,'end_index':end,
            'before':[round(v,6) for v in before],'outlier':[round(v,6) for v in bad],
            'after':[round(v,6) for v in after],'detour_m':round(removed-new_distance),
            'time_seconds':round(d1+d2,1),'jump_speed_kmh':round(max(left/d1,right/d2)*3.6)})
        if len(spikes)>=16:break
    return spikes


def route_after_proposals(points, proposals):
    result=list(points)
    for item in reversed(proposals):
        result[item['start_index']+1:item['end_index']]=[]
    return result


def route_review(activity_id, action=None, selection=None):
    if type(activity_id) is not int or not 0<activity_id<10**12:raise ValueError('Invalid activity ID')
    if action is not None and action not in ('apply','restore'):raise ValueError('Unknown route action')
    if action:
        with STATE_LOCK:
            if JOB['status']=='running':raise ValueError('Finish importing before editing the stored route')
    with db_connect() as con:
        row=con.execute('SELECT coordinates,point_count,distance_m,west,south,east,north FROM activities WHERE id=?',(activity_id,)).fetchone()
        if row is None:raise ValueError('Activity not found')
        saved=con.execute('SELECT original_coordinates,original_point_count,original_distance_m,original_bbox,original_telemetry,original_telemetry_count,edits,applied_at FROM activity_route_repairs WHERE activity_id=?',(activity_id,)).fetchone()
        if action=='restore':
            if saved:
                bb=json.loads(saved[3])
                con.execute('UPDATE activities SET coordinates=?,point_count=?,distance_m=?,west=?,south=?,east=?,north=? WHERE id=?',(saved[0],saved[1],saved[2],bb[0],bb[1],bb[2],bb[3],activity_id))
                if saved[4] is not None:
                    con.execute('UPDATE activity_telemetry SET payload=?,sample_count=? WHERE activity_id=?',(saved[4],saved[5],activity_id))
                con.execute('DELETE FROM activity_route_repairs WHERE activity_id=?',(activity_id,))
        elif action=='apply' and saved:raise ValueError('Restore the original route before reviewing another repair')
        elif action=='apply':
            telemetry=con.execute('SELECT payload,sample_count FROM activity_telemetry WHERE activity_id=?',(activity_id,)).fetchone()
            if not telemetry:raise ValueError('This route has no timestamped GPS evidence for a safe repair')
            samples=json.loads(zlib.decompress(telemetry[0]))
            points=geometry_data(row[0]);proposals=route_spike_candidates(points,samples)
            if not isinstance(selection,list) or not selection or len(selection)>16 or any(type(i) is not int for i in selection) or len(set(selection))!=len(selection):raise ValueError('Select the candidate spikes to repair')
            chosen=[v for v in proposals if v['sample_index'] in selection]
            if len(chosen)!=len(selection):raise ValueError('Route changed; refresh the review before applying')
            fixed=route_after_proposals(points,chosen)
            count,bbox,distance=geometry_measure(fixed)
            if distance>=row[2]:raise ValueError('No supported GPS spike reduction')
            for proposal in chosen:
                i=proposal['sample_index'];samples[i][1]=(samples[i-1][1]+samples[i+1][1])/2;samples[i][2]=(samples[i-1][2]+samples[i+1][2])/2
            payload=zlib.compress(json.dumps(samples,allow_nan=False,separators=(',',':')).encode(),6)
            con.execute('INSERT INTO activity_route_repairs(activity_id,original_coordinates,original_point_count,original_distance_m,original_bbox,original_telemetry,original_telemetry_count,edits,applied_at) VALUES(?,?,?,?,?,?,?,?,?)',(
                activity_id,row[0],row[1],row[2],json.dumps([row[3],row[4],row[5],row[6]]),telemetry[0],telemetry[1],json.dumps(chosen),dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')))
            con.execute('UPDATE activities SET coordinates=?,point_count=?,distance_m=?,west=?,south=?,east=?,north=? WHERE id=?',(geometry_pack(fixed),count,round(distance),bbox[1],bbox[0],bbox[3],bbox[2],activity_id))
            con.execute('UPDATE activity_telemetry SET payload=? WHERE activity_id=?',(payload,activity_id))
    if action:
        clear_render_caches(include_tracks=True)
        start_heat_warmup()
        return route_review(activity_id)
    if saved:
        return {'activity_id':activity_id,'applied':True,'applied_at':saved[7],
                'changes':json.loads(saved[6]),'original_distance_m':saved[2],'current_distance_m':row[2],
                'message':'Original GPS track and sensor coordinates are preserved in the local database and can be restored.'}
    telemetry=con_telemetry=None
    with db_connect() as con:
        telemetry=con.execute('SELECT payload FROM activity_telemetry WHERE activity_id=?',(activity_id,)).fetchone()
    points=geometry_data(row[0]); proposals=[]
    if telemetry:
        samples=json.loads(zlib.decompress(telemetry[0]));proposals=route_spike_candidates(points,samples)
    repaired=route_after_proposals(points,proposals) if proposals else points
    def preview(values):
        step=max(1,math.ceil(len(values)/1600));out=[]
        for i,p in enumerate(values):
            if p is None:out.append(None)
            elif i%step==0:out.append([round(p[0],6),round(p[1],6)])
        if values and values[-1] is not None and (not out or out[-1]!=list(values[-1])):out.append([round(x,6) for x in values[-1]])
        return out
    return {'activity_id':activity_id,'applied':False,'proposals':proposals,
        'original_distance_m':row[2], 'proposed_distance_m':round(geometry_measure(repaired)[2]),
        'original_points':preview(points),'proposed_points':preview(repaired),
        'message':'Only isolated, implausibly fast GPS excursions supported by timestamped sensor positions are proposed. Legitimate out-and-back riding and GPS gaps are not automatically changed.'}


def statistics():
    with db_connect() as con:
        count, points, west, south, east, north = con.execute("SELECT COUNT(*), COALESCE(SUM(point_count),0), MIN(west), MIN(south), MAX(east), MAX(north) FROM activities").fetchone()
        types = con.execute("SELECT sport,COUNT(*) FROM activities GROUP BY sport ORDER BY COUNT(*) DESC").fetchall()
        bikes = con.execute("SELECT DISTINCT bike FROM activities WHERE bike IS NOT NULL AND bike<>'' ORDER BY bike COLLATE NOCASE").fetchall()
        first, last = con.execute("SELECT MIN(day),MAX(day) FROM activities WHERE day IS NOT NULL").fetchone()
    focus = None
    if count:
        with db_connect() as con:
            boxes = con.execute("SELECT west,south,east,north FROM activities WHERE west > -180 AND east < 180 AND south > -85 AND north < 85 AND east>=west AND north>=south").fetchall()
        focus = focus_activity_bounds(boxes)
    with db_connect() as con:
        first_launch = con.execute("SELECT value FROM app_settings WHERE key=?", ("welcome_dismissed",)).fetchone() is None
    return {"count": count, "mapped_gps_count":count, "points": points, "bounds": [west, south, east, north] if count else None, "focus_bounds":focus, "types": types, "bikes": [b[0] for b in bikes], "first": first, "last": last, "first_launch":first_launch}



