def statistics_preferences():
    with db_connect() as con:
        rows=dict(con.execute("SELECT key,value FROM app_settings WHERE key IN ('filter_speed_anomalies','filter_speed_smart','advanced_data','speed_threshold_mph','garmin_sync_minutes','garmin_recent_count','strava_sync_minutes','strava_recent_count')"))
    return {'filter_speed_anomalies':rows.get('filter_speed_anomalies')=='1',
            'filter_speed_smart':rows.get('filter_speed_smart')=='1',
            'advanced_data':rows.get('advanced_data')=='1',
            'speed_threshold_mph':speed_threshold_mph(rows),
            'garmin_sync_minutes':garmin_sync_minutes(rows),
            'garmin_recent_count':garmin_recent_count(rows),
            'strava_sync_minutes':strava_sync_interval(), 'strava_recent_count':strava_recent_count()}


def store_all_settings(payload):
    allowed={'appearance','filter_speed_anomalies','filter_speed_smart','advanced_data','display_units','watch_folder','speed_threshold_mph','garmin_sync_minutes','garmin_recent_count','strava_sync_minutes','strava_recent_count','activity_focus'}
    mandatory=allowed-{'garmin_recent_count','strava_recent_count','activity_focus'}
    if not isinstance(payload,dict) or not mandatory <= set(payload) or set(payload)-allowed:
        raise ValueError('Invalid settings fields')
    if type(payload['filter_speed_anomalies']) is not bool or type(payload['filter_speed_smart']) is not bool or type(payload['advanced_data']) is not bool:
        raise ValueError('Invalid statistics toggles')
    activity_focus=payload.get('activity_focus',load_activity_focus())
    if activity_focus not in ('cycling','foot','all') or type(activity_focus) is not str:raise ValueError('Invalid activity focus')
    appearance=normalize_appearance(payload['appearance'])
    if payload['display_units'] not in ('mi','km') or type(payload['display_units']) is not str:
        raise ValueError('Invalid display units')
    threshold = payload['speed_threshold_mph']
    if type(threshold) not in (int,float) or not math.isfinite(threshold) or not 5 <= threshold <= 200:
        raise ValueError('Custom speed threshold must be from 5 to 200 mph')
    threshold = round(float(threshold), 5)
    interval = payload['garmin_sync_minutes']
    if type(interval) is not int or not 15 <= interval <= 1440:
        raise ValueError('Garmin automatic sync interval must be from 15 to 1440 minutes')
    strava_interval=payload['strava_sync_minutes']
    if type(strava_interval) is not int or not 15 <= strava_interval <= 1440:
        raise ValueError('Strava automatic sync interval must be from 15 to 1440 minutes')
    garmin_count=payload.get('garmin_recent_count',load_garmin_recent_count())
    if type(garmin_count) is not int or not 1 <= garmin_count <= 100:
        raise ValueError("Garmin recent activity count must be from 1 to 100")
    recent_count=payload.get('strava_recent_count',strava_recent_count())
    if type(recent_count) is not int or not 1 <= recent_count <= 50:
        raise ValueError('Strava recent activity count must be from 1 to 50')
    watch_folder=normalize_watch_folder(payload['watch_folder'])
    with db_connect() as con:
        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('appearance',?)", (json.dumps(appearance,separators=(',',':')),))
        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('activity_focus',?)",(activity_focus,))
        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('display_units',?)",(payload['display_units'],))
        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('watch_folder',?)",(watch_folder,))
        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('speed_threshold_mph',?)",(str(threshold),))
        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('garmin_sync_minutes',?)",(str(interval),))
        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('garmin_recent_count',?)",(str(garmin_count),))
        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('strava_sync_minutes',?)",(str(strava_interval),))
        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('strava_recent_count',?)",(str(recent_count),))
        for name in ('filter_speed_anomalies','filter_speed_smart','advanced_data'):
            con.execute('INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)',(name,'1' if payload[name] else '0'))
    return {'appearance':appearance,**{k:payload[k] for k in ('filter_speed_anomalies','filter_speed_smart','advanced_data')},'speed_threshold_mph':threshold,'garmin_sync_minutes':interval,'garmin_recent_count':garmin_count,'strava_sync_minutes':strava_interval,'strava_recent_count':recent_count,'display_units':payload['display_units'],'watch_folder':watch_folder,'activity_focus':activity_focus}


 
 
 
 
STRAVA_PROFILE_NAME = 'Strava-Browser-Session'
STRAVA_RECONNECT_KEY = 'strava_browser_reconnect_required'


class StravaReauthenticationRequired(ValueError):
    pass

STRAVA_SYNC_LOCK = threading.Lock()
STRAVA_STATUS_LOCK = threading.RLock()
STRAVA_SCHEDULE_LOCK = threading.Lock()
STRAVA_BROWSER_LOCK = threading.Lock()
STRAVA_BROWSER_PROCESS = None
STRAVA_LAST_ATTEMPT_MONO = 0.0
STRAVA_STOP = threading.Event()
STRAVA_STATUS = {'running': False, 'connecting': False, 'message': 'Not connected. Optional unofficial browser-based GPX syncing requires your Strava account and permission to use its website.', 'last_sync': None, 'checked': 0, 'added': 0, 'skipped': 0, 'failed': 0}
STRAVA_TRAINING_URL = 'https://www.strava.com/athlete/training'


def strava_profile_path():
    return DB_PATH.parent / STRAVA_PROFILE_NAME


def strava_connection_state():
    with db_connect() as con:
        saved = dict(con.execute("SELECT key,value FROM app_settings WHERE key IN ('strava_browser_connected',?)", (STRAVA_RECONNECT_KEY,)))
    profile = strava_profile_path()
    has_session = profile.is_dir() and not profile.is_symlink()
    authorized = saved.get('strava_browser_connected') == '1' and has_session
    reconnect_required = authorized and saved.get(STRAVA_RECONNECT_KEY) == '1'
    return {'connected': authorized and not reconnect_required,
            'session_saved': authorized, 'reconnect_required': reconnect_required,
            'has_session': profile.is_dir() or profile.is_symlink()}


def strava_connected():
    return strava_connection_state()['connected']


def strava_require_reconnect():
     
     
    if STRAVA_STOP.is_set():return
    with db_connect() as con:
        still_connected=con.execute("SELECT value FROM app_settings WHERE key='strava_browser_connected'").fetchone()
        if not still_connected or still_connected[0]!='1':return
        con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?, '1')", (STRAVA_RECONNECT_KEY,))
    with STRAVA_STATUS_LOCK:
        STRAVA_STATUS.update(message='Strava sign-in expired. Automatic GPX checks are paused. Select Reconnect Strava to sign in again; imported rides are safe.')


def strava_sync_interval():
    with db_connect() as con:
        record = con.execute("SELECT value FROM app_settings WHERE key='strava_sync_minutes'").fetchone()
    try:
        minutes = int(record[0]) if record else 60
        return minutes if 15 <= minutes <= 1440 else 60
    except (TypeError, ValueError):
        return 60


def strava_recent_count():
    with db_connect() as con:
        record = con.execute("SELECT value FROM app_settings WHERE key='strava_recent_count'").fetchone()
    try:
        count = int(record[0]) if record else 25
        return count if 1 <= count <= 50 else 25
    except (TypeError, ValueError):
        return 25


def strava_status():
    with STRAVA_STATUS_LOCK:
        status = dict(STRAVA_STATUS)
    state = strava_connection_state()
    status.update(state)
    if state['reconnect_required'] and not status['connecting']:
        status['message'] = 'Strava sign-in expired. Automatic GPX checks are paused. Select Reconnect Strava to sign in again; imported rides are safe.'
    elif not state['session_saved'] and not status['running'] and status['message'].startswith('Strava sign-in expired.'):
        status['message'] = 'Strava disconnected. A fresh connection needs a new sign-in in the dedicated browser window.'
    elif state['connected'] and status['message'].startswith('Not connected.'):
        status['message'] = 'Strava browser session saved on this computer. Login will be checked on the next sync; reconnect only if prompted.'
    status['sync_interval_minutes'] = strava_sync_interval()
    status['recent_count'] = strava_recent_count()
    status['method'] = 'Unofficial Strava website GPX export (no developer API)'
    return status


def strava_browser_executable():
     
    guesses = []
    if os.name == 'nt':
        for base in (os.environ.get('PROGRAMFILES'), os.environ.get('PROGRAMFILES(X86)'), os.environ.get('LOCALAPPDATA')):
            if base:
                guesses += [Path(base)/'Microsoft/Edge/Application/msedge.exe', Path(base)/'Google/Chrome/Application/chrome.exe']
    elif sys.platform == 'darwin':
        guesses += [Path('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'), Path('/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge')]
    for exe in guesses:
        if exe.is_file():
            return str(exe)
    for name in ('msedge', 'microsoft-edge', 'google-chrome', 'chromium', 'chromium-browser'):
        found = shutil.which(name)
        if found:
            return found
    raise ValueError('Install Microsoft Edge or Chrome on your computer to connect Strava in a dedicated browser window')


def strava_start_browser(*, visible):
    global STRAVA_BROWSER_PROCESS
    profile = strava_profile_path()
    if profile.exists() and (profile.is_symlink() or not profile.is_dir()):
        raise ValueError('Strava session folder is not an ordinary directory')
    profile.mkdir(parents=True, exist_ok=True)
    if os.name != 'nt':
        os.chmod(profile, 0o700)
    marker = profile/'DevToolsActivePort'
    marker.unlink(missing_ok=True)
    command = [strava_browser_executable(), '--user-data-dir='+str(profile), '--remote-debugging-port=0', '--no-first-run', '--no-default-browser-check', '--disable-background-mode', '--disable-extensions']
    startup = None
    if not visible:
        if os.name == 'nt':
             
             
            command += ['--start-minimized', '--window-position=-32000,-32000']
            startup = subprocess.STARTUPINFO()
            startup.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            startup.wShowWindow = 0   
        else:
            command += ['--headless=new', '--disable-gpu']
    command.append(STRAVA_TRAINING_URL)
    kwargs = {'stdin': subprocess.DEVNULL, 'stdout': subprocess.DEVNULL, 'stderr': subprocess.DEVNULL}
    if startup is not None:
        kwargs['startupinfo'] = startup
    proc = subprocess.Popen(command, **kwargs)
    with STRAVA_BROWSER_LOCK:
        STRAVA_BROWSER_PROCESS = proc
    if os.name == 'nt' and not visible:
        threading.Thread(target=strava_hide_sync_browser, args=(proc,), daemon=True,
                         name='LibreHeatmaps-Strava-Window-Hider').start()
    try:
        port = None
        deadline = time.monotonic()+22
        while time.monotonic() < deadline:
            if STRAVA_STOP.is_set():
                raise ValueError('Strava connection was disconnected')
            if marker.is_file():
                try:
                    candidate = marker.read_text(encoding='ascii').splitlines()[0].strip()
                    if candidate.isdecimal() and 1 <= int(candidate) <= 65535:
                        port = int(candidate)
                        break
                except (OSError, UnicodeError, ValueError):
                    pass
            if proc.poll() is not None:
                break
            time.sleep(.2)
        if port is None:
            raise ValueError('Could not start the dedicated Strava browser. Close other LibreHeatmaps Strava windows and try again')
        return proc, port
    except Exception:
         
        strava_end_browser(proc)
        raise



def strava_hide_sync_browser(proc):
     
     
     
    if os.name != 'nt':
        return
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        callback_type = ctypes.WINFUNCTYPE(ctypes.c_int, wintypes.HWND, wintypes.LPARAM)
        user32.GetWindowThreadProcessId.argtypes = (wintypes.HWND, ctypes.POINTER(wintypes.DWORD))
        user32.GetWindowThreadProcessId.restype = wintypes.DWORD
        user32.IsWindowVisible.argtypes = (wintypes.HWND,)
        user32.IsWindowVisible.restype = ctypes.c_int
        user32.ShowWindowAsync.argtypes = (wintypes.HWND, ctypes.c_int)
        user32.ShowWindowAsync.restype = ctypes.c_int
        def hide_window(hwnd, _):
            owner = wintypes.DWORD(0)
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(owner))
            if owner.value == proc.pid and user32.IsWindowVisible(hwnd):
                user32.ShowWindowAsync(hwnd, 0)   
            return 1
        callback = callback_type(hide_window)
        while proc.poll() is None:
            user32.EnumWindows(callback, 0)
            time.sleep(.12)
    except (AttributeError, OSError, TypeError, ValueError):
         
        return

def strava_end_browser(proc, *, graceful=False):
    global STRAVA_BROWSER_PROCESS
    if proc is not None and proc.poll() is None:
         
         
         
        if graceful:
            try:
                proc.wait(timeout=8)
            except subprocess.TimeoutExpired:
                pass
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=4)
            except subprocess.TimeoutExpired:
                proc.kill()
    with STRAVA_BROWSER_LOCK:
        if STRAVA_BROWSER_PROCESS is proc:
            STRAVA_BROWSER_PROCESS = None


def strava_browser_target(port):
     
     
    expected = urlparse(STRAVA_TRAINING_URL).hostname or ''
    expected_hosts={expected,'strava.com','www.strava.com'} if expected else set()
    deadline=time.monotonic()+12
    fallback=None
    while time.monotonic()<deadline:
        try:
            raw=urlopen(Request('http://127.0.0.1:{}/json'.format(port),headers={'Accept':'application/json'}),timeout=3).read(512*1024)
            targets=json.loads(raw)
            strava_target=None
            for item in targets:
                url=item.get('webSocketDebuggerUrl','')
                if item.get('type')!='page' or not url.startswith('ws://127.0.0.1:{}/'.format(port)):
                    continue
                if not fallback:fallback=url
                actual=item.get('url','')
                parsed=urlparse(actual)
                if expected and parsed.hostname in expected_hosts:
                     
                     
                    if parsed.path.rstrip('/')==urlparse(STRAVA_TRAINING_URL).path.rstrip('/'):
                        return url
                    if not strava_target:strava_target=url
                elif not expected and actual.startswith(STRAVA_TRAINING_URL):
                    return url
            if strava_target:return strava_target
        except (OSError,ValueError,URLError,json.JSONDecodeError):
            pass
        time.sleep(.25)
    if fallback:return fallback
    raise ValueError('The Strava browser did not open an activity tab')


class StravaDevTools:
     
     
    def __init__(self, ws_url):
        parsed = urlparse(ws_url)
        if parsed.scheme != 'ws' or parsed.hostname != '127.0.0.1' or not parsed.port:
            raise ValueError('Unexpected browser debugging endpoint')
        self.socket = socket.create_connection(('127.0.0.1', parsed.port), timeout=10)
        self.socket.settimeout(18)
        self.next_id = 0
        key = base64.b64encode(os.urandom(16)).decode('ascii')
        request = 'GET {} HTTP/1.1\r\nHost: 127.0.0.1:{}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {}\r\nSec-WebSocket-Version: 13\r\n\r\n'.format(parsed.path, parsed.port, key)
        self.socket.sendall(request.encode('ascii'))
        response = b''
        while b'\r\n\r\n' not in response and len(response) < 8192:
            response += self.socket.recv(8192)
        headers, sep, tail = response.partition(b'\r\n\r\n')
        expected = base64.b64encode(hashlib.sha1((key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').encode()).digest())
        if not sep or not headers.startswith(b'HTTP/1.1 101 ') or expected not in headers:
            self.close()
            raise ValueError('The browser rejected its local control connection')
        self.pending = tail

    def close(self):
        try:self.socket.close()
        except OSError:pass

    def _send(self, payload, opcode=1):
        mask = os.urandom(4)
        length = len(payload)
        header = bytearray([0x80|opcode])
        if length < 126:header.append(0x80|length)
        elif length < 65536:header.extend([0x80|126]);header.extend(struct.pack('!H',length))
        else:header.extend([0x80|127]);header.extend(struct.pack('!Q',length))
        header.extend(mask)
        self.socket.sendall(header+bytes(b ^ mask[i%4] for i,b in enumerate(payload)))

    def _receive_bytes(self, count):
        while len(self.pending) < count:
            fragment = self.socket.recv(min(262144,max(4096,count-len(self.pending))))
            if not fragment:raise ConnectionError('Strava browser closed its connection')
            self.pending += fragment
        result, self.pending = self.pending[:count], self.pending[count:]
        return result

    def _receive(self):
        combined=bytearray()
        while True:
            head=self._receive_bytes(2)
            opcode=head[0]&15
            length=head[1]&127
            if length == 126:length=struct.unpack('!H',self._receive_bytes(2))[0]
            elif length == 127:length=struct.unpack('!Q',self._receive_bytes(8))[0]
            if length > 16*1024*1024:raise ValueError('Oversized browser response')
            mask=self._receive_bytes(4) if head[1]&128 else None
            payload=self._receive_bytes(length)
            if mask:payload=bytes(b^mask[i%4] for i,b in enumerate(payload))
            if opcode == 8:raise ConnectionError('Strava browser was closed')
            if opcode == 9:self._send(payload,10);continue
            combined.extend(payload)
            if head[0]&0x80:
                if opcode in (1,0):return json.loads(combined.decode('utf-8'))
                combined.clear()

    def call(self, method, params=None):
        self.next_id += 1
        ident = self.next_id
        self._send(json.dumps({'id':ident,'method':method,'params':params or {}},separators=(',',':')).encode('utf-8'))
        deadline=time.monotonic()+18
        while time.monotonic()<deadline:
            result=self._receive()
            if result.get('id') == ident:
                if 'error' in result:
                    raise ValueError('Browser command failed: '+str(result['error'].get('message','unknown'))[:120])
                return result.get('result',{})
        raise TimeoutError('Browser control request timed out')

    def evaluate(self, expression):
        result=self.call('Runtime.evaluate',{'expression':expression,'returnByValue':True,'awaitPromise':False})
        if result.get('exceptionDetails'):
            raise ValueError('Could not read the Strava activities page')
        return result.get('result',{}).get('value')


def strava_signin_page(state):
    href = state.get('href', '')
    try:
        parsed = urlparse(href)
        path = parsed.path.lower().rstrip('/')
    except (TypeError, ValueError):
        path = ''
    return bool(state.get('password') or path in ('/login', '/session/new', '/signin', '/sign-in') or path.startswith('/login/'))



 
 
 
 
STRAVA_PAGE_SCAN_JS = r'''(function(advance) {
  const table = [...document.querySelectorAll('table')].find(t =>
    t.querySelector('a[href*="/activities/"]'));
  const source = table || document;
  const ids = [...new Set([...source.querySelectorAll('a[href*="/activities/"]')]
    .map(a => (a.getAttribute('href') || '').match(/\/activities\/(\d+)/))
    .filter(Boolean).map(m => m[1]))];
  const pager = [...document.querySelectorAll('nav, .pagination, [class*="pagination"], [class*="paginator"], [data-testid*="pagination"]')]
    .filter(el => /paginat|pager/i.test(String(el.getAttribute('aria-label') || '') + ' ' + String(el.className || '') + ' ' + String(el.getAttribute('data-testid') || '')));
  const nextCandidates = [];
  for (const root of pager) nextCandidates.push(...root.querySelectorAll('a, button, [role="button"]'));
  nextCandidates.push(...document.querySelectorAll('a[rel="next"]'));
  const next = nextCandidates.find(el => {
    const description = [el.getAttribute('aria-label'), el.getAttribute('title'),
      el.getAttribute('data-testid'), el.getAttribute('rel'),
      el.textContent, String(el.className || '')].filter(Boolean).join(' ');
    const inNextContainer = !!el.closest('li.next, .next-page, .pagination-next, [data-testid*="next"]');
    if (!(/\bnext\b/i.test(description) || inNextContainer || /[›»→]/.test(el.textContent || ''))) return false;
    if (el.disabled || el.getAttribute('aria-disabled') === 'true' || el.closest('[aria-disabled="true"], .disabled, [disabled]')) return false;
    if (el.tagName === 'A' && !el.getAttribute('href')) return false;
    return el.getClientRects().length > 0;
  });
  if (advance && next) next.click();
  return JSON.stringify({href:location.href, ready:document.readyState,
    ids:ids.slice(0,50), next:!!next, advanced:!!(advance && next)});
})'''


def strava_visible_activity_page(cdp, *, advance=False):
    script=STRAVA_PAGE_SCAN_JS+'('+('true' if advance else 'false')+')'
    raw=cdp.evaluate(script)
    state=json.loads(raw) if isinstance(raw,str) else {}
    if not isinstance(state,dict):return {'ids':[], 'next':False, 'advanced':False}
    ids=[]
    for value in state.get('ids',[]):
        if isinstance(value,str) and value.isdecimal() and len(value)>=7:
            ident=int(value)
            if ident not in ids:ids.append(ident)
    return {'ids':ids,'next':bool(state.get('next')),'advanced':bool(state.get('advanced')),
            'href':state.get('href','')}


def strava_extend_recent_activity_ids(cdp, initial_ids, *, target=25):
     
     
     
    found=list(dict.fromkeys(initial_ids))[:target]
    if len(found)>=target:return found
    last_change=time.monotonic()
    max_pages = min(50, max(4, target))
    for page in range(max_pages):
        if STRAVA_STOP.is_set():raise ValueError('Strava connection was disconnected')
        state=None
        while time.monotonic()-last_change < 2.5:
            state=strava_visible_activity_page(cdp)
            visible=state['ids']
            added=False
            for ident in visible:
                if ident not in found:
                    found.append(ident)
                    added=True
                    if len(found)>=target:return found[:target]
            if added:
                last_change=time.monotonic()
            time.sleep(.45)
        if state is None:state=strava_visible_activity_page(cdp)
        if not state['next'] or len(found)>=target or page>=max_pages-1:return found[:target]
        previous_page=set(state['ids'])
        clicked=strava_visible_activity_page(cdp,advance=True)
        if not clicked['advanced']:return found[:target]
        deadline=time.monotonic()+12
        changed=False
        while time.monotonic()<deadline:
            if STRAVA_STOP.is_set():raise ValueError('Strava connection was disconnected')
            time.sleep(.55)
            state=strava_visible_activity_page(cdp)
            current=set(state['ids'])
            if current and current!=previous_page:
                changed=True
                last_change=time.monotonic()
                break
        if not changed:return found[:target]
    return found[:target]


def strava_recent_activity_ids(cdp, *, sign_in=False, target=None):
    if target is None:
        target = 10 if sign_in else strava_recent_count()
    if type(target) is not int or not 1 <= target <= 50:
        raise ValueError('Strava recent activity count must be from 1 to 50')
     
     
    script = r'''JSON.stringify({href:location.href,ids:[...new Set(Array.from(document.querySelectorAll('a[href*="/activities/"]')).map(a=>{let m=a.href.match(/\/activities\/(\d+)/);return m?m[1]:null}).filter(Boolean))].slice(0,50),ready:document.readyState,password:[...document.querySelectorAll('input[type="password"]')].some(el=>el.getClientRects().length>0 && getComputedStyle(el).visibility!=='hidden')})'''
    deadline=time.monotonic()+(240 if sign_in else 35)
    last=None
    login_since=None
    returned_to_activities=False
    on_other_strava_since=None
    confirmed_account_page_since=None
    while time.monotonic()<deadline:
        if STRAVA_STOP.is_set():raise ValueError('Strava connection was disconnected')
        try:
            raw=cdp.evaluate(script)
            state=json.loads(raw) if isinstance(raw,str) else {}
            last=state
            url=state.get('href','')
            if state.get('ids') and '/athlete/training' in url:
                first=[int(v) for v in state['ids'] if isinstance(v,str) and v.isdecimal() and len(v)>=7][:target]
                return first if sign_in or len(first)>=target else strava_extend_recent_activity_ids(cdp,first,target=target)
             
             
             
             
             
            parsed=urlparse(url) if isinstance(url,str) else urlparse('')
            on_account_page=(parsed.hostname in ('strava.com','www.strava.com')
                and parsed.path.rstrip('/')=='/athlete/training'
                and state.get('ready')=='complete' and not strava_signin_page(state))
            if sign_in and on_account_page:
                if confirmed_account_page_since is None:
                    confirmed_account_page_since=time.monotonic()
                elif time.monotonic()-confirmed_account_page_since>=5:
                    return []
            else:
                confirmed_account_page_since=None
            if not sign_in and state.get('ready','complete')=='complete' and strava_signin_page(state):
                if login_since is None:login_since=time.monotonic()
                elif time.monotonic()-login_since>=7:
                    raise StravaReauthenticationRequired('Strava returned a login page even with the saved browser session. Select Reconnect Strava in Settings')
            else:
                login_since=None
             
             
             
            if (sign_in and not returned_to_activities and parsed.hostname in ('strava.com','www.strava.com')
                    and '/athlete/training' not in parsed.path and not strava_signin_page(state)
                    and state.get('ready')=='complete'):
                if on_other_strava_since is None:
                    on_other_strava_since=time.monotonic()
                elif time.monotonic()-on_other_strava_since>=1.5:
                    cdp.call('Page.navigate',{'url':STRAVA_TRAINING_URL})
                    returned_to_activities=True
            else:
                on_other_strava_since=None
             
             
             
        except (socket.timeout,TimeoutError):
            pass
        time.sleep(1.5)
    if last and last.get('ready','complete')=='complete' and strava_signin_page(last):
        if sign_in:raise ValueError('Please finish signing in to Strava in the opened browser window')
        raise StravaReauthenticationRequired('Strava still shows its login page. Select Reconnect Strava in Settings')
    raise ValueError('Could not identify recent activities on Strava. The website may have changed or the account may need sign-in')


def strava_download_gpx(cdp, activity_id, download_dir):
     
    try:
        cdp.call('Browser.setDownloadBehavior',{'behavior':'allow','downloadPath':str(download_dir)})
    except ValueError:
        try:
            cdp.call('Page.setDownloadBehavior',{'behavior':'allow','downloadPath':str(download_dir)})
        except ValueError:
            raise ValueError('The browser did not permit activity-file downloads') from None
    existing={p.name for p in download_dir.iterdir()}
    try:
        result=cdp.call('Page.navigate',{'url':'https://www.strava.com/activities/{}/export_gpx'.format(activity_id)})
         
         
        error_text=str(result.get('errorText','')) if isinstance(result,dict) else ''
        if error_text and error_text!='net::ERR_ABORTED':
            raise ValueError('Strava GPX navigation failed: '+error_text[:100])
    except ValueError as exc:
        if 'ERR_ABORTED' not in str(exc):
            raise
    deadline=time.monotonic()+45
    last_auth_probe=time.monotonic()
    while time.monotonic()<deadline:
        if STRAVA_STOP.is_set():raise ValueError('Strava was disconnected during download')
         
         
        if time.monotonic()-last_auth_probe>=3:
            last_auth_probe=time.monotonic()
            try:
                state=cdp.evaluate("JSON.stringify({href:location.href,password:!!document.querySelector('input[type=\"password\"]')})")
                if isinstance(state,str) and strava_signin_page(json.loads(state)):
                    raise StravaReauthenticationRequired('Strava login expired during GPX export. Select Reconnect Strava in Settings')
            except (OSError,ConnectionError,TimeoutError,ValueError) as exc:
                if isinstance(exc,StravaReauthenticationRequired):raise
        candidates=[p for p in download_dir.iterdir() if p.name not in existing and p.is_file() and p.suffix.casefold()=='.gpx']
        pending=[p for p in download_dir.iterdir() if p.suffix.casefold() in ('.crdownload','.tmp')]
        if candidates and not pending:
            file=max(candidates,key=lambda p:p.stat().st_mtime_ns)
            if file.stat().st_size > 64*1024*1024:raise ValueError('GPX exceeds the 64 MiB safety limit')
            raw=file.read_bytes()
            if not re.search(br'<(?:[A-Za-z0-9_]+:)?gpx\b',raw[:2048],re.I):
                raise ValueError('Strava returned a file that is not GPX')
            file.unlink()
            return raw
        time.sleep(.3)
     
     
    try:
        state = cdp.evaluate("JSON.stringify({href:location.href,password:!!document.querySelector('input[type=\"password\"]')})")
        if isinstance(state, str) and strava_signin_page(json.loads(state)):
            raise StravaReauthenticationRequired('Strava login expired during GPX export. Select Reconnect Strava in Settings')
    except (OSError, ConnectionError, TimeoutError, ValueError) as exc:
        if isinstance(exc, StravaReauthenticationRequired):raise
    raise ValueError('Strava did not return a GPX download for activity {}'.format(activity_id))


def strava_save_original(folder_name, activity_id, raw):
     
    folder=Path(folder_name)
    if not folder.is_dir() or folder.is_symlink():raise ValueError('Your chosen activity folder is unavailable')
    target=folder/('{}_Strava.gpx'.format(activity_id))
    digest=hashlib.sha256(raw).hexdigest()
    if target.exists():
        if target.is_symlink():raise ValueError('Cannot overwrite a linked GPX file')
        if hashlib.sha256(target.read_bytes()).hexdigest()==digest:return target,False
        target=folder/('{}_Strava-{}.gpx'.format(activity_id,digest[:12]))
        if target.exists():
            if target.is_symlink() or hashlib.sha256(target.read_bytes()).hexdigest()!=digest:raise ValueError('Strava GPX filename conflict')
            return target,False
    fd,temp=tempfile.mkstemp(prefix='.strava-transfer-',suffix='.part',dir=str(folder))
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write(raw);stream.flush();os.fsync(stream.fileno())
        os.replace(temp,target)
        return target,True
    finally:
        if os.path.exists(temp):os.unlink(temp)


def strava_connect_job():
    global STRAVA_LAST_ATTEMPT_MONO
    if not STRAVA_SYNC_LOCK.acquire(blocking=False):return
    proc=None;cdp=None;connected_now=False
    with STRAVA_STATUS_LOCK:STRAVA_STATUS.update(connecting=True,running=True,message='Opening a separate Edge/Chrome profile for auto-sync. Your normal browser login cannot be reused automatically; sign in here once. LibreHeatmaps never receives your password.')
    try:
        if STRAVA_STOP.is_set():raise ValueError('Strava was disconnected')
        proc,port=strava_start_browser(visible=True)
        cdp=StravaDevTools(strava_browser_target(port))
        ids=strava_recent_activity_ids(cdp,sign_in=True)
        if STRAVA_STOP.is_set():raise ValueError('Strava was disconnected')
        with db_connect() as con:
            con.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('strava_browser_connected','1')")
            con.execute("DELETE FROM app_settings WHERE key=?", (STRAVA_RECONNECT_KEY,))
         
        with STRAVA_SCHEDULE_LOCK:STRAVA_LAST_ATTEMPT_MONO=time.monotonic()
        connected_now=True
        with STRAVA_STATUS_LOCK:
            STRAVA_STATUS.update(message=('Strava session verified; {} recent activity links visible. Checking for missing GPX routes…'.format(len(ids))
                if ids else 'Strava session verified. No activity links were visible during sign-in; checking recent rides separately…'))
    except Exception as exc:
        if not STRAVA_STOP.is_set():
            with STRAVA_STATUS_LOCK:STRAVA_STATUS.update(message='Strava connection needs attention: '+str(exc)[:240])
    finally:
        closed_gracefully=False
        if cdp:
            try:
                cdp.call('Browser.close')
                closed_gracefully=True
            except (ValueError,ConnectionError,OSError,TimeoutError,AttributeError):pass
            cdp.close()
        strava_end_browser(proc,graceful=closed_gracefully)
        with STRAVA_STATUS_LOCK:STRAVA_STATUS.update(connecting=False,running=False)
        STRAVA_SYNC_LOCK.release()
    if connected_now and not STRAVA_STOP.is_set():
        threading.Thread(target=strava_first_sync_after_connect,daemon=True,name='LibreHeatmaps-Strava-First-Sync').start()


def strava_first_sync_after_connect():
     
     
    time.sleep(2)
    if not STRAVA_STOP.is_set() and strava_connected():
        strava_sync_job()


def strava_disconnect():
    global STRAVA_LAST_ATTEMPT_MONO
    STRAVA_STOP.set()
    with db_connect() as con:
        con.execute("DELETE FROM app_settings WHERE key IN ('strava_browser_connected',?)", (STRAVA_RECONNECT_KEY,))
    with STRAVA_BROWSER_LOCK:
        proc=STRAVA_BROWSER_PROCESS
    if proc is not None:strava_end_browser(proc)
     
    if not STRAVA_SYNC_LOCK.acquire(timeout=15):
        raise ValueError('Stopped Strava syncing. The browser session is still closing; please select Disconnect again to remove its files')
    try:
         
        with db_connect() as con:
            con.execute("DELETE FROM app_settings WHERE key IN ('strava_browser_connected',?)", (STRAVA_RECONNECT_KEY,))
        profile=strava_profile_path()
        if profile.is_symlink():
            profile.unlink()
        elif profile.is_dir():
            shutil.rmtree(profile)
        with STRAVA_SCHEDULE_LOCK:STRAVA_LAST_ATTEMPT_MONO=0.0
        with STRAVA_STATUS_LOCK:
            STRAVA_STATUS.update(running=False,connecting=False,message='Strava disconnected; the separate local browser session was deleted. To sign in again, acknowledge the Strava website warning above and select Sign in for auto-sync. Imported rides remain untouched.',last_sync=None)
    finally:
        STRAVA_SYNC_LOCK.release()
    return strava_status()


def strava_sync_job():
    global STRAVA_LAST_ATTEMPT_MONO
    if not STRAVA_SYNC_LOCK.acquire(blocking=False):return
    cdp=None;proc=None
    added=skipped=failed=checked=0
    failure_examples=[]
    skipped_because_busy=False
    try:
        if not strava_connected():raise ValueError('Connect your own Strava account in Settings first')
        with STATE_LOCK:
            if JOB.get('status')=='running':
                skipped_because_busy=True
                return
            JOB.update(status='running',processed=0,total=0,added=0,skipped=0,failed=0,updated=0,message='Checking recent Strava rides')
        recent_count = strava_recent_count()
        with STRAVA_STATUS_LOCK:STRAVA_STATUS.update(running=True,message='Checking your {} newest Strava activity links…'.format(recent_count))
        if STRAVA_STOP.is_set():raise ValueError('Strava was disconnected')
        proc,port=strava_start_browser(visible=False)
        cdp=StravaDevTools(strava_browser_target(port))
        ids=strava_recent_activity_ids(cdp, target=recent_count)
        if not ids:raise ValueError('No recent activity links were found on your Strava training page')
        checked=len(ids)
        with db_connect() as con:
            known={str(r[0]) for r in con.execute('SELECT activity_id FROM activities WHERE activity_id IS NOT NULL')}
            pending=[aid for aid in reversed(ids) if str(aid) not in known]
            folder_name=load_watch_folder()
            set_job(total=len(pending),message='Downloading only missing Strava GPX rides')
            with tempfile.TemporaryDirectory(prefix='libre-strava-') as temp:
                for index,aid in enumerate(pending,1):
                    if STRAVA_STOP.is_set() or not strava_connected():raise ValueError('Strava was disconnected')
                    set_job(processed=index-1,message='Strava GPX for ride {}'.format(aid))
                    try:
                        raw=strava_download_gpx(cdp,aid,Path(temp))
                        key=hashlib.sha256(('strava-gpx:{}:'.format(aid)).encode()+hashlib.sha256(raw).digest()).hexdigest()
                        outcome=insert_activity(con,'{}.gpx'.format(aid),key,io.BytesIO(raw),{})
                        if outcome=='added':added+=1
                        elif outcome in ('skipped','enriched'):skipped+=1
                        else:
                            failed+=1
                            failure_examples.append('Activity {}: the downloaded GPX has no usable GPS track'.format(aid))
                        if folder_name and outcome in ('added','skipped','enriched'):
                            target,_=strava_save_original(folder_name,aid,raw)
                            stat=target.stat()
                            con.execute('INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)',(watch_seen_key(folder_name,target),'{}:{}'.format(stat.st_size,stat.st_mtime_ns)))
                            con.commit()
                    except StravaReauthenticationRequired:
                         
                        raise
                    except Exception as exc:
                        failed+=1
                        detail='Activity {}: {}'.format(aid,str(exc).strip()[:140] or type(exc).__name__)
                        if len(failure_examples)<3:failure_examples.append(detail)
                        print('[LibreHeatmaps] Strava GPX import problem: {}'.format(detail),flush=True)
                    set_job(processed=index,added=added,skipped=skipped,failed=failed)
            con.execute('INSERT INTO import_history(imported_at,label,added,skipped,no_gps,failed,updated) VALUES (?,?,?,?,?,?,?)',(dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds'),'Strava GPX (browser)',added,skipped,0,failed,0))
        existing=checked-len(pending)+skipped
        if added:
            message='Strava: imported {} new GPS route{}; {} already present; {} failed ({} recent activities checked).'.format(added,'' if added==1 else 's',existing,failed,checked)
        elif failed:
            message='Strava: no rides imported; {} missing GPX download{} failed ({} recent activities checked).'.format(failed,'' if failed==1 else 's',checked)
        else:
            message='Strava: no new GPS routes; {} recent activities were already in LibreHeatmaps. The heatmap is unchanged.'.format(existing)
        if checked<recent_count:
            message+=' Only {} of the requested {} activity links were available from Strava’s visible activity pages.'.format(checked,recent_count)
        if failure_examples:
            message+=' '+failure_examples[0]
        result_status='error' if failed and not added else 'done'
        with STRAVA_STATUS_LOCK:STRAVA_STATUS.update(last_sync=dt.datetime.now().isoformat(timespec='seconds'),checked=checked,added=added,skipped=existing,failed=failed,message=message)
        set_job(status=result_status,message=message,added=added,skipped=existing,failed=failed,processed=len(pending),total=len(pending))
        if added:start_heat_warmup()
    except StravaReauthenticationRequired as exc:
        strava_require_reconnect()
        message='Strava sync paused: '+str(exc)[:220]
        with STATE_LOCK:
            if JOB.get('status')=='running' and JOB.get('message','').startswith(('Checking recent Strava','Downloading only missing Strava','Strava GPX for ride')):
                set_job(status='error',message=message)
    except Exception as exc:
        message='Strava GPX check failed: '+str(exc)[:260]
        if not STRAVA_STOP.is_set():
            with STRAVA_STATUS_LOCK:STRAVA_STATUS.update(message=message,failed=failed)
        with STATE_LOCK:
            if JOB.get('status')=='running' and JOB.get('message','').startswith(('Checking recent Strava','Downloading only missing Strava','Strava GPX for ride')):
                set_job(status='error',message=message)
    finally:
        closed_gracefully=False
        if cdp:
            try:
                cdp.call('Browser.close')
                closed_gracefully=True
            except (ValueError,ConnectionError,OSError,TimeoutError,AttributeError):pass
            cdp.close()
        strava_end_browser(proc,graceful=closed_gracefully)
        with STRAVA_SCHEDULE_LOCK:
            STRAVA_LAST_ATTEMPT_MONO=0.0 if skipped_because_busy else time.monotonic()
        with STRAVA_STATUS_LOCK:STRAVA_STATUS.update(running=False)
        STRAVA_SYNC_LOCK.release()


def strava_sync_due(now=None):
    if now is None:now=time.monotonic()
    with STRAVA_SCHEDULE_LOCK:last=STRAVA_LAST_ATTEMPT_MONO
    return not last or now-last>=strava_sync_interval()*60


def strava_sync_loop():
    while True:
        try:
            if strava_connected() and strava_sync_due() and not STRAVA_SYNC_LOCK.locked():
                with STATE_LOCK:busy=JOB.get('status')=='running'
                if not busy:strava_sync_job()
        except Exception as exc:
            print('[LibreHeatmaps] Strava scheduling error: {}'.format(type(exc).__name__),flush=True)
        time.sleep(20)


def robust_speed_flags(rows):
    cohorts={}
    for r in rows:
        sport=(r[1] or '').casefold()
        if not any(w in sport for w in ('ride','bik','cycl')):continue
        avg=r[9] if r[9] is not None else ((r[3] or 0)/r[4] if r[4] and r[4]>0 else None)
        peak=r[10]
        cohorts.setdefault(sport,[]).append((r[14],avg,peak))
    flagged=set()
    for rides in cohorts.values():
        if len(rides)<12:continue
        for index in (1,2):
            values=sorted(v[index] for v in rides if v[index] is not None and math.isfinite(v[index]) and v[index]>0)
            if len(values)<12:continue
            median=values[len(values)//2] if len(values)%2 else (values[len(values)//2-1]+values[len(values)//2])/2
            deviations=sorted(abs(v-median) for v in values)
            mad=deviations[len(deviations)//2] if len(deviations)%2 else (deviations[len(deviations)//2-1]+deviations[len(deviations)//2])/2
            floor=7.15 if index==1 else 14.3
            cutoff=max(median*1.6,median+floor,median+3.5*1.4826*mad)
            flagged.update(r[0] for r in rides if r[index] is not None and math.isfinite(r[index]) and r[index]>cutoff)
    return flagged



SPEED_REVIEW_FIELDS = "name,sport,day,COALESCE(recorded_distance_m,distance_m),moving_seconds,elapsed_seconds,elevation_m,recorded_distance_m,avg_heart_rate,avg_speed,max_speed,bike,moving_source,elevation_source,id"


def speed_review_snapshot():
    prefs = statistics_preferences()
    with db_connect() as con:
        approved = {int(row[0]) for row in con.execute("SELECT activity_id FROM speed_filter_exceptions WHERE included=1")}
        if not (prefs['filter_speed_anomalies'] or prefs['filter_speed_smart']):
            return {}, approved, prefs
        rows = con.execute("SELECT " + SPEED_REVIEW_FIELDS + " FROM activities").fetchall()
    smart = robust_speed_flags(rows) if prefs['filter_speed_smart'] else set()
    flagged = {}
    for r in rows:
        reasons = []
        if prefs['filter_speed_anomalies'] and speed_outlier(r, prefs['speed_threshold_mph'] * 0.44704):
            speed_label = format(prefs['speed_threshold_mph'], 'g') + ' mph'
            reasons.append('Custom cycling speed threshold (' + speed_label + ')')
        if r[14] in smart:
            reasons.append('Unusual compared with similar rides (experimental)')
        if reasons:
            flagged[r[14]] = reasons
    return flagged, approved, prefs


def speed_review_summary():
    flagged, approved, prefs = speed_review_snapshot()
    active = bool(prefs['filter_speed_anomalies'] or prefs['filter_speed_smart'])
    return {'active':active, 'excluded_count':len(flagged.keys()-approved) if active else 0,
            'approved_count':len(flagged.keys() & approved) if active else 0}


def speed_review(params):
    flagged, approved, prefs = speed_review_snapshot()
    active = prefs['filter_speed_anomalies'] or prefs['filter_speed_smart']
    sql, args = filter_query(params)
    with db_connect() as con:
        rows = con.execute("SELECT " + SPEED_REVIEW_FIELDS + " FROM activities" + sql + " ORDER BY day DESC,id DESC", args).fetchall() if active else []
    excluded = []
    allowed = []
    for r in rows:
        reason = flagged.get(r[14], [])
        if not reason and r[14] not in approved:
            continue
        item = {'id':r[14], 'name':r[0], 'sport':r[1], 'day':r[2], 'distance_m':r[3],
                'avg_speed':r[9], 'max_speed':r[10], 'reasons':reason, 'approved':r[14] in approved}
        if item['approved']:
            allowed.append(item)
        elif reason:
            excluded.append(item)
    return {'active':bool(active), 'excluded':excluded, 'allowed':allowed,
            'excluded_count':len(excluded), 'allowed_count':len(allowed)}


def set_speed_exception(activity_id, included):
    if type(activity_id) is not int or activity_id < 1 or activity_id > 999999999999:
        raise ValueError('Invalid activity selection')
    if type(included) is not bool:
        raise ValueError('Expected a true or false exception value')
    with db_connect() as con:
        if con.execute('SELECT 1 FROM activities WHERE id=?', (activity_id,)).fetchone() is None:
            raise ValueError('Activity not found')
        if included:
            con.execute('INSERT OR REPLACE INTO speed_filter_exceptions(activity_id,included) VALUES (?,1)', (activity_id,))
        else:
            con.execute('DELETE FROM speed_filter_exceptions WHERE activity_id=?', (activity_id,))
    flagged, approved, prefs = speed_review_snapshot()
    return {'activity_id':activity_id, 'approved':activity_id in approved,
            'excluded':activity_id in flagged and activity_id not in approved,
            'reasons':flagged.get(activity_id, []), 'active':prefs['filter_speed_anomalies'] or prefs['filter_speed_smart']}


def speed_outlier(row, threshold_mps=22.352):
    sport = (row[1] or '').casefold()
    if not any(word in sport for word in ('ride','cycl','bik')):
        return False
    for speed in (row[9],row[10]):
        if speed is not None and (not math.isfinite(speed) or speed >= threshold_mps or speed < 0):
            return True
    if row[4] and row[4] > 0 and (row[3] or 0)/row[4] >= threshold_mps:
        return True
    return False


def insights(params):
    sql, args = filter_query(params)
    with db_connect() as con:
        query = "SELECT name,sport,day,COALESCE(recorded_distance_m,distance_m),moving_seconds,elapsed_seconds,elevation_m,recorded_distance_m,avg_heart_rate,avg_speed,max_speed,bike,moving_source,elevation_source,id FROM activities" + sql
        rows = con.execute(query, args).fetchall()
    flagged, approved, prefs = speed_review_snapshot()
    with db_connect() as con:
        extra=con.execute("SELECT day,calories_kcal,avg_temp_c,max_temp_c,weather_temp_c,wind_speed_mps,wind_gust_mps,humidity_pct,avg_cadence,avg_power,id,name,sport,avg_heart_rate,max_power,max_cadence,total_cycles,normalized_power,training_stress_score,intensity_factor,max_heart_rate FROM activities"+sql,args).fetchall() if prefs.get('advanced_data') else []
    filter_anomalies=prefs['filter_speed_anomalies']
    valid_speed_rows=[r for r in rows if r[14] not in flagged or r[14] in approved]
    excluded_speeds = len(rows)-len(valid_speed_rows)
    count = len(rows)
    total_distance = sum(row[3] or 0 for row in rows)
    moving = sum(row[4] or 0 for row in rows)
    elapsed = sum(row[5] or 0 for row in rows)
    ascent = sum(row[6] or 0 for row in rows)
    official = sum(row[7] is not None for row in rows)
    moving_count = sum(row[4] is not None for row in rows)
    elevation_count = sum(row[6] is not None for row in rows)
    dates = []
    years, months, sports, weekday_distance = {}, {}, {}, [0.0]*7
    bikes = {}
    moving_estimates = sum(r[12] == "track-estimate" for r in rows)
    elevation_estimates = sum(r[13] == "track-estimate" for r in rows)
    for row in rows:
        name, sport, day, dist = row[:4]
        sport = sport or "Unknown"
        totals = sports.setdefault(sport, [0, 0])
        totals[0] += 1
        totals[1] += dist or 0
        if any(w in sport.casefold() for w in ("ride", "bik", "cycl")):
            key = (sport, row[11] or "Unidentified bike")
            bt = bikes.setdefault(key, [0, 0.0])
            bt[0] += 1
            bt[1] += dist or 0
        if day:
            try:
                parsed = dt.date.fromisoformat(day)
            except ValueError:
                continue
            dates.append(parsed)
            weekday_distance[parsed.weekday()] += dist or 0
            year = str(parsed.year)
            month = day[:7]
            y = years.setdefault(year, [0, 0])
            m = months.setdefault(month, [0, 0])
            y[0] += 1; y[1] += dist or 0
            m[0] += 1; m[1] += dist or 0
    sorted_days = sorted(set(dates))
    streak = best = 0
    earlier = None
    for current in sorted_days:
        streak = streak + 1 if earlier and (current-earlier).days == 1 else 1
        best = max(best, streak)
        earlier = current
    weekday_counts = [0]*7
    for day in dates:
        weekday_counts[day.weekday()] += 1
    longest = max(rows, key=lambda r:r[3] or 0, default=None)
    max_ascent = max((r for r in rows if r[6] is not None), key=lambda r:r[6], default=None)
    longest_moving = max((r for r in rows if r[4] is not None), key=lambda r:r[4], default=None)
    top_month = max(months.items(), key=lambda x:(x[1][0], x[0]), default=None)
    top_year = max(years.items(), key=lambda x:(x[1][0],x[0]), default=None)
    fastest = max((r for r in valid_speed_rows if (r[4] or 0) >= 600 and (r[3] or 0) >= 1000), key=lambda r:r[3] / r[4], default=None)
    peak_speed = max((r for r in valid_speed_rows if r[10] is not None and math.isfinite(r[10]) and 0 <= r[10] <= 200), key=lambda r:r[10], default=None)
    active_weeks = len({d.isocalendar()[:2] for d in dates})
    dist_per_week = total_distance / active_weeks if active_weeks else 0
    speed_moving = sum(r[4] or 0 for r in valid_speed_rows)
    speed_distance = sum(r[3] or 0 for r in valid_speed_rows)
    avg_speed = speed_distance / speed_moving * 3.6 if speed_moving > 0 and all(r[4] is not None for r in valid_speed_rows) else None
    top_distance_month = max(months.items(), key=lambda x:(x[1][1],x[0]), default=None)
    riding_rows = [r for r in rows if any(w in (r[1] or '').casefold() for w in ('ride','bik','cycl'))]
    longest_ride = max(riding_rows, key=lambda r: (r[3] or 0, r[14]), default=None)
    max_ascent_ride = max((r for r in riding_rows if r[6] is not None),key=lambda r:(r[6],r[14]),default=None)
    def advanced_extreme(column, mode='max', low=None, high=None, riding_only=False):
        valid = [r for r in extra if isinstance(r[column],(int,float)) and math.isfinite(r[column])
                 and (low is None or r[column]>=low) and (high is None or r[column]<=high)
                 and (not riding_only or any(w in (r[12] or '').casefold() for w in ('ride','bik','cycl')))]
        if not valid:return None
        winner = (max if mode=='max' else min)(valid,key=lambda r:(r[column], r[0] or '',r[10]))
        return {'id':winner[10],'name':winner[11],'sport':winner[12],'day':winner[0],
                'value':winner[column],'coverage':len(valid)}
    advanced_records = {}
    if prefs.get('advanced_data'):
        for key,col,mode,low,high in (
            ('hottest_weather',4,'max',-70,70),('coldest_weather',4,'min',-70,70),
            ('warmest_device',2,'max',-70,70),('coldest_device',2,'min',-70,70),
            ('windiest',5,'max',0,110),('strongest_gust',6,'max',0,130),
            ('highest_avg_cadence',8,'max',1,250),('highest_avg_power',9,'max',1,2500),
            ('highest_max_power',14,'max',1,3500),('highest_max_cadence',15,'max',1,250),('most_cycles',16,'max',1,10000000),('highest_normalized_power',17,'max',1,3500),('highest_training_stress',18,'max',0,2000),('most_calories',1,'max',1,100000),
            ('highest_avg_heart_rate',13,'max',20,240)):
            advanced_records[key]=advanced_extreme(col,mode,low,high,key in ('highest_avg_cadence','highest_max_cadence','most_cycles'))
        cadences=[r[8] for r in extra if isinstance(r[8],(int,float)) and math.isfinite(r[8]) and 1<=r[8]<=250 and any(w in (r[12] or '').casefold() for w in ('ride','bik','cycl'))]
        advanced_records['mean_ride_cadence']={'value':sum(cadences)/len(cadences),'coverage':len(cadences)} if cadences else None
    def ride_record(row):
        return {"id":row[14], "name":row[0], "sport":row[1], "day":row[2],
                "distance_m":row[3], "moving_seconds":row[4], "elapsed_seconds":row[5],
                "elevation_m":row[6], "bike":row[11]}
    top_routes = sorted(rows, key=lambda row:(row[3] or 0, row[14]), reverse=True)[:6]
    recent_routes = sorted(rows, key=lambda row:(row[2] or "", row[14]), reverse=True)[:10]
    return {
        "count":count,"filter_speed_anomalies":filter_anomalies,"filter_speed_smart":prefs["filter_speed_smart"],"excluded_speed_activities":excluded_speeds,"distance_m":round(total_distance,1),"moving_seconds":round(moving),
        "elapsed_seconds":round(elapsed),"elevation_m":round(ascent,2),
        "strava_distance_count":official,"mapped_gps_count":count,
        "moving_count":moving_count,"elapsed_count":sum(r[5] is not None for r in rows),"elevation_count":elevation_count,
        "moving_estimated_count":moving_estimates,"elevation_estimated_count":elevation_estimates,
        "bikes":[{"sport":k[0],"name":k[1],"count":v[0],"distance_m":round(v[1],1)} for k,v in sorted(bikes.items(),key=lambda x:(x[0][0].casefold(),-x[1][1],x[0][1].casefold()))],
        "avg_distance_m":round(total_distance/count,1) if count else 0,
        "first":min((r[2] for r in rows if r[2]),default=None),"last":max((r[2] for r in rows if r[2]),default=None),
        "longest":ride_record(longest) if longest else None,
        "longest_ride":ride_record(longest_ride) if longest_ride else None,
        "max_ascent_ride":ride_record(max_ascent_ride) if max_ascent_ride else None,
        "advanced_records":advanced_records,
        "max_ascent":ride_record(max_ascent) if max_ascent else None,
        "longest_moving":ride_record(longest_moving) if longest_moving else None,
        "sports":[{"name":k,"count":v[0],"distance_m":round(v[1],1)} for k,v in sorted(sports.items(),key=lambda x:x[1][0],reverse=True)],
        "top_month":{"month":top_month[0],"count":top_month[1][0]} if top_month else None,
        "top_year":{"year":top_year[0],"count":top_year[1][0]} if top_year else None,
        "favorite_weekday":(["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"][max(range(7),key=lambda k:weekday_counts[k])] if any(weekday_counts) else None),
        "active_days":len(sorted_days),"active_weeks":active_weeks,"longest_streak":best,
        "average_weekly_distance_m":round(dist_per_week,1),"overall_avg_speed_kmh":round(avg_speed,2) if avg_speed is not None else None,
        "peak_speed_mps":peak_speed[10] if peak_speed else None,
        "peak_speed":dict(ride_record(peak_speed),speed_mps=peak_speed[10]) if peak_speed else None,
        "peak_speed_count":sum(r[10] is not None and math.isfinite(r[10]) and 0 <= r[10] <= 200 for r in valid_speed_rows),
        "top_routes":[ride_record(r) for r in top_routes],"recent_routes":[ride_record(r) for r in recent_routes],
        "fastest":dict(ride_record(fastest), speed_kmh=round(fastest[3] / fastest[4] * 3.6,1)) if fastest else None,
        "biggest_distance_month":{"month":top_distance_month[0],"distance_m":round(top_distance_month[1][1],1)} if top_distance_month else None,
        "weekdays":[{"name":name,"count":weekday_counts[i],"distance_m":round(weekday_distance[i],1)} for i,name in enumerate(("Mon","Tue","Wed","Thu","Fri","Sat","Sun"))],
        "years":[{"year":k,"count":v[0],"distance_m":round(v[1],1)} for k,v in sorted(years.items())],
        "months":[{"month":k,"count":v[0],"distance_m":round(v[1],1)} for k,v in sorted(months.items())],
        "advanced_enabled":prefs.get('advanced_data',False),
        "advanced": {"coverage":{name:sum(v[index] is not None for v in extra) for name,index in (("calories_kcal",1),("avg_temp_c",2),("max_temp_c",3),("weather_temp_c",4),("wind_speed_mps",5),("wind_gust_mps",6),("humidity_pct",7),("avg_cadence",8),("avg_power",9),("max_cadence",15),("total_cycles",16),("normalized_power",17),("training_stress_score",18),("intensity_factor",19),("max_heart_rate",20))},
            "rides":[{"day":r[0],"calories":r[1],"temp_c":r[2],"weather_temp_c":r[4],"wind_mps":r[5],"humidity":r[7],"cadence":r[8],"power":r[9],"max_cadence":r[15],"cycles":r[16],"normalized_power":r[17],"training_stress":r[18],"intensity_factor":r[19]} for r in extra if r[0]][-20000:]} if prefs.get('advanced_data') else None,
        "analytics_limited": len(rows)>20000,
        "analytics": {
            "monthly_speeds":[{"month":k,"speed_kmh":round(sum(d/t*3.6 for d,t in vs)/len(vs),2),"count":len(vs)}
                for k,vs in sorted({m:[((r[3] or 0),r[4]) for r in valid_speed_rows if r[2] and r[2][:7]==m and r[4] and r[4]>0 and r[3] is not None] for m in months}.items()) if vs],
            "speed_history":[{"day":r[2],"speed_kmh":round((r[3] or 0)/r[4]*3.6,2),"id":r[14]} for r in sorted(valid_speed_rows,key=lambda r:(r[2] or '',r[14])) if r[2] and r[4] and r[4]>0 and r[3] is not None][-20000:],
            "speed_vs_duration":[{"day":r[2],"minutes":round(r[4]/60,1),"speed_kmh":round((r[3] or 0)/r[4]*3.6,2),"id":r[14]} for r in valid_speed_rows if r[4] and r[4]>0 and r[3] is not None][-20000:],
            "activity_distances":[{"day":r[2],"distance_km":round((r[3] or 0)/1000,2),"id":r[14]} for r in sorted(rows,key=lambda r:(r[2] or '',r[14])) if r[2]][-20000:],
            "distance_vs_duration":[{"day":r[2],"minutes":round(r[4]/60,1),"distance_km":round((r[3] or 0)/1000,2),"id":r[14]} for r in valid_speed_rows if r[4] and r[4]>0 and r[3] is not None][-20000:],
            "moving_history":[{"day":r[2],"hours":round(r[4]/3600,3),"id":r[14]} for r in sorted(rows,key=lambda r:(r[2] or '',r[14])) if r[2] and r[4] is not None and r[4]>=0][-20000:],
            "monthly_moving_time":[{"month":k,"hours":round(sum(r[4] or 0 for r in rows if r[2] and r[2][:7]==k)/3600,2)} for k in sorted(months)],
        },
    }


 
 
def calendar_overview(params):
    year_text=params.get('year', [''])[0]
    if len(year_text)!=4 or not year_text.isascii() or not year_text.isdecimal():
        raise ValueError('Invalid calendar year')
    year=int(year_text)
    if not 1900 <= year <= 2100:raise ValueError('Calendar year outside supported range')
    focus=params.get('focus',['cycling'])[0]
    where,args=filter_query({'focus':[focus]})
    criteria=(where+' AND ' if where else ' WHERE ')+'day>=? AND day<?'
    with db_connect() as con:
        rows=con.execute('SELECT day,COUNT(*),COALESCE(SUM(COALESCE(recorded_distance_m,distance_m)),0),COALESCE(SUM(moving_seconds),0) FROM activities'
            +criteria+' GROUP BY day ORDER BY day',args+[f'{year:04d}-01-01',f'{year+1:04d}-01-01']).fetchall()
        latest=con.execute('SELECT MAX(day) FROM activities'+where,args).fetchone()[0]
    from datetime import date
    days=[];months={f'{year:04d}-{m:02d}':{'count':0,'distance_m':0.0,'moving_seconds':0,'active_days':0} for m in range(1,13)}
    for day,count,dist,seconds in rows:
        if not isinstance(day,str) or len(day)!=10:continue
        try:
            if date.fromisoformat(day).isoformat()!=day:continue
        except ValueError:continue
        entry={'day':day,'count':int(count),'distance_m':round(float(dist or 0),1),'moving_seconds':int(seconds or 0)}
        days.append(entry)
        month=months[day[:7]];month['count']+=entry['count'];month['distance_m']+=entry['distance_m'];month['moving_seconds']+=entry['moving_seconds'];month['active_days']+=1
    for month in months.values():month['distance_m']=round(month['distance_m'],1)
    return {'year':year,'focus':focus,'days':days,'months':months,'latest_day':latest,'total_count':sum(m['count'] for m in months.values()),'total_distance_m':round(sum(m['distance_m'] for m in months.values()),1)}


def calendar_day(params):
    from datetime import date
    day=params.get('day',[''])[0]
    if not isinstance(day,str) or len(day)!=10:
        raise ValueError('Invalid calendar day')
    try:
        if date.fromisoformat(day).isoformat()!=day:raise ValueError('Invalid calendar day')
    except ValueError:raise ValueError('Invalid calendar day')
    focus=params.get('focus',['cycling'])[0]
    where,args=filter_query({'focus':[focus]})
    criteria=(where+' AND ' if where else ' WHERE ')+'day=?'
    with db_connect() as con:
        total=con.execute('SELECT COUNT(*) FROM activities'+criteria,args+[day]).fetchone()[0]
        rows=con.execute("SELECT id,name,COALESCE(sport,'Unknown'),COALESCE(recorded_distance_m,distance_m),moving_seconds,bike FROM activities"
            +criteria+' ORDER BY id DESC LIMIT 120',args+[day]).fetchall()
    return {'day':day,'focus':focus,'total':total,'truncated':total>len(rows),
            'activities':[{'id':r[0],'name':r[1],'sport':r[2],'distance_m':r[3] or 0,'moving_seconds':r[4] or 0,'bike':r[5] or ''} for r in rows]}

def filter_query(params, bounds=False):
    clauses = []
    values = []
    focus=params.get('focus',['all'])[0]
    if focus not in ('cycling','foot','all'):raise ValueError('Invalid activity focus')
    if focus=='foot':
        clauses.append("(lower(sport) LIKE '%run%' OR lower(sport) LIKE '%jog%' OR lower(sport) LIKE '%walk%' OR lower(sport) LIKE '%hik%' OR lower(sport) LIKE '%trek%')")
    elif focus=='cycling':
        clauses.append("(lower(sport) LIKE '%rid%' OR lower(sport) LIKE '%bik%' OR lower(sport) LIKE '%cycl%' OR lower(sport) LIKE '%velo%' OR sport IS NULL OR sport IN ('Unknown','Route'))")
    sport = params.get("sport", [""])[0].strip()[:100]
    if sport:
        clauses.append("sport=?")
        values.append(sport)
    bike = params.get("bike", [""])[0].strip()[:160]
    if bike:
        clauses.append("bike=?")
        values.append(bike)
    after = params.get("from", [""])[0]
    before = params.get("to", [""])[0]
    if after and parse_date(after) == after:
        clauses.append("day>=?")
        values.append(after)
    if before and parse_date(before) == before:
        clauses.append("day<=?")
        values.append(before)
    year = params.get("year", [""])[0].strip()
    if len(year) == 4 and year.isdecimal():
        clauses.append("substr(day,1,4)=?")
        values.append(year)
    month = params.get("month", [""])[0].strip()
    if len(month) == 7 and month[4] == "-" and month[:4].isdecimal() and month[5:].isdecimal() and 1 <= int(month[5:]) <= 12:
        clauses.append("substr(day,1,7)=?")
        values.append(month)
    keyword = params.get("q", [""])[0].strip()[:100]
    if keyword:
        clauses.append("name LIKE ? ESCAPE '\\'")
        values.append("%" + keyword.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_") + "%")
    activity_id = params.get("activity_id", [""])[0]
    if activity_id:
        if not activity_id.isascii() or not activity_id.isdecimal() or len(activity_id) > 12 or int(activity_id) <= 0:
            raise ValueError("Invalid activity selection")
        clauses.append("id=?")
        values.append(int(activity_id))
    if bounds:
        for name in ("west", "south", "east", "north"):
            try:
                float(params[name][0])
            except (KeyError, ValueError, IndexError):
                raise ValueError("Missing map bounds")
        west, south, east, north = [float(params[n][0]) for n in ("west", "south", "east", "north")]
        if not all(math.isfinite(v) for v in (west, south, east, north)):
            raise ValueError("Invalid map bounds")
        west, east = max(-180, west), min(180, east)
        south, north = max(-85.0511, south), min(85.0511, north)
        clauses.append("east>=? AND west<=? AND north>=? AND south<=?")
        values.extend((west, east, south, north))
    return (" WHERE " + " AND ".join(clauses) if clauses else ""), values


ACTIVITY_TABLE_COLUMNS = ('day','name','sport','distance_m','moving_seconds','elapsed_seconds',
    'avg_speed','max_speed','avg_heart_rate','avg_power','elevation_m','bike','filename','point_count','id') + ADV_NUM_FIELDS + ('weather_condition',)
ACTIVITY_TABLE_SORT = {name:name for name in ACTIVITY_TABLE_COLUMNS}


def activity_table(params,as_csv=False):
    sql,args=filter_query(params)
    try:
        page=max(1,min(100000,int(params.get('page',['1'])[0])))
        limit=max(10,min(200,int(params.get('limit',['50'])[0])))
    except (TypeError,ValueError):
        raise ValueError('Invalid table pagination')
    sort=params.get('sort',['day'])[0]
    if sort not in ACTIVITY_TABLE_SORT:raise ValueError('Invalid sorting field')
    direction=params.get('direction',['desc'])[0]
    if direction not in ('asc','desc'):raise ValueError('Invalid sort direction')
    cols=params.get('columns',[''])[0].split(',') if as_csv else list(ACTIVITY_TABLE_COLUMNS)
    if as_csv and (not cols or len(cols)>len(ACTIVITY_TABLE_COLUMNS) or len(set(cols))!=len(cols) or any(c not in ACTIVITY_TABLE_COLUMNS for c in cols)):
        raise ValueError('Invalid CSV columns')
    ordering=f' ORDER BY {ACTIVITY_TABLE_SORT[sort]} {direction.upper()}, id DESC'
    fields='id,name,sport,day,COALESCE(recorded_distance_m,distance_m) AS distance_m,moving_seconds,elapsed_seconds,avg_speed,max_speed,avg_heart_rate,avg_power,elevation_m,bike,filename,point_count,'+','.join(ADV_NUM_FIELDS)+',weather_condition'
    with db_connect() as con:
        total=con.execute('SELECT COUNT(*) FROM activities'+sql,args).fetchone()[0]
        if as_csv:
            if total>50000:raise ValueError('CSV export limited to 50,000 activities; narrow the filters')
            records=con.execute('SELECT '+fields+' FROM activities'+sql+ordering,args).fetchall()
        else:
            records=con.execute('SELECT '+fields+' FROM activities'+sql+ordering+' LIMIT ? OFFSET ?',args+[limit,(page-1)*limit]).fetchall()
    names=['id','name','sport','day','distance_m','moving_seconds','elapsed_seconds','avg_speed','max_speed','avg_heart_rate','avg_power','elevation_m','bike','filename','point_count']+list(ADV_NUM_FIELDS)+['weather_condition']
    rows=[dict(zip(names,r)) for r in records]
    flagged, approved, prefs = speed_review_snapshot()
    for row in rows:
        row['speed_excluded']=row['id'] in flagged and row['id'] not in approved
        row['speed_approved']=row['id'] in approved
    if as_csv:
        out=io.StringIO(newline='')
        writer=csv.writer(out)
        writer.writerow(cols)
        for r in rows:
            writer.writerow([("'"+str(r[c])) if isinstance(r[c],str) and r[c].lstrip().startswith(('=','+','-','@')) else r[c] for c in cols])
        return out.getvalue().encode('utf-8-sig')
    return {'total':total,'page':page,'limit':limit,'rows':rows}


def iter_coordinates(blob):
    raw = zlib.decompress(blob)
    for lat, lon in struct.iter_unpack("<ii", raw):
        if lat == 2147483647:
            yield None
        else:
            yield lat / 1e6, lon / 1e6


def project_xy(lat, lon, zoom):
    scale = 256 * (2 ** zoom)
    x = (lon + 180.0) / 360.0 * scale
    a = math.radians(max(-85.0511, min(85.0511, lat)))
    y = (1 - math.asinh(math.tan(a)) / math.pi) / 2 * scale
    return x, y


def activity_preview(params):
    identity = params.get("id", [""])[0]
    if not identity.isascii() or not identity.isdecimal() or not 1 <= len(identity) <= 12 or int(identity) <= 0:
        raise ValueError("Invalid activity selection")
    with db_connect() as con:
        row = con.execute("""SELECT id,name,sport,day,COALESCE(recorded_distance_m,distance_m),
            moving_seconds,elapsed_seconds,elevation_m,bike,avg_heart_rate,avg_speed,max_speed,
            coordinates,point_count,west,south,east,north,avg_power,filename,moving_source,
            elevation_source,recorded_distance_m,distance_m,""" + ",".join(ADV_NUM_FIELDS) + ",weather_condition FROM activities WHERE id=?", (int(identity),)).fetchone()
    if row is None:
        raise ValueError("Activity not found")
    step = max(1, math.ceil(max(1, row[13]) / 3800))
    points, i, last = [], 0, None
    for point in iter_coordinates(row[12]):
        if point is None:
            if last is not None and (not points or points[-1] != last):
                points.append(last)
            if points and points[-1] is not None:
                points.append(None)
            last, i = None, 0
            continue
        last = [round(point[0], 6), round(point[1], 6)]
        if i % step == 0:
            points.append(last)
        i += 1
    if last is not None and (not points or points[-1] != last):
        points.append(last)
    peaks={}
    with db_connect() as con:
        saved=con.execute('SELECT payload FROM activity_telemetry WHERE activity_id=?',(int(identity),)).fetchone()
    if saved:
        try:
            samples=json.loads(zlib.decompress(saved[0]))
            for name,index in (('speed',3),('cadence',6)):
                candidates=[(i,r) for i,r in enumerate(samples)
                    if len(r)>index and type(r[index]) in (int,float) and math.isfinite(r[index]) and r[index]>=0
                    and len(r)>2 and all(type(x) in (int,float) and math.isfinite(x) for x in r[:3])
                    and -90<=r[1]<=90 and -180<=r[2]<=180]
                if candidates:
                    i,peak=max(candidates,key=lambda pair:pair[1][index])
                    peaks[name]={'sample_index':i,'value':peak[index],'timestamp':peak[0],
                                 'position':[round(peak[1],6),round(peak[2],6)]}
        except (ValueError,TypeError,IndexError,zlib.error):pass
    flagged, approved, prefs = speed_review_snapshot()
    return {"peak_samples":peaks,"speed_review":{"active":bool(prefs['filter_speed_anomalies'] or prefs['filter_speed_smart']),
            "excluded":row[0] in flagged and row[0] not in approved,"approved":row[0] in approved,
            "reasons":flagged.get(row[0], [])},
            "id":row[0],"name":row[1],"sport":row[2],"day":row[3],
            "distance_m":row[4],"moving_seconds":row[5],"elapsed_seconds":row[6],
            "elevation_m":row[7],"bike":row[8],"avg_heart_rate":row[9],
            "avg_speed":row[10],"max_speed":row[11],"avg_power":row[18],
            **dict(zip(ADV_NUM_FIELDS,list(row[24:24+len(ADV_NUM_FIELDS)]))),"weather_condition":row[24+len(ADV_NUM_FIELDS)],
            "filename":row[19],"moving_source":row[20],"elevation_source":row[21],
            "reported_distance_m":row[22],"gps_distance_m":row[23],"point_count":row[13],
            "bounds":[row[14],row[15],row[16],row[17]],"points":points}



def cached_projected_track_with_chunks(activity_id, compressed, epoch, con=None, save_projection=True):
    global TRACK_CACHE_BYTES
    cache_key=(epoch,activity_id)
    with STATE_LOCK:
        found=TRACK_CACHE.get(cache_key)
        if found is not None:
            TRACK_CACHE.move_to_end(cache_key)
            return found
    source_digest=hashlib.blake2b(compressed,digest_size=12).hexdigest()
    if con is not None:
        try:
            row=con.execute('SELECT payload FROM heatmap_track_cache WHERE activity_id=? AND source_digest=?',(activity_id,source_digest)).fetchone()
            if row is not None and len(row[0])<8*1024*1024:
                decoder=zlib.decompressobj()
                raw=decoder.decompress(row[0],16*1024*1024+1)
                if len(raw)<=16*1024*1024 and decoder.eof and not decoder.unconsumed_tail:
                    coordinate_bytes,saved_chunks=marshal.loads(raw)
                    if isinstance(coordinate_bytes,bytes) and len(coordinate_bytes)%16==0 and isinstance(saved_chunks,list) and len(saved_chunks)<=100000:
                        restored=array('d');restored.frombytes(coordinate_bytes)
                        value=(restored,saved_chunks)
                        size=len(restored)*8+len(saved_chunks)*72
                        if size<=MAX_TRACK_CACHE_BYTES:
                            with STATE_LOCK:
                                while TRACK_CACHE and TRACK_CACHE_BYTES+size>MAX_TRACK_CACHE_BYTES:
                                    _,stale=TRACK_CACHE.popitem(last=False)
                                    TRACK_CACHE_BYTES-=len(stale[0])*8+len(stale[1])*72
                                TRACK_CACHE[cache_key]=value
                                TRACK_CACHE_BYTES+=size
                            return value
        except (sqlite3.Error,ValueError,TypeError,EOFError,zlib.error,OverflowError):
            pass
    coords=array('d')
    append=coords.append
    for point in iter_coordinates(compressed):
        if point is None:
            append(float('nan'));append(float('nan'))
        else:
            lat,lon=point
            a=math.radians(max(-85.0511,min(85.0511,lat)))
            append((lon+180.0)*(256.0/360.0))
            append((1.0-math.asinh(math.tan(a))/math.pi)*128.0)
    chunks=[]
    count=len(coords)//2
    for start in range(0,count,128):
        end=min(start+128,count)
        first=max(0,start-1)
        xs=[coords[2*j] for j in range(first,end) if coords[2*j]==coords[2*j]]
        ys=[coords[2*j+1] for j in range(first,end) if coords[2*j+1]==coords[2*j+1]]
        if xs:
            chunks.append((first*2,end*2,min(xs),min(ys),max(xs),max(ys)))
    size=len(coords)*8+len(chunks)*72
    value=(coords,chunks)
    if con is not None and save_projection and size<=8*1024*1024:
        try:
            payload=zlib.compress(marshal.dumps((coords.tobytes(),chunks)),1)
            if len(payload)<8*1024*1024:
                con.execute('INSERT OR REPLACE INTO heatmap_track_cache (activity_id,source_digest,payload) VALUES (?,?,?)',(activity_id,source_digest,payload))
        except (sqlite3.Error,ValueError,OverflowError,MemoryError):
            pass
    if size<=MAX_TRACK_CACHE_BYTES:
        with STATE_LOCK:
            previous=TRACK_CACHE.get(cache_key)
            if previous is not None:
                TRACK_CACHE.move_to_end(cache_key)
                return previous
            while TRACK_CACHE and TRACK_CACHE_BYTES+size>MAX_TRACK_CACHE_BYTES:
                _,stale=TRACK_CACHE.popitem(last=False)
                TRACK_CACHE_BYTES-=len(stale[0])*8+len(stale[1])*72
            TRACK_CACHE[cache_key]=value
            TRACK_CACHE_BYTES+=size
    return value



def clear_render_caches(include_tracks=False):
    global TRACK_CACHE_BYTES, VIEW_CACHE_BYTES
    with STATE_LOCK:
        CACHE_STATE["epoch"] += 1
        VIEW_CACHE.clear()
        VIEW_CACHE_BYTES = 0
        if include_tracks:
            try:
                with db_connect() as con:
                    con.execute("DROP TABLE IF EXISTS heatmap_index_cache")
                    con.execute("DELETE FROM heatmap_track_cache")
                    con.execute("DELETE FROM heatmap_view_cache")
            except sqlite3.Error:
                pass
            TRACK_CACHE.clear()
            TRACK_CACHE_BYTES = 0


def _clip_segment(x0, y0, x1, y1, xmin, ymin, xmax, ymax):
    dx, dy = x1 - x0, y1 - y0
    start, end = 0.0, 1.0
    for p, q in ((-dx, x0 - xmin), (dx, xmax - x0), (-dy, y0 - ymin), (dy, ymax - y0)):
        if p == 0:
            if q < 0:
                return None
        else:
            t = q / p
            if p < 0:
                start = max(start, t)
            else:
                end = min(end, t)
            if start > end:
                return None
    return x0 + dx * start, y0 + dy * start, x0 + dx * end, y0 + dy * end

















def heatmap_view_fingerprint(con):
    hasher=hashlib.blake2b(digest_size=20)
    hasher.update(b'libre-heat-view-with-activity-visits-v3')
    for row in con.execute('SELECT id,name,sport,day,bike,west,south,east,north,point_count,LENGTH(coordinates) FROM activities ORDER BY id'):
        hasher.update(json.dumps(row,separators=(',',':')).encode('utf-8'))
    return hasher.hexdigest()


def read_persisted_view(key):
    try:
        digest=hashlib.sha256(key.encode('utf-8')).hexdigest()
        with db_connect() as con:
            fingerprint=heatmap_view_fingerprint(con)
            row=con.execute('SELECT fingerprint,digest,payload FROM heatmap_view_cache WHERE key=?',(digest,)).fetchone()
        if not row or row[0]!=fingerprint or len(row[2])>8*1024*1024 or hashlib.sha256(row[2]).hexdigest()!=row[1]:return None
        decoder=zlib.decompressobj()
        data=decoder.decompress(row[2],12*1024*1024+1)
        if len(data)>12*1024*1024 or decoder.unconsumed_tail or not decoder.eof:return None
        parsed=json.loads(data)
        if not isinstance(parsed,dict) or not {'z','step','segments','activities','peak','visitStep','visits'}<=parsed.keys():return None
        return data
    except (sqlite3.Error,ValueError,TypeError,zlib.error,OverflowError):
        return None


def persist_view(key,data,expected_epoch):
    if len(data)>12*1024*1024:return
    try:
        zipped=zlib.compress(data,1)
        if len(zipped)>8*1024*1024:return
        with STATE_LOCK:
            if CACHE_STATE['epoch']!=expected_epoch:return
        with db_connect() as con:
            fingerprint=heatmap_view_fingerprint(con)
            con.execute('INSERT OR REPLACE INTO heatmap_view_cache(key,fingerprint,digest,payload,used) VALUES (?,?,?,?,?)',
                (hashlib.sha256(key.encode('utf-8')).hexdigest(),fingerprint,hashlib.sha256(zipped).hexdigest(),zipped,int(time.time())))
            count,size=con.execute('SELECT COUNT(*),COALESCE(SUM(LENGTH(payload)),0) FROM heatmap_view_cache').fetchone()
            if count>128 or size>128*1024*1024:
                for cache_key,bytes_used in con.execute('SELECT key,LENGTH(payload) FROM heatmap_view_cache ORDER BY used,key').fetchall():
                    if count<=128 and size<=128*1024*1024:break
                    con.execute('DELETE FROM heatmap_view_cache WHERE key=?',(cache_key,))
                    count-=1;size-=bytes_used
    except (sqlite3.Error,ValueError,MemoryError,OverflowError):
        pass


def _heat_worker_start(db_path,cancel_flags):
    global DB_PATH, MAX_TRACK_CACHE_BYTES, HEAT_CANCEL_FLAGS
    DB_PATH=Path(db_path)
    HEAT_CANCEL_FLAGS=cancel_flags
    MAX_TRACK_CACHE_BYTES=80*1024*1024


def _heat_worker_ready():
    return True


def _heat_worker_chunk(task):
    z,lo_x,hi_x,lo_y,hi_y,gscale,dscale,geom_step,ids,epoch,slot,ticket=task
    def superseded():
        return HEAT_CANCEL_FLAGS[slot]!=ticket
    return _heat_accumulate(ids,z,lo_x,hi_x,lo_y,hi_y,gscale,dscale,geom_step,epoch,superseded,False)


def _heat_accumulate(ids,z,lo_x,hi_x,lo_y,hi_y,gscale,dscale,geom_step,epoch,cancelled,save_projection=True):
    if not ids:return set(),{},0
    paths=set();counts={};selected=0
    with db_connect() as con:
        for activity_id,compressed in con.execute('SELECT id,coordinates FROM activities WHERE id IN ('+','.join('?' for _ in ids)+')',ids):
            if cancelled():raise ViewCancelled()
            selected+=1
            coords,chunks=cached_projected_track_with_chunks(activity_id,compressed,epoch,con,save_projection=save_projection)
            visited=set()
            for chunk_start,chunk_end,cxmin,cymin,cxmax,cymax in chunks:
                if cxmax<lo_x or cxmin>hi_x or cymax<lo_y or cymin>hi_y:
                    continue
                previous=None
                for i in range(chunk_start,chunk_end,2):
                    x,y=coords[i],coords[i+1]
                    if x!=x:
                        previous=None
                        continue
                    dg=(round(x*dscale),round(y*dscale))
                    gg=(round(x*gscale),round(y*gscale))
                    if previous is not None:
                        px,py,old_d,old_g=previous
                        if z<=12 and dg==old_d and gg==old_g and lo_x+.01<x<hi_x-.01 and lo_y+.01<y<hi_y-.01 and lo_x+.01<px<hi_x-.01 and lo_y+.01<py<hi_y-.01:
                            visited.add(dg)
                            continue
                        if not(max(px,x)<lo_x or min(px,x)>hi_x or max(py,y)<lo_y or min(py,y)>hi_y):
                            if lo_x<=px<=hi_x and lo_x<=x<=hi_x and lo_y<=py<=hi_y and lo_y<=y<=hi_y:
                                da,db=old_d,dg
                                ga,gb=old_g,gg
                            else:
                                clipped=_clip_segment(px,py,x,y,lo_x,lo_y,hi_x,hi_y)
                                if clipped is None:
                                    previous=(x,y,dg,gg);continue
                                ax,ay,bx,by=clipped
                                da=(round(ax*dscale),round(ay*dscale));db=(round(bx*dscale),round(by*dscale))
                                ga=(round(ax*gscale),round(ay*gscale));gb=(round(bx*gscale),round(by*gscale))
                            visited.add(da);visited.add(db)
                            dsteps=max(abs(db[0]-da[0]),abs(db[1]-da[1]))
                            if dsteps>2:
                                dcx,dcy=db[0]-da[0],db[1]-da[1]
                                sx,sy=2.0*dcx/dsteps,2.0*dcy/dsteps
                                pxv,pyv=sx,sy
                                for _ in range(2,dsteps,2):
                                    visited.add((da[0]+round(pxv),da[1]+round(pyv)))
                                    pxv+=sx;pyv+=sy
                            if ga!=gb:
                                span=max(abs(gb[0]-ga[0]),abs(gb[1]-ga[1]))
                                pieces=max(1,math.ceil(span*geom_step/24.0))
                                if pieces==1:
                                    a,b=(ga,gb) if ga<gb else (gb,ga)
                                    paths.add((a[0],a[1],b[0],b[1]))
                                else:
                                    ox,oy=ga
                                    for k in range(1,pieces+1):
                                        ex=round(ga[0]+(gb[0]-ga[0])*k/pieces)
                                        ey=round(ga[1]+(gb[1]-ga[1])*k/pieces)
                                        if (ex,ey)!=(ox,oy):
                                            a,b=((ox,oy),(ex,ey)) if (ox,oy)<(ex,ey) else ((ex,ey),(ox,oy))
                                            paths.add((a[0],a[1],b[0],b[1]))
                                        ox,oy=ex,ey
                    previous=(x,y,dg,gg)
            for c in visited:
                counts[c]=counts.get(c,0)+1
    return paths,counts,selected


def _heat_session_slot(session):
    if not session:return 0
    return (int.from_bytes(hashlib.blake2b(session.encode(),digest_size=4).digest(),'big')%1023)+1


def _heat_executor():
    global HEAT_WORKERS, HEAT_CANCEL_FLAGS
    if HEAT_WORKERS is not None:return HEAT_WORKERS
    with HEAT_WORKERS_LOCK:
        if HEAT_WORKERS is None:
            workers=min(4,max(2,os.cpu_count() or 2))
            HEAT_CANCEL_FLAGS=multiprocessing.RawArray("Q",1024)
            HEAT_WORKERS=ProcessPoolExecutor(max_workers=workers,mp_context=multiprocessing.get_context("spawn"),initializer=_heat_worker_start,initargs=(str(DB_PATH),HEAT_CANCEL_FLAGS))
    return HEAT_WORKERS

def warm_heat_workers():
    if HEAT_PARALLEL_DISABLED or HEAT_WORKERS is not None:return
    try:
        with db_connect() as con:
            count,points=con.execute('SELECT COUNT(*),COALESCE(SUM(point_count),0) FROM activities').fetchone()
        if count<100 or points<350000:return
        executor=_heat_executor()
        for _ in range(min(4,max(2,os.cpu_count() or 2))):
            executor.submit(_heat_worker_ready)
    except Exception as error:
        print('Map worker warmup skipped:',error,file=sys.stderr)


def start_heat_warmup():
    if not HEAT_PARALLEL_DISABLED and HEAT_WORKERS is None:
        threading.Thread(target=warm_heat_workers,daemon=True).start()


def create_view(params,cancelled=lambda:False):
    global VIEW_CACHE_BYTES, HEAT_WORKERS, HEAT_PARALLEL_DISABLED
    key=json.dumps(params,sort_keys=True,separators=(',',':'))
    with STATE_LOCK:
        if key in VIEW_CACHE:
            VIEW_CACHE.move_to_end(key)
            return VIEW_CACHE[key]
        epoch=CACHE_STATE['epoch']
    sql,args=filter_query(params,True)
    saved=read_persisted_view(key)
    if saved is not None and not cancelled():
        with STATE_LOCK:
            if CACHE_STATE['epoch']==epoch and len(saved)<=MAX_VIEW_CACHE_BYTES:
                while VIEW_CACHE and (len(VIEW_CACHE)>=12 or VIEW_CACHE_BYTES+len(saved)>MAX_VIEW_CACHE_BYTES):
                    _,stale=VIEW_CACHE.popitem(last=False);VIEW_CACHE_BYTES-=len(stale)
                VIEW_CACHE[key]=saved;VIEW_CACHE_BYTES+=len(saved)
        return saved
    z=max(0,min(19,int(float(params.get('z',['4'])[0]))))
    scale=2**z
    west,south,east,north=[float(params[n][0]) for n in ('west','south','east','north')]
    x0,y0=project_xy(north,west,z)
    x1,y1=project_xy(south,east,z)
    left,right=min(x0,x1)-48,max(x0,x1)+48
    top,bottom=min(y0,y1)-48,max(y0,y1)+48
    lo_x,hi_x=left/scale,right/scale
    lo_y,hi_y=top/scale,bottom/scale
    geom_step=1.1 if z>=13 else 1.35
    density_step=6.5 if z>=13 else 7.5
    gscale=scale/geom_step
    dscale=scale/density_step
    with db_connect() as con:
        activity_rows=con.execute('SELECT id,point_count FROM activities'+sql,args).fetchall()
    ids=[r[0] for r in activity_rows]
    point_total=sum(r[1] for r in activity_rows)
    selected=len(ids)
    paths=set();counts={}
    if len(ids)<100 or point_total<350000 or HEAT_PARALLEL_DISABLED or os.environ.get('LIBREHEATMAPS_SINGLE_CORE')=='1':
        paths,counts,_=_heat_accumulate(ids,z,lo_x,hi_x,lo_y,hi_y,gscale,dscale,geom_step,epoch,cancelled)
    else:
        workers=min(4,max(2,os.cpu_count() or 2))
        batches=[ids[i::workers] for i in range(workers)]
        try:
            executor=_heat_executor()
            session=getattr(cancelled,'heat_session','')
            slot=_heat_session_slot(session)
            with HEAT_CANCEL_LOCK:
                HEAT_CANCEL_FLAGS[slot]=(HEAT_CANCEL_FLAGS[slot]+1)&0xffffffffffffffff
                ticket=HEAT_CANCEL_FLAGS[slot]
            futures=[executor.submit(_heat_worker_chunk,(z,lo_x,hi_x,lo_y,hi_y,gscale,dscale,geom_step,batch,epoch,slot,ticket)) for batch in batches if batch]
            pending=set(futures)
            while pending:
                if cancelled():
                    for future in pending:future.cancel()
                    raise ViewCancelled()
                finished,pending=wait(pending,timeout=0.06,return_when=FIRST_COMPLETED)
                for future in finished:
                    worker_paths,worker_counts,_=future.result()
                    paths.update(worker_paths)
                    for cell,n in worker_counts.items():
                        counts[cell]=counts.get(cell,0)+n
        except ViewCancelled:
            raise
        except Exception as error:
            print('Multicore map rendering unavailable, using local rendering:',error,file=sys.stderr)
            with HEAT_WORKERS_LOCK:
                HEAT_PARALLEL_DISABLED=True
                if HEAT_WORKERS is not None:
                    HEAT_WORKERS.shutdown(wait=False,cancel_futures=True)
                    HEAT_WORKERS=None
            paths,counts,_=_heat_accumulate(ids,z,lo_x,hi_x,lo_y,hi_y,gscale,dscale,geom_step,epoch,cancelled)
    neighborhood={}
    def nearby_peak(cx,cy):
        key=(cx,cy)
        value=neighborhood.get(key)
        if value is None:
            value=max(counts.get((cx+dx,cy+dy),0)
                      for dx in (-1,0,1) for dy in (-1,0,1))
            neighborhood[key]=value
        return value
    def smooth_visits(gx,gy):
        cx,cy=math.floor(gx),math.floor(gy)
        tx,ty=gx-cx,gy-cy
        a=nearby_peak(cx,cy)*(1-tx)+nearby_peak(cx+1,cy)*tx
        b=nearby_peak(cx,cy+1)*(1-tx)+nearby_peak(cx+1,cy+1)*tx
        return round(a*(1-ty)+b*ty,4)
    levels=[]
    factor=geom_step/density_step
    for ax,ay,bx,by in sorted(paths):
        start_visit=smooth_visits(ax*factor,ay*factor)
        end_visit=smooth_visits(bx*factor,by*factor)
        levels.append([ax,ay,bx,by,start_visit,end_visit])
    peak=max(counts.values(),default=0)
    data={'step':geom_step,'z':z,'segments':levels,'activities':selected,'peak':peak,
          'visitStep':density_step,'visits':[[x,y,n] for (x,y),n in sorted(counts.items())]}
    encoded=json.dumps(data,separators=(',',':')).encode()
    with STATE_LOCK:
        if CACHE_STATE['epoch']==epoch and len(encoded)<=MAX_VIEW_CACHE_BYTES:
            while VIEW_CACHE and (len(VIEW_CACHE)>=12 or VIEW_CACHE_BYTES +len(encoded)>MAX_VIEW_CACHE_BYTES):
                _,stale=VIEW_CACHE.popitem(last=False);VIEW_CACHE_BYTES-=len(stale)
            VIEW_CACHE[key]=encoded;VIEW_CACHE_BYTES+=len(encoded)
    if not cancelled():persist_view(key,encoded,epoch)
    return encoded



 
 
def place_lens(params):
    try:
        lat=float(params.get('lat',[''])[0]);lon=float(params.get('lon',[''])[0]);radius=float(params.get('radius_m',['250'])[0])
    except (TypeError,ValueError,OverflowError):
        raise ValueError('Invalid location or search radius')
    if not (math.isfinite(lat) and math.isfinite(lon) and math.isfinite(radius)) or not (-85<=lat<=85 and -180<=lon<=180 and 75<=radius<=1000):
        raise ValueError('Place search requires valid coordinates and a 75–1000 m radius')
    where,args=filter_query(params)
     
    lat_step=radius/110574.0
    lon_step=radius/max(1000.0,111320.0*math.cos(math.radians(lat)))
    south,north=lat-lat_step,lat+lat_step
    if lon-lon_step<-180:
        box='(east>=? OR west<=?)'; box_args=[lon-lon_step+360,lon+lon_step]
    elif lon+lon_step>180:
        box='(east>=? OR west<=?)'; box_args=[lon-lon_step,lon+lon_step-360]
    else:
        box='east>=? AND west<=?';box_args=[lon-lon_step,lon+lon_step]
    where+=(' AND ' if where else ' WHERE ')+'north>=? AND south<=? AND ('+box+')'
    query_args=args+[south,north]+box_args
    scan_cap=300; point_cap=1_800_000
    with db_connect() as con:
        candidate_total=con.execute('SELECT COUNT(*) FROM activities'+where,query_args).fetchone()[0]
        rows=con.execute('SELECT id,name,sport,day,COALESCE(recorded_distance_m,distance_m),coordinates FROM activities'+where+' ORDER BY day DESC,id DESC LIMIT ?',query_args+[scan_cap]).fetchall()
    cos_lat=math.cos(math.radians(lat));r2=radius*radius
    matches=[];points_scanned=0;budget_exceeded=False
    def planar(coord):
        delta=((coord[1]-lon+180)%360)-180
        return delta*111320*cos_lat,(coord[0]-lat)*110574
    for activity_id,name,sport,day,distance,compressed in rows:
        nearest2=float('inf');previous=None;found=False
        for coord in iter_coordinates(compressed):
            points_scanned+=1
            if points_scanned>point_cap:
                budget_exceeded=True;break
            if coord is None:
                previous=None;continue
            x,y=planar(coord);d2=x*x+y*y
            if previous is not None:
                ax,ay=previous;dx=x-ax;dy=y-ay;length=dx*dx+dy*dy
                if length>0:
                    t=max(0.,min(1.,-(ax*dx+ay*dy)/length))
                    dx=ax+t*dx;dy=ay+t*dy
                    d2=min(d2,dx*dx+dy*dy)
            nearest2=min(nearest2,d2)
            if nearest2<=r2:
                found=True;break
            previous=(x,y)
        if found:
            matches.append({'id':activity_id,'name':name,'sport':sport or 'Unknown','day':day,
                            'distance_m':distance,'nearest_m':round(math.sqrt(nearest2))})
        if budget_exceeded:break
    dated=[a['day'] for a in matches if a['day']]
     
     
    month_counts=Counter(day[:7] for day in dated
                         if isinstance(day,str) and re.match(r'^\d{4}-(?:0[1-9]|1[0-2])(?:-|$)',day))
    limited=(candidate_total>len(rows) or budget_exceeded)
    return {'latitude':round(lat,6),'longitude':round(lon,6),'radius_m':int(radius),
            'matched_activities':len(matches),'candidate_activities':candidate_total,
            'scanned_activities':len(rows) if not budget_exceeded else None,
            'limited':limited,'first_visit':min(dated) if dated else None,'last_visit':max(dated) if dated else None,
            'activities':matches[:24], 'year_counts':dict(sorted(Counter(day[:4] for day in dated).items())), 'month_counts':dict(sorted(month_counts.items())), 'point_budget_reached':budget_exceeded,
            'method':'GPS track proximity, not device-location accuracy'}

def timeline_summary(params=None):
    where,args=filter_query({'focus':(params or {}).get('focus',['all'])})
    where+=(' AND ' if where else ' WHERE ')+"day IS NOT NULL AND length(day)>=4"
    with db_connect() as con:
        rows=con.execute("SELECT substr(day,1,4),COUNT(*),SUM(COALESCE(recorded_distance_m,distance_m)),SUM(COALESCE(moving_seconds,0)) FROM activities"+where+" GROUP BY substr(day,1,4) ORDER BY 1",args).fetchall()
    with db_connect() as con:
        months=con.execute("SELECT substr(day,1,7),COUNT(*) FROM activities"+where+" AND length(day)>=7 GROUP BY substr(day,1,7) ORDER BY 1",args).fetchall()
    return {'years':[{'year':int(y),'activities':n,'distance_m':d or 0,'moving_seconds':t or 0} for y,n,d,t in rows if y and y.isdigit()],
            'months':[{'month':m,'activities':n} for m,n in months if len(m)==7 and m[4]=='-' and m[:4].isdigit() and m[5:].isdigit() and 1<=int(m[5:])<=12]}


def compare_options(params):
    query=params.get('q',[''])[0].strip()[:100]
    direction=params.get('order',['newest'])[0]
    if direction not in ('newest','oldest'):
        raise ValueError('Invalid comparison sort order')
    try:
        offset=int(params.get('offset',['0'])[0])
    except (ValueError,TypeError):
        raise ValueError('Invalid comparison offset')
    if offset<0 or offset>1000000:
        raise ValueError('Invalid comparison offset')
    where,args=filter_query({'focus':params.get('focus',['all'])})
    if query:
        term='%'+query.replace('\\','\\\\').replace('%','\\%').replace('_','\\_')+'%'
        where+=(' AND ' if where else ' WHERE ')+"(name LIKE ? ESCAPE '\\' OR day LIKE ? ESCAPE '\\')"
        args.extend((term,term))
    order='day DESC,id DESC' if direction=='newest' else '(day IS NULL),day ASC,id ASC'
    with db_connect() as con:
        total=con.execute('SELECT COUNT(*) FROM activities'+where,args).fetchone()[0]
        rows=con.execute('SELECT id,name,day,COALESCE(recorded_distance_m,distance_m),sport FROM activities'+where+' ORDER BY '+order+' LIMIT 80 OFFSET ?',args+[offset]).fetchall()
    return {'rows':[{'id':r[0],'name':r[1],'day':r[2],'distance_m':r[3],'sport':r[4]} for r in rows],
            'total':total,'has_more':offset+len(rows)<total}



def duplicate_library_scan():
    import bisect
    with STATE_LOCK:
        if JOB['status']=='running':
            raise ValueError('Finish the current import before reviewing duplicates')
        with db_connect() as con:
            total=con.execute('SELECT COUNT(*) FROM activities').fetchone()[0]
            if total>30000:
                rows=[]
            else:
                rows=con.execute("SELECT a.id,a.name,a.day,a.sport,a.filename,a.distance_m,a.point_count,a.moving_seconds,"
                             "a.recorded_distance_m,a.bike,t.payload,t.sample_count "
                             "FROM activities a JOIN activity_telemetry t ON a.id=t.activity_id ORDER BY a.id").fetchall()
            archived=[{'id':a,'original_id':o,'kept_id':k,'archived_at':day,'name':name}
                      for a,o,k,day,name in con.execute("SELECT archive_id,original_id,kept_id,archived_at,json_extract(metadata,'$.name') FROM archived_duplicates ORDER BY archive_id DESC")]
    prepared=[]
    for record in rows:
        identity,name,day,sport,filename,distance,points,moving,reported,bike,payload,count=record
        if not distance or distance<1000 or not day or count<8:
            continue
        try:
            samples=json.loads(zlib.decompress(payload))
            gps=[(float(r[0]),float(r[1]),float(r[2])) for r in samples if len(r)>=3 and all(isinstance(v,(int,float)) and math.isfinite(v) for v in r[:3])]
            if len(gps)<8 or not 30<=gps[-1][0]-gps[0][0]<=7*86400:
                continue
            times=[r[0] for r in gps]
            if times!=sorted(times):
                continue
            checkpoints=[]
            for k in range(11):
                timestamp=gps[0][0]+(gps[-1][0]-gps[0][0])*k/10
                index=bisect.bisect_left(times,timestamp)
                index=min(len(gps)-1,max(0,index))
                if index and abs(times[index-1]-timestamp)<abs(times[index]-timestamp):index-=1
                checkpoints.append(gps[index][1:])
            richness=sum(any(len(r)>k and r[k] is not None for r in samples) for k in range(3,9))
            prepared.append({'id':identity,'name':name,'day':day,'sport':sport,'filename':filename,
                             'distance_m':distance,'points':points,'moving_seconds':moving,'reported':reported,
                             'bike':bike,'start':gps[0][0],'end':gps[-1][0],'checkpoints':checkpoints,
                             'telemetry_count':count,'richness':richness})
        except (ValueError,TypeError,IndexError,OverflowError,zlib.error):
            continue
    prepared.sort(key=lambda r:r['start'])
    matches=[]
    for i,item in enumerate(prepared):
        for j in range(i+1,len(prepared)):
            other=prepared[j]
            if other['start']-item['start']>120:break
            if abs(item['end']-other['end'])>120:continue
            tolerance=max(60,item['distance_m']*.03)
            if abs(item['distance_m']-other['distance_m'])>tolerance:continue
            if item['sport'] and other['sport'] and item['sport'].casefold()!='unknown' and other['sport'].casefold()!='unknown':
                a=item['sport'].casefold();b=other['sport'].casefold()
                cycling=lambda v:any(n in v for n in ('ride','cycl','bik'))
                if cycling(a)!=cycling(b):continue
            distances=[haversine(a,b) for a,b in zip(item['checkpoints'],other['checkpoints'])]
            if distances[0]>80 or distances[-1]>80 or max(distances)>260 or sum(d<=115 for d in distances)<9:
                continue
            if sorted(distances)[len(distances)//2]>75:continue
            left={k:v for k,v in item.items() if k not in ('start','end','checkpoints')}
            right={k:v for k,v in other.items() if k not in ('start','end','checkpoints')}
            matches.append({'first':left,'second':right,'max_offset_seconds':round(max(abs(item['start']-other['start']),abs(item['end']-other['end']))),
                            'median_route_offset_m':round(sorted(distances)[len(distances)//2])})
            if len(matches)>=250:break
        if len(matches)>=250:break
    with db_connect() as con: combined_sources=source_version_review(con)
    return {'pairs':matches,'archived':archived,'combined_sources':combined_sources,'activity_count':total,'truncated':len(matches)>=250,
            'compared':len(prepared),'warning':'This scan supports 30,000 activities at a time; archived items remain restorable.' if total>30000 else '',
            'message':'Only very close timestamped GPS recordings are suggested. Inspect each pair before archiving.'}


def duplicate_library_action(action):
    if isinstance(action,dict) and action.get('action')=='choose_sources':return choose_activity_sources(action)
    if not isinstance(action,dict) or action.get('action') not in ('archive','restore'):
        raise ValueError('Invalid duplicate action')
    with STATE_LOCK:
        if JOB['status']=='running':raise ValueError('Finish the import before changing the library')
        if action['action']=='archive':
            if set(action)!={'action','keep_id','remove_id'}:raise ValueError('Invalid archive request')
            keep,remove=action['keep_id'],action['remove_id']
            if type(keep)!=int or type(remove)!=int or keep<=0 or remove<=0 or keep==remove:
                raise ValueError('Select two different activities')
            verified=False
            for pair in duplicate_library_scan()['pairs']:
                if {pair['first']['id'],pair['second']['id']}=={keep,remove}:verified=True;break
            if not verified:raise ValueError('The recordings no longer meet the strict duplicate checks. No changes made')
            with db_connect() as con:
                con.execute('BEGIN IMMEDIATE')
                con.row_factory=sqlite3.Row
                original=con.execute('SELECT * FROM activities WHERE id=?',(remove,)).fetchone()
                retained=con.execute('SELECT 1 FROM activities WHERE id=?',(keep,)).fetchone()
                if not original or not retained:raise ValueError('Activity changed; please scan again')
                if con.execute('SELECT 1 FROM activity_overrides WHERE activity_id=?',(remove,)).fetchone() or con.execute('SELECT 1 FROM activity_route_repairs WHERE activity_id=?',(remove,)).fetchone():
                    raise ValueError('This recording has reviewed edits. Restore the original details and GPS track before archiving it as a duplicate')
                seed_source_version(con,keep)
                seed_source_version(con,remove)
                raw=dict(original)
                coords=raw.pop('coordinates')
                telemetry=con.execute('SELECT payload,sample_count FROM activity_telemetry WHERE activity_id=?',(remove,)).fetchone()
                speed=con.execute('SELECT included FROM speed_filter_exceptions WHERE activity_id=?',(remove,)).fetchone()
                cur=con.execute('INSERT INTO archived_duplicates (original_id,kept_id,archived_at,metadata,coordinates,telemetry,telemetry_samples,speed_exception) VALUES(?,?,?,?,?,?,?,?)',
                    (remove,keep,dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds'),json.dumps(raw,separators=(',',':')),coords,telemetry[0] if telemetry else None,telemetry[1] if telemetry else None,speed[0] if speed else None))
                con.execute('DELETE FROM activity_telemetry WHERE activity_id=?',(remove,))
                con.execute('DELETE FROM speed_filter_exceptions WHERE activity_id=?',(remove,))
                con.execute('DELETE FROM heatmap_track_cache WHERE activity_id=?',(remove,))
                for row in con.execute('SELECT source_key,label,provider,fields_json,coordinates,route_stats,telemetry,sample_count FROM activity_source_versions WHERE activity_id=?',(remove,)).fetchall():
                    con.execute('INSERT OR IGNORE INTO activity_source_versions(activity_id,source_key,label,provider,fields_json,coordinates,route_stats,telemetry,sample_count) VALUES(?,?,?,?,?,?,?,?,?)',
                                (keep,)+tuple(row))
                con.execute('DELETE FROM activity_source_versions WHERE activity_id=?',(remove,))
                con.execute('DELETE FROM activity_source_choices WHERE activity_id=?',(remove,))
                con.execute('DELETE FROM activity_source_baselines WHERE activity_id=?',(remove,))
                apply_global_source_preferences(con,keep)
                con.execute('DELETE FROM activities WHERE id=?',(remove,))
                archive_id=cur.lastrowid
            clear_render_caches()
            return {'ok':True,'archived_id':archive_id,'remaining':keep}
        if set(action)!={'action','archive_id'} or type(action['archive_id'])!=int or action['archive_id']<=0:
            raise ValueError('Invalid restoration request')
        with db_connect() as con:
            con.execute('BEGIN IMMEDIATE')
            row=con.execute('SELECT original_id,metadata,coordinates,telemetry,telemetry_samples,speed_exception FROM archived_duplicates WHERE archive_id=?',(action['archive_id'],)).fetchone()
            if not row:raise ValueError('Archived recording not found')
            original,metadata,coords,telemetry,count,speed=row
            values=json.loads(metadata)
            values['coordinates']=coords
            if con.execute('SELECT 1 FROM activities WHERE unique_key=?',(values['unique_key'],)).fetchone():
                raise ValueError('This source is already imported; no changes made')
            if con.execute('SELECT 1 FROM activities WHERE id=?',(original,)).fetchone():
                values.pop('id',None)
            columns=list(values)
            cursor=con.execute('INSERT INTO activities ('+','.join(columns)+') VALUES ('+','.join('?' for _ in columns)+')',tuple(values.values()))
            restored=values.get('id',cursor.lastrowid)
            if telemetry is not None:
                con.execute('INSERT INTO activity_telemetry(activity_id,payload,sample_count) VALUES(?,?,?)',(restored,telemetry,count))
            if speed is not None:
                con.execute('INSERT INTO speed_filter_exceptions(activity_id,included) VALUES(?,?)',(restored,speed))
            con.execute('DELETE FROM archived_duplicates WHERE archive_id=?',(action['archive_id'],))
        clear_render_caches()
        return {'ok':True,'restored_id':restored}

def ride_telemetry(params):
    identity=params.get('id',[''])[0]
    if not identity.isascii() or not identity.isdecimal() or len(identity)>12 or int(identity)<=0:raise ValueError('Invalid activity ID')
    with db_connect() as con:
        row=con.execute('SELECT sample_count,payload FROM activity_telemetry WHERE activity_id=?',(int(identity),)).fetchone()
    if row is None:return {'samples':[],'count':0,'available':[],'message':'Reimport the original FIT, GPX or TCX file to add a timestamped ride trace where available.'}
    samples=json.loads(zlib.decompress(row[1]))
    if len(samples)>8000:raise ValueError('Telemetry limit exceeded')
    fields=('time','lat','lon','speed_mps','heart_rate_bpm','power_w','cadence_rpm','temp_c','altitude_m')
    available=[fields[i] for i in range(3,9) if any(x[i] is not None for x in samples)]
    return {'samples':samples,'count':row[0],'available':available,'fields':fields}


def yearly_review(params):
    year=params.get('year',[''])[0]
    if len(year)!=4 or not year.isascii() or not year.isdecimal() or not 1980<=int(year)<=2200:raise ValueError('Select a valid year')
    where,args=filter_query({'focus':params.get('focus',['all'])})
    where+=(' AND ' if where else ' WHERE ')+'day>=? AND day<?'
    args.extend((year,str(int(year)+1)))
    with db_connect() as con:
        rows=con.execute('SELECT id,name,day,COALESCE(recorded_distance_m,distance_m),moving_seconds,elevation_m,bike,sport FROM activities'+where+' ORDER BY day,id',args).fetchall()
    if not rows:return {'year':int(year),'activities':0}
    from collections import Counter
    bikes=Counter(r[6] for r in rows if r[6]);months=Counter(r[2][:7] for r in rows if r[2]);best=max(rows,key=lambda r:r[3] or 0)
    return {'year':int(year),'activities':len(rows),'distance_m':sum(r[3] or 0 for r in rows),'moving_seconds':sum(r[4] or 0 for r in rows),'elevation_m':sum(r[5] or 0 for r in rows),'active_days':len({r[2] for r in rows if r[2]}),'longest':{'id':best[0],'name':best[1],'day':best[2],'distance_m':best[3]},'top_bike':bikes.most_common(1)[0][0] if bikes else None,'top_month':months.most_common(1)[0][0] if months else None,'months':[{'month':m,'rides':n} for m,n in sorted(months.items())]}



def library_work_file(prefix, suffix):
    fd, name = tempfile.mkstemp(prefix=prefix, suffix=suffix, dir=str(DB_PATH.parent))
    os.close(fd)
    return Path(name)


def remove_library_work_file(path):
    for suffix in ('', '-wal', '-shm'):
        Path(str(path) + suffix).unlink(missing_ok=True)


def make_library_backup():
    with STATE_LOCK:
        if JOB['status'] == 'running':
            raise ValueError('Finish importing before backing up the library')
        snapshot = library_work_file('.libreheatmaps-library-', '.sqlite3')
        destination = None
        complete = False
        try:
            destination = library_work_file('.libreheatmaps-backup-', '.zip')
            with closing(db_connect()) as source, closing(sqlite3.connect(str(snapshot), timeout=40)) as target:
                source.backup(target, pages=256, sleep=0.05)
                target.commit()
            with closing(sqlite3.connect(str(snapshot), timeout=40)) as check:
                if check.execute('PRAGMA integrity_check').fetchone()[0] != 'ok':
                    raise ValueError('Library database integrity check failed')
                count = check.execute('SELECT COUNT(*) FROM activities').fetchone()[0]
            digest = hashlib.sha256()
            with snapshot.open('rb') as raw:
                for block in iter(lambda: raw.read(1024 * 1024), b''):
                    digest.update(block)
            manifest = {'format':'LibreHeatmaps-library-v1','created_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'version':VERSION,'activities':count,'database_sha256':digest.hexdigest()}
            with zipfile.ZipFile(destination, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=6, allowZip64=True) as archive:
                archive.writestr('manifest.json', json.dumps(manifest, separators=(',',':')))
                archive.write(snapshot, 'activities.sqlite3')
            with zipfile.ZipFile(destination) as archive:
                if archive.testzip() is not None:
                    raise ValueError('Library backup ZIP did not pass its integrity check')
            complete = True
            return str(destination)
        finally:
            remove_library_work_file(snapshot)
            if not complete and destination is not None:
                remove_library_work_file(destination)


def inspect_library_backup(path):
    snapshot = library_work_file('.libreheatmaps-verified-', '.sqlite3')
    success = False
    try:
        with zipfile.ZipFile(path) as archive:
            if sorted(archive.namelist()) != ['activities.sqlite3', 'manifest.json']:
                raise ValueError('Not a LibreHeatmaps library backup')
            info = archive.getinfo('manifest.json')
            if info.file_size > 65536:
                raise ValueError('Backup manifest is too large')
            metadata = json.loads(archive.read(info))
            if not isinstance(metadata, dict) or metadata.get('format') != 'LibreHeatmaps-library-v1':
                raise ValueError('Unsupported library backup format')
            member = archive.getinfo('activities.sqlite3')
            if member.file_size > 8 * 1024**3 or member.file_size < 1024:
                raise ValueError('Backup database exceeds safety limits')
            if member.file_size > max(1024**2, member.compress_size * 1000):
                raise ValueError('Backup database compression exceeds safety limits')
            digest = hashlib.sha256()
            with archive.open(member) as source, snapshot.open('wb') as output:
                for block in iter(lambda: source.read(1024 * 1024), b''):
                    digest.update(block)
                    output.write(block)
                output.flush()
                os.fsync(output.fileno())
        if metadata.get('database_sha256') and not hmac.compare_digest(str(metadata['database_sha256']), digest.hexdigest()):
            raise ValueError('Backup database checksum does not match')
        with closing(sqlite3.connect(str(snapshot), timeout=40)) as check:
            if check.execute('PRAGMA integrity_check').fetchone()[0] != 'ok':
                raise ValueError('Backup database is damaged')
            tables = {row[0] for row in check.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if not {'activities', 'app_settings'}.issubset(tables):
                raise ValueError('Backup is missing required activity tables')
            count = check.execute('SELECT COUNT(*) FROM activities').fetchone()[0]
            if not isinstance(metadata.get('activities'), int) or metadata['activities'] != count:
                raise ValueError('Backup activity count does not match its manifest')
        success = True
        return snapshot, count
    finally:
        if not success:
            remove_library_work_file(snapshot)


def verify_library_backup(path):
    snapshot, count = inspect_library_backup(path)
    try:
        return {'status':'verified', 'activities':count, 'message':'Backup verified. Keep this ZIP in a safe place before deleting any activities.'}
    finally:
        remove_library_work_file(snapshot)


def restore_library_backup(path):
    with STATE_LOCK:
        if JOB['status'] == 'running':
            raise ValueError('Finish importing before restoring a library')
        snapshot, count = inspect_library_backup(path)
        rollback = None
        rollback_complete = False
        try:
            rollback = library_work_file('.libreheatmaps-restore-safety-', '.sqlite3')
            with closing(db_connect()) as source, closing(sqlite3.connect(str(rollback), timeout=40)) as target:
                source.backup(target, pages=256, sleep=0.05)
                target.commit()
            rollback_complete = True
            try:
                with closing(sqlite3.connect(str(snapshot), timeout=40)) as source, closing(db_connect()) as target:
                    source.backup(target, pages=256, sleep=0.05)
                    target.commit()
                init_db()
                clear_render_caches(include_tracks=True)
            except Exception as problem:
                try:
                    with closing(sqlite3.connect(str(rollback), timeout=40)) as source, closing(db_connect()) as target:
                        source.backup(target, pages=256, sleep=0.05)
                        target.commit()
                    clear_render_caches(include_tracks=True)
                except Exception as rollback_error:
                    rollback_complete = False
                    raise RuntimeError('Restore failed and automatic rollback failed. Keep the recovery database at {}. Restore error: {}; rollback error: {}'.format(rollback, problem, rollback_error)) from problem
                raise
            return {'status':'restored', 'activities':count}
        finally:
            remove_library_work_file(snapshot)
            if rollback is not None and rollback_complete:
                remove_library_work_file(rollback)


def export_gpx(handler, params):
    sql, args = filter_query(params)
    handler.send_response(200)
    handler.send_header('Content-Type','application/gpx+xml; charset=utf-8')
    handler.send_header('Content-Disposition','attachment; filename="LibreHeatmaps_routes.gpx"')
    handler.send_header('Cache-Control','no-store')
    handler.end_headers()
    handler.wfile.write(b'<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="LibreHeatmaps" xmlns="http://www.topografix.com/GPX/1/1">\n')
    with db_connect() as con:
        for name, coords in con.execute('SELECT name,coordinates FROM activities'+sql+' ORDER BY id',args):
            handler.wfile.write(('<trk><name>'+html.escape(name)+'</name>\n').encode())
            opened=False
            for point in iter_coordinates(coords):
                if point is None:
                    if opened:
                        handler.wfile.write(b'</trkseg>\n')
                        opened=False
                    continue
                if not opened:
                    handler.wfile.write(b'<trkseg>\n')
                    opened=True
                handler.wfile.write(('<trkpt lat="%.6f" lon="%.6f"/>\n'%point).encode('ascii'))
            if opened:handler.wfile.write(b'</trkseg>\n')
            handler.wfile.write(b'</trk>\n')
    handler.wfile.write(b'</gpx>\n')


